  ["_CeladonGymBattleText2"] = "喂！\f这里不许你进来！",
  ["_CeladonGymBattleText3"] = "我正觉得无聊呢。",
  ["_CeladonGymBattleText4"] = "你就是那个\n偷窥狂吧？",
  ["_CeladonGymBattleText5"] = "看看我的\n草属性宝可梦！\f它们可好养了！",
  ["_CeladonGymBattleText6"] = "不许把虫属性或\n火属性宝可梦带进来！",
  ["_CeladonGymBattleText7"] = "很高兴认识你。\n我的爱好是\v训练宝可梦。",
  ["_CeladonGymBattleText8"] = "欢迎来到\n玉虹道馆！\f可别小看\n女孩子的力量！",
  ["_CeladonGymEndBattleText2"] = "你下手\n太狠了！",
  ["_CeladonGymEndBattleText3"] = "我的\n妆！",
  ["_CeladonGymEndBattleText4"] = "我\n惊呆了！",
  ["_CeladonGymEndBattleText5"] = "不！",
  ["_CeladonGymEndBattleText6"] = "哎呀！\n你这人！",
  ["_CeladonGymEndBattleText7"] = "哎呀！\n真精彩！",
  ["_CeladonGymEndBattleText8"] = "啊！\n输了！",
  ["_CeladonGymErikaPostBattleAdviceText"] = "你在收集宝可梦？\n真令人佩服。\f不过，要是不好看，\n我可不会去收集。",
  ["_CeladonGymErikaPreBattleText"] = "你好。今天天气\n真不错呢。\v让人好惬意。\f……哎呀……\n我好像睡着了。\v欢迎你。\f我叫莉佳，\n是玉虹道馆的馆主。\f我教授插花艺术。\n我的宝可梦\v都是草属性。\f哎呀，对不起，\n没想到你是来\v挑战我的。\f那好吧，\n不过我不会输的。",
  ["_CeladonGymErikaReceivedRainbowBadgeText"] = "哎呀！\n我认输了。\f你强得令人惊叹。\f请收下\n这枚彩虹徽章。",
  ["_CeladonGymRainbowBadgeInfoText"] = "彩虹徽章能让\n等级不超过50的\v宝可梦听从指示。\f它也能让宝可梦\n在战斗内外\v使用怪力。\f这个也请收下。",
  ["_CeladonGymReceivedTM21Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CeladonGymTM21NoRoomText"] = "先给这个\n腾出位置吧。",
  ["_CeladonHotelBeautyText"] = "我和哥哥、男朋友\n一起来度假。\f玉虹市真漂亮！",
  ["_CeladonHotelGrannyText"] = "宝可梦？不，\n这里是人住的酒店。\f而且已经客满了。",
  ["_CeladonHotelSuperNerdText"] = "她为什么\n还带着哥哥来？",
  ["_CeladonMansion1FClefairyText"] = "皮皮：皮\n皮皮皮！",
  ["_CeladonMansion1FManagersSuiteSignText"] = "玉虹大厦\n管理员套房",
  ["_CeladonMansion1FMeowthText"] = "喵喵：喵！",
  ["_CeladonMansion1FNidoranFText"] = "尼多兰：呀\n呀哦！",
  ["_CeladonMansion1Text10"] = "你的皮卡丘\n好像已经很听话了。",
  ["_CeladonMansion1Text11"] = "你的皮卡丘\n和你在一起很开心。",
  ["_CeladonMansion1Text12"] = "你们看起来\n真是绝佳搭档。\f真让我羡慕！",
  ["_CeladonMansion1Text2"] = "亲爱的宝可梦们\n一直陪着我。\f喵喵还会把钱\n带回家呢！",
  ["_CeladonMansion1Text6"] = "哎呀，你带着一只\n可爱的皮卡丘呢。",
  ["_CeladonMansion1Text7"] = "看来它\n一点也不听话。",
  ["_CeladonMansion1Text8"] = "你怎么不更用心地\n照顾皮卡丘呢？",
  ["_CeladonMansion1Text9"] = "有这么可爱的宝可梦，\n你一定很幸福吧。",
  ["_CeladonMansion2FMeetingRoomSignText"] = "GAME FREAK\n会议室",
  ["_CeladonMansion3FDevRoomSignText"] = "GAME FREAK\n开发室",
  ["_CeladonMansion3FGameDesignerCompletedDexText"] = "哇！太棒了！\n你完成了\v宝可梦图鉴！\v恭喜！\v……",
  ["_CeladonMansion3FGameDesignerCompletedDexText2"] = "去向开发团队\n炫耀你的奖状吧。",
  ["_CeladonMansion3FGameDesignerText"] = "原来如此。\f我是游戏设计师！\f完成宝可梦图鉴\n很不容易，\v但别放弃！\f完成后记得\n来告诉我！",
  ["_CeladonMansion3FGameProgramPCText"] = "这是游戏程序！\n随便乱动的话，\v游戏会出故障！",
  ["_CeladonMansion3FGameScriptPCText"] = "这是游戏脚本！\n最好别偷看结局！",
  ["_CeladonMansion3FGraphicArtistText"] = "我是美术设计师！\n你就是我画的！",
  ["_CeladonMansion3FGraphicArtistText2"] = "我是美术设计师！\f哇，你完成了\n宝可梦图鉴！\v要不要打印一张\v奖状作为证明？",
  ["_CeladonMansion3FGraphicArtistText3"] = "想打印奖状的话，\n随时告诉我。",
  ["_CeladonMansion3FGraphicArtistText4"] = "全部完成！",
  ["_CeladonMansion3FGraphicArtistText5"] = "好，那就不打印。",
  ["_CeladonMansion3FPlayingGamePCText"] = "有人不工作，\n在玩游戏！",
  ["_CeladonMansion3FProgrammerText"] = "我？我是\n程序员！",
  ["_CeladonMansion3FProgrammerText2"] = "我？我是程序员！\f真没想到！\n竟然有人能\v完成宝可梦图鉴。",
  ["_CeladonMansion3FWriterText"] = "剧情是我写的！\n莉佳很可爱吧？\f我也很喜欢小霞！\f还有娜姿，\n我也喜欢！",
  ["_CeladonMansion3FWriterText2"] = "剧情是我写的！\f你收服了所有宝可梦！\n太棒了，谢谢！",
  ["_CeladonMansionRoofHouseHikerText"] = "你的GAME BOY中\n宝可梦世界的一切，\v我都了如指掌！\f和朋友们聚在一起，\n交换宝可梦吧！",
  ["_CeladonMansionRoofHouseSignText"] = "我无所不知！",
  ["_CeladonMart1FCurrentFloorSignText"] = "1楼：服务台",
  ["_CeladonMart1FDirectorySignText"] = "1楼：服务台\f2楼：训练家用品\f3楼：电视游戏商店\f4楼：贤者礼品店\f5楼：药品店\f屋顶广场：\n自动售货机",
  ["_CeladonMart1FReceptionistText"] = "你好！欢迎来到\n玉虹百货大楼。\f右边的楼层指南\n介绍了店内布局。",
  ["_CeladonMart2FCurrentFloorSignText"] = "训练家的\n顶级道具！\f2楼：训练家用品",
  ["_CeladonMart2FGirlText"] = "长途旅行时，\n最好买些活力碎片。",
  ["_CeladonMart2FMiddleAgedManText"] = "白银喷雾能让\n弱小的宝可梦\v不敢靠近……\f嗯，它是效果更强的\n除虫喷雾！",
  ["_CeladonMart3FClerkReceivedTM18Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CeladonMart3FClerkTM18ExplanationText"] = "招式学习器18是\n双倍奉还！\v可不是我靠着的\n这个柜台哦！",
  ["_CeladonMart3FClerkTM18NoRoomText"] = "你的背包\n已经装满道具了！",
  ["_CeladonMart3FClerkTM18PreReceiveText"] = "哦，你好！我终于\n通关宝可梦了！\f你还没通关？\n这个也许有用！",
  ["_CeladonMart3FCurrentFloorSignText"] = "3楼：电视游戏商店",
  ["_CeladonMart3FFightingGameText"] = "格斗游戏！\n看起来很难！",
  ["_CeladonMart3FGameBoyKid1Text"] = "收服的宝可梦\n会登记ID编号，\v以及最初收服它的\v初训家姓名！",
  ["_CeladonMart3FGameBoyKid2Text"] = "好！\f朋友要用他的袋兽\n交换我的隆隆石！",
  ["_CeladonMart3FGameBoyKid3Text"] = "加油，隆隆石！\f我最喜欢隆隆石！\n一直在收集它们！\f咦？\f隆隆石变成了\n另一种宝可梦！",
  ["_CeladonMart3FLittleBoyText"] = "通过ID编号，\n就能辨认交换来的\v宝可梦！",
  ["_CeladonMart3FPokemonPosterText"] = "红与蓝！\n两款都是宝可梦！",
  ["_CeladonMart3FPuzzleGameText"] = "益智游戏！\n看起来会让人上瘾！",
  ["_CeladonMart3FRPGText"] = "角色扮演游戏！\n没时间玩那个！",
  ["_CeladonMart3FSNESText"] = "是超级任天堂！",
  ["_CeladonMart3FSportsGameText"] = "体育游戏！\n爸爸一定会喜欢！",
  ["_CeladonMart4FCurrentFloorSignText"] = "用礼物表达心意！\f4楼：贤者礼品店\f进化特卖！\n各种进化之石\v正在销售！",
  ["_CeladonMart4FSuperNerdText"] = "我要给华蓝市的\n模仿少女买礼物。\f一定得买皮皮玩偶，\n现在很流行！",
  ["_CeladonMart4FYoungsterText"] = "听说了一个好办法。\f遇到野生宝可梦时，\n用皮皮玩偶\v分散它的注意力，\v就能逃走！",
  ["_CeladonMart5FCurrentFloorSignText"] = "5楼：药品店",
  ["_CeladonMart5FGentlemanText"] = "只有这里能买到\n宝可梦的能力增强剂。\f使用特攻增强剂\n可以提高特殊能力。\f使用速度增强剂\n可以提高速度。",
  ["_CeladonMart5FSailorText"] = "我是来买\n能力增强剂的。\f攻击增强剂\n可以提高攻击。\f防御增强剂\n可以提高防御！",
  ["_CeladonMartRoofCurrentFloorSignText"] = "屋顶广场：\n自动售货机",
  ["_CeladonMartRoofLittleGirlGiveHerADrinkText"] = "我渴了！\n想喝点什么！\f要给她饮料吗？",
  ["_CeladonMartRoofLittleGirlGiveHerWhichDrinkText"] = "要给她哪种饮料？",
  ["_CeladonMartRoofLittleGirlImNotThirstyText"] = "不用了，谢谢！\n我已经不渴了！",
  ["_CeladonMartRoofLittleGirlImThirstyText"] = "我渴了！\n想喝点什么！",
  ["_CeladonMartRoofLittleGirlNoRoomText"] = "没有空间\n放这个了！",
  ["_CeladonMartRoofLittleGirlReceivedTM13Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CeladonMartRoofLittleGirlReceivedTM48Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CeladonMartRoofLittleGirlReceivedTM49Text"] = "{PLAYER}获得了\n招式学习器49！",
  ["_CeladonMartRoofLittleGirlTM13ExplanationText"] = "\f{RAM:wStringBuffer}里是\n冰冻光束！\f有时能让对手冰冻！",
  ["_CeladonMartRoofLittleGirlTM48ExplanationText"] = "\f{RAM:wStringBuffer}里是\n岩崩！",
  ["_CeladonMartRoofLittleGirlTM49ExplanationText"] = "\f招式学习器49里是\n三重攻击！",
  ["_CeladonMartRoofLittleGirlYayFreshWaterText"] = "太好了！\f是美味之水！\f谢谢你！\f这个送给你！",
  ["_CeladonMartRoofLittleGirlYayLemonadeText"] = "太好了！\f是果汁牛奶！\f谢谢你！\f这个送给你！",
  ["_CeladonMartRoofLittleGirlYaySodaPopText"] = "太好了！\f是劲爽汽水！\f谢谢你！\f这个送给你！",
  ["_CeladonMartRoofSuperNerdText"] = "别看我姐姐那样，\n她其实是训练家。\f可她太不成熟了，\n真让我受不了！",
  ["_CeladonPokecenterBeautyText"] = "我从浅红市出发，\n沿自行车道上坡\v骑到这里！",
  ["_CeladonPokecenterGentlemanText"] = "宝可梦之笛会发出\n只有宝可梦听得见的\v声音，唤醒它们！",
  ["_CeruleanBadgeHouseBoulderBadgeText"] = "所有宝可梦的\n攻击都会\v稍微提升。\f此外，你还能\n随时使用\v闪光。",
  ["_CeruleanBadgeHouseCascadeBadgeText"] = "等级不超过30的宝可梦\n会听从你的指示。\f等级再高就会\n变得不听话！\f此外，你还能\n在对战外使用\v居合斩。",
  ["_CeruleanBadgeHouseEarthBadgeText"] = "所有宝可梦都会\n听从你的指示！",
  ["_CeruleanBadgeHouseMarshBadgeText"] = "等级不超过70的宝可梦\n会听从你的指示。\f等级再高就会\n变得不听话！",
  ["_CeruleanBadgeHouseMiddleAgedManText"] = "只有优秀的\n宝可梦训练家\v才能拥有徽章。\f看来你至少\n有一枚。\f这些徽章\n藏着惊人的秘密！",
  ["_CeruleanBadgeHouseMiddleAgedManVisitAnyTimeText"] = "欢迎你随时\n来找我。",
  ["_CeruleanBadgeHouseMiddleAgedManWhichBadgeText"] = "那么……\f8枚徽章中，\n你想让我\v介绍哪一枚？",
  ["_CeruleanBadgeHouseRainbowBadgeText"] = "等级不超过50的宝可梦\n会听从你的指示。\f等级再高就会\n变得不听话！\f此外，你还能\n在对战外使用\v怪力。",
  ["_CeruleanBadgeHouseSoulBadgeText"] = "所有宝可梦的\n防御都会\v稍微提升。\f此外，你还能\n在对战外使用\v冲浪。",
  ["_CeruleanBadgeHouseThunderBadgeText"] = "所有宝可梦的\n速度都会\v稍微提升。\f此外，你还能\n在对战外使用\v飞翔。",
  ["_CeruleanBadgeHouseVolcanoBadgeText"] = "你的宝可梦的\n特殊能力会\v稍微提升。",
  ["_CeruleanCityBikeShopSign"] = "草地和洞窟\n都能轻松通过！\v奇迹自行车店",
  ["_CeruleanCityCooltrainerF1ElectrodePunchText"] = "顽皮雷弹，用撞击！\n不！你又\v搞错了！",
  ["_CeruleanCityCooltrainerF1ElectrodeUseSonicboomText"] = "好！顽皮雷弹！\n使用音爆！\v拜托，顽皮雷弹，\v集中注意！",
  ["_CeruleanCityCooltrainerF1ElectrodeWithdrawText"] = "顽皮雷弹，用高速星星！\n不！不是这个！\f训练宝可梦\n真困难！\f宝可梦会不会\n听从指示，\v取决于你身为训练家的\v能力！",
  ["_CeruleanCityCooltrainerF2Text"] = "我想要一辆\n鲜红的自行车！\f我要把它放在\n家里，免得\v弄脏！",
  ["_CeruleanCityCooltrainerMText"] = "你也是训练家吗？\n收服宝可梦、\v进行对战，\v真不容易。",
  ["_CeruleanCityElectrodeIgnoredOrdersText"] = "顽皮雷弹\n无视了指示……",
  ["_CeruleanCityElectrodeIsLoafingAroundText"] = "顽皮雷弹在\n偷懒……",
  ["_CeruleanCityElectrodeTookASnoozeText"] = "顽皮雷弹\n打起了瞌睡……",
  ["_CeruleanCityElectrodeTurnedAwayText"] = "顽皮雷弹\n把头转开了……",
  ["_CeruleanCityGuardText"] = "这户可怜的人家\n遭到抢劫。\f我们确信\n这起恶劣事件\v就是火箭队\v干的。\f就连我们的警察\n也拿火箭队\v没办法！",
  ["_CeruleanCityGymSign"] = "华蓝市\n宝可梦道馆\v馆主：小霞\f俏皮的\n美人鱼！",
  ["_CeruleanCityRivalDefeatedText"] = "喂！\n别那么认真！\v你已经赢了！",
  ["_CeruleanCityRivalIWentToBillsText"] = "{RIVAL}：喂，\n猜猜怎么着？\f我去了正辉那里，\n让他给我看了\v珍稀的\v宝可梦！\f我的宝可梦图鉴\n增加了不少\v资料！\f毕竟正辉可是\n世界闻名的\v宝可梦狂热迷！\f他发明了\n电脑里的宝可梦\v寄放系统！\f既然你也在用\n他的系统，\v就去谢谢他吧！\f好了，我得\n出发了！\v回头见！",
  ["_CeruleanCityRivalPreBattleText"] = "{RIVAL}：哟！\n{PLAYER}！\f你一路\n苦苦挣扎，\v才走到这里？\f我可顺利得很！\n我抓到了一群\v又强大\v又聪明的宝可梦！\f来，让我看看\n你抓到了什么，\v{PLAYER}！",
  ["_CeruleanCityRivalVictoryText"] = "嘿嘿！\n你根本不是\v本天才的对手！",
  ["_CeruleanCityRocketIBetterGetMovingText"] = "\f我得赶快\n溜了！再见！",
  ["_CeruleanCityRocketIGiveUpText"] = "住手！\n我投降！我会\v乖乖离开！",
  ["_CeruleanCityRocketIllReturnTheTMText"] = "好吧！我把偷来的\n招式学习器还你！",
  ["_CeruleanCityRocketReceivedTM28Text"] = "{PLAYER}找回了\n招式学习器28！",
  ["_CeruleanCityRocketTM28NoRoomText"] = "给这个腾出\n位置吧！\f交给你之前，\n我还不能逃！",
  ["_CeruleanCityRocketText"] = "喂！别靠近！\n这里又不是你的\v院子！啊？我？\f我只是无辜的\n路人！你难道\v不相信我吗？",
  ["_CeruleanCitySignText"] = "华蓝市\n神秘的蓝色\v气息环绕着\v这座城市",
  ["_CeruleanCitySuperNerd1Text"] = "商店前面的\n灌木丛\v挡路了。\f或许有别的路\n可以绕过去。",
  ["_CeruleanCitySuperNerd2Text"] = "你在制作\n宝可梦图鉴？\v听起来\v挺有趣的。",
  ["_CeruleanCitySuperNerd3Text"] = "这里就是\n华蓝洞窟！里面有\v强得可怕的\v宝可梦！\f只有宝可梦联盟的\n冠军才\v获准\v进入！",
  ["_CeruleanCityTrainerTipsText"] = "训练家提示\f宝可梦进化时，\n按下B键\v就能取消\v整个进化过程。",
  ["_CeruleanGymAfterBattleText1"] = "只有和其他\n训练家对战，\v才能知道自己\v究竟有多强。",
  ["_CeruleanGymAfterBattleText2"] = "小霞会继续\n变强的！\f她绝不会输给\n你这样的人！",
  ["_CeruleanGymBattleText1"] = "对付你，\n我绰绰有余！\f小霞先等等吧！",
  ["_CeruleanGymBattleText2"] = "哗啦！\f由我打头阵！\n来吧！",
  ["_CeruleanGymEndBattleText1"] = "完全\n被你压制了！",
  ["_CeruleanGymEndBattleText2"] = "这\n不可能！",
  ["_CeruleanGymGymGuideBeatMistyText"] = "你打败小霞了！\n我说得没错吧？\f小子，你和我\n真是相当\v默契的搭档！",
  ["_CeruleanGymGymGuideChampInMakingText"] = "哟！未来的\n冠军！\f听听我的建议！\f馆主小霞\n是使用水属性\v宝可梦的专家！\f用草属性宝可梦\n吸干它们的\v水分！\f或者用电\n狠狠电它们！",
  ["_CeruleanGymMistyCascadeBadgeInfoText"] = "蓝色徽章能让\n等级不超过30的宝可梦\v听从你的指示！\f就连外来的\n宝可梦也包括在内！\f还有呢，你现在\n随时都能使用居合斩\v了！\f用居合斩砍倒\n小灌木，\v就能开辟新道路！\f你也可以拿走\n我最喜欢的招式学习器！",
  ["_CeruleanGymMistyPreBattleText"] = "你好！你是\n新面孔呢！\f你对宝可梦的\n培育方针是什么？\v你的对战方式呢？\f我的方针是\n使用水属性宝可梦\v全力\v进攻！\f举世闻名的\n美女小霞，\v来当你的对手！\f准备好了吗，\n小可爱？",
  ["_CeruleanGymMistyReceivedCascadeBadgeText"] = "我不敢\n相信自己输了！\f好吧！\f把这枚蓝色徽章\n送给你，作为\v打败我的证明！",
  ["_CeruleanGymMistyReceivedTM11Text"] = "{PLAYER}获得了\n招式学习器11！",
  ["_CeruleanGymMistyTM11ExplanationText"] = "招式学习器11里是\n泡沫光线！\f让水生宝可梦\n学会它吧！",
  ["_CeruleanGymMistyTM11NoRoomText"] = "你最好给这个\n腾出位置！",
  ["_CeruleanMartCooltrainerFText"] = "你见过\n神奇糖果吗？\f据说它能让宝可梦\n提升\v一个等级！",
  ["_CeruleanMartCooltrainerMText"] = "使用除虫喷雾就能\n赶走虫子和\v弱小的宝可梦。\f把最强的宝可梦\n放在队伍\v最前面，\v效果会更好！",
  ["_CeruleanPokecenterGentlemanText"] = "你听说过\n正辉吗？\f大家都说他是\n宝可梦狂热迷！\f不过我觉得\n大家只是嫉妒\v正辉罢了。\f谁不想炫耀\n自己的\v宝可梦呢？",
  ["_CeruleanPokecenterGuyText"] = "正辉有很多\n宝可梦！\f他也会收集\n珍稀的宝可梦！",
  ["_CeruleanPokecenterSuperNerdText"] = "正辉那家伙！\f听说为了\n得到珍稀宝可梦，\v他什么事\v都肯做！",
  ["_CeruleanTrashedHouseFishingGuruTheyStoleATMText"] = "可恶的\n火箭队！\f看看他们\n干的好事！\f他们偷走了\n能让宝可梦\v学会挖洞的\v招式学习器！\f那可是我花了\n一大笔钱买的！",
  ["_CeruleanTrashedHouseFishingGuruWhatsLostIsLostText"] = "我想，丢了就\n丢了吧！\f我决定不用招式学习器\n直接让地鼠\v学会挖洞！",
  ["_CeruleanTrashedHouseGirlText"] = "火箭队一定\n想靠挖洞\v偷偷去干\v坏事！",
  ["_CeruleanTrashedHouseWallHoleText"] = "火箭队留下了\n逃跑的通道！",
  ["_ChampionsRoomOakComeWithMeText"] = "大木博士：{PLAYER}！\f你要明白，\n这场胜利不只是\v靠你一人取得的！\f你和宝可梦之间的\n羁绊非常了不起！\f{PLAYER}！\n跟我来！",
  ["_ChampionsRoomOakCongratulatesPlayerText"] = "大木博士：你赢了！\n恭喜！\v你就是新任的\v宝可梦联盟冠军！\f自从你带着\n{RAM:wNameBuffer}出发以来，\v真的成长了很多！\f{PLAYER}，\n你已经长大了！",
  ["_ChampionsRoomOakDisappointedWithRivalText"] = "大木博士：{RIVAL}！\n我很失望！\f听说你打败四天王，\n我便赶了过来！\f可我到这里时，\n你已经输了！\f{RIVAL}！你明白\n自己为什么会输吗？\f你忘了要以信任和爱\n对待自己的宝可梦！\f没有这些，\n你永远无法\v再次成为冠军！",
  ["_ChampionsRoomOakText"] = "大木博士：{PLAYER}！",
  ["_ChampionsRoomRivalAfterBattleText"] = "为什么？\n我为什么会输？\f我培育宝可梦时\n明明没犯任何错……\f可恶！现在你是\n宝可梦联盟冠军了！\f虽然我不愿承认。",
  ["_ChampionsRoomRivalIntroText"] = "{RIVAL}：嘿！\f我一直期待\n和你见面，{PLAYER}！\f我的劲敌必须够强，\n才能让我保持敏锐！\f为了完成宝可梦图鉴，\n我四处寻找\v强大的宝可梦！\f不仅如此，\n我还组建了\v足以击败任何属性\v宝可梦的队伍！\f而现在！\f我就是\n宝可梦联盟冠军！\f{PLAYER}！\n你知道这意味着什么吗？\f告诉你吧！\f我就是全世界\n最强的训练家！",
  ["_ChanseyDexEntry"] = "温柔善良的宝可梦。\n看到受伤的宝可梦时，\f会把营养丰富的蛋\n分给它。",
  ["_ChargeMoveEffectText"] = "{USER}",
  ["_CharizardDexEntry"] = "喷出灼热火焰时，\n尾巴尖端的红色火焰\f会燃烧得更加猛烈。",
  ["_CharmanderDexEntry"] = "尾巴尖端的火焰\n燃烧时会发出声音。\f只有在安静的地方\n才能听见。",
  ["_CharmeleonDexEntry"] = "激烈的战斗\n会令它兴奋。\f兴奋时有时会\n喷出蓝白色火焰。",
  ["_ChooseABoxText"] = "选择一个\n宝可梦盒。",
  ["_CinnabarGymBlainePostBattleAdviceText"] = "大字爆炎是\n终极的火属性招式！\f别浪费在\n水属性宝可梦身上！",
  ["_CinnabarGymBlainePreBattleText"] = "哈！\f我就是夏伯！\n红莲道馆的馆主！\f我的火属性宝可梦\n会把所有挑战者\v烧成灰烬！\f哈！你最好\n备好灼伤药！",
  ["_CinnabarGymBlaineReceivedTM38Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CinnabarGymBlaineReceivedVolcanoBadgeText"] = "我的火焰\n熄灭了！\f你赢得了\n深红徽章！",
  ["_CinnabarGymBlaineTM38ExplanationText"] = "\f招式学习器38里是\n大字爆炎！\f把它教给\n火属性宝可梦吧！\f火恐龙或烈焰马\n都是不错的选择！",
  ["_CinnabarGymBlaineTM38NoRoomText"] = "给我的礼物\n腾出位置！",
  ["_CinnabarGymBlaineVolcanoBadgeInfoText"] = "哈！\f深红徽章能提高\n宝可梦的特殊能力！\f来，这个也给你！",
  ["_CinnabarGymGymGuideBeatBlaineText"] = "{PLAYER}！你打败了\n那个火爆老头！",
  ["_CinnabarGymGymGuideChampInMakingText"] = "哟！未来的冠军！\f脾气火爆的夏伯\n是火属性宝可梦专家！\f用水浇灭\n他的斗志吧！\f最好带上一些\n灼伤药！",
  ["_CinnabarGymQuizCorrectText"] = "完全正确！\f继续前进吧！",
  ["_CinnabarGymQuizDummyIntroText"] = "宝可梦问答！\f答对后，通往\n下一间房的门会打开！\f答错就得\n和训练家对战！\f如果想保留宝可梦\n挑战道馆馆主……\f那就答对吧！\n开始！",
  ["_CinnabarGymQuizIncorrectText"] = "很遗憾！答错了！",
  ["_CinnabarGymQuizIntroText"] = "宝可梦问答！\f答对后，通往\n下一间房的门会打开！\f答错就得和\n挡路的训练家对战！\f如果想保留宝可梦\n挑战道馆馆主……\f那就答对吧！\n开始！\f",
  ["_CinnabarGymQuizShortIntroText"] = "宝可梦问答！\n考验你的知识！\f",
  ["_CinnabarGymSuperNerd1AfterBattleText"] = "火，准确地说\n应该是燃烧……\f诸如此类，\n诸如此类……",
  ["_CinnabarGymSuperNerd1BattleText"] = "你知道宝可梦喷出的\n火焰有多热吗？",
  ["_CinnabarGymSuperNerd1EndBattleText"] = "呀！\n好烫，好烫！",
  ["_CinnabarGymSuperNerd2AfterBattleText"] = "我就是忍不住\n偷别人的宝可梦！",
  ["_CinnabarGymSuperNerd2BattleText"] = "我以前是小偷，\n成为训练家后\v已经改邪归正！",
  ["_CinnabarGymSuperNerd2EndBattleText"] = "我\n投降！",
  ["_CinnabarGymSuperNerd3AfterBattleText"] = "我的理论\n对你来说太复杂了！",
  ["_CinnabarGymSuperNerd3BattleText"] = "你赢不了！\n我把宝可梦\v研究透了！",
  ["_CinnabarGymSuperNerd3EndBattleText"] = "哇！\n我的研究！",
  ["_CinnabarGymSuperNerd4AfterBattleText"] = "真希望有一种\n小偷宝可梦！\v我一定会用它！",
  ["_CinnabarGymSuperNerd4BattleText"] = "我就是喜欢用\n火属性宝可梦！",
  ["_CinnabarGymSuperNerd4EndBattleText"] = "太烫了，\n受不了！",
  ["_CinnabarGymSuperNerd5AfterBattleText"] = "夏伯曾在山里迷路，\n这时出现了一只\v燃烧着火焰的鸟宝可梦。\f它的光芒照亮道路，\n让夏伯找到了下山的路！",
  ["_CinnabarGymSuperNerd5BattleText"] = "我知道夏伯\n为何会成为训练家！",
  ["_CinnabarGymSuperNerd5EndBattleText"] = "哎哟！",
  ["_CinnabarGymSuperNerd6AfterBattleText"] = "我们这些火属性\n宝可梦迷喜欢\v小火马和九尾！",
  ["_CinnabarGymSuperNerd6BattleText"] = "我去过很多道馆，\n这里是我最喜欢的！",
  ["_CinnabarGymSuperNerd6EndBattleText"] = "哎呀！\n太烫了！",
  ["_CinnabarGymSuperNerd7AfterBattleText"] = "水能克火！\n但火也能融化\v冰属性宝可梦！",
  ["_CinnabarGymSuperNerd7BattleText"] = "火怕H2O！",
  ["_CinnabarGymSuperNerd7EndBattleText"] = "啊！\n熄灭了！",
  ["_CinnabarGymText_1"] = "这座道馆也被称为\n问答道馆。\f想见夏伯，\n就得参加问答。\f只要答对，\n就不用和我们对战。",
  ["_CinnabarGymText_2"] = "觉得自己能做到吗？",
  ["_CinnabarGymText_3"] = "这题很难！",
  ["_CinnabarGymText_4"] = "宝可梦也喜欢\n猜谜！",
  ["_CinnabarGymText_5"] = "我喜欢这座\n问答道馆。",
  ["_CinnabarGymText_6"] = "这是最后一题。",
  ["_CinnabarGymText_7"] = "来吧，回答问题！",
  ["_CinnabarIslandDoorIsLockedText"] = "门锁着……",
  ["_CinnabarIslandGamblerText"] = "科学家们在\n那栋烧毁的建筑里\v进行实验。",
  ["_CinnabarIslandGirlText"] = "红莲道馆的夏伯\n是个古怪的人，\v已经在这里生活了几十年。",
  ["_CinnabarIslandGymSignText"] = "红莲镇\n宝可梦道馆\v馆主：夏伯\f脾气火爆的问答大师！",
  ["_CinnabarIslandPokemonLabSignText"] = "宝可梦研究所",
  ["_CinnabarIslandSignText"] = "红莲镇\n热情燃烧的火红之镇",
  ["_CinnabarLabFishingGuruText"] = "我们在这里\n深入研究宝可梦。\f人们经常带来\n珍稀宝可梦供我们检查。",
  ["_CinnabarLabFossilRoomScientist1ComeAgainText"] = "哎呀！你又来啦！",
  ["_CinnabarLabFossilRoomScientist1FossilIsBackToLifeText"] = "你去哪儿了？\f你的化石复活啦！\f果然和我想的一样，\n是{RAM:wStringBuffer}！",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText"] = "需要一点时间！\f你先出去\n走一会儿！",
  ["_CinnabarLabFossilRoomScientist1GoForAWalkText2"] = "需要一点时间！\f你先出去\n走一会儿！",
  ["_CinnabarLabFossilRoomScientist1NoFossilsText"] = "没有！真可惜！",
  ["_CinnabarLabFossilRoomScientist1SeesFossilText"] = "哦！那是\n{RAM:wNameBuffer}！\f是已经灭绝的宝可梦\n{RAM:wStringBuffer}的化石！\f我的复活机器\n能让那只宝可梦\v重新活过来！",
  ["_CinnabarLabFossilRoomScientist1TakesFossilText"] = "好！快把它给我！\f{PLAYER}交出了\n{RAM:wNameBuffer}！",
  ["_CinnabarLabFossilRoomScientist1Text"] = "你好！\f我是个了不起的博士！\f我在这里研究\n珍稀宝可梦的化石！\f你！有化石\n要交给我吗？",
  ["_CinnabarLabMeetingRoomSignText"] = "宝可梦研究所\n会议室",
  ["_CinnabarLabMetronomeRoomAmberPipeText"] = "琥珀制的烟斗！",
  ["_CinnabarLabMetronomeRoomPCText"] = "有一封电子邮件！\f……\f三只传说中的\n鸟宝可梦分别是\v急冻鸟、闪电鸟和火焰鸟。\f它们目前下落不明。\f我们计划探索\n华蓝市附近的洞窟。\f发件人：\n宝可梦研究团队\f……",
  ["_CinnabarLabMetronomeRoomScientist1ReceivedTM35Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CinnabarLabMetronomeRoomScientist1TM35ExplanationText"] = "滴答滴答！\n这就是挥指的节奏！\f它会刺激宝可梦的大脑，\n使出自己不会的招式！",
  ["_CinnabarLabMetronomeRoomScientist1TM35NoRoomText"] = "你的背包\n已经塞满了！",
  ["_CinnabarLabMetronomeRoomScientist1Text"] = "滴答滴答！\n我做出了很酷的\v招式学习器！\f能引发各种\n有趣的效果！",
  ["_CinnabarLabMetronomeRoomScientist2Text"] = "伊布可以进化成\n3种宝可梦之一。",
  ["_CinnabarLabPhotoText"] = "研究所创办人\n富士博士的照片！",
  ["_CinnabarLabRAndDSignText"] = "宝可梦研究所\n研发室",
  ["_CinnabarLabTestingRoomSignText"] = "宝可梦研究所\n测试室",
  ["_CinnabarLabTradeRoomSuperNerdText"] = "我在月见山\n发现了这个奇怪的化石！\f我觉得它是\n珍稀的史前宝可梦！",
  ["_CinnabarMartScientistText"] = "多备些道具\n总不会吃亏！",
  ["_CinnabarMartSilphWorkerFText"] = "没有力量强化吗？\n对战时很好用！",
  ["_CinnabarPokecenterCooltrainerFText"] = "可以取消进化。\f宝可梦正在进化时，\n你可以让它停下来，\v维持原来的样子。",
  ["_CinnabarPokecenterGentlemanText"] = "你有朋友吗？\f通过交换得到的宝可梦\n成长得非常快。\f值得试试看！",
  ["_CinnabarPokecenterGuyText"] = "取消进化后，\n宝可梦依然能学习招式。\f等它学会新招式后\n再进化也不迟。",
  ["_CinnabarQuizQuestionsText1"] = "绿毛虫会进化成\n巴大蝶？",
  ["_CinnabarQuizQuestionsText2"] = "宝可梦联盟认证的\n徽章共有9枚？",
  ["_CinnabarQuizQuestionsText3"] = "蚊香蝌蚪会\n进化3次？",
  ["_CinnabarQuizQuestionsText4"] = "电属性招式对\n地面属性宝可梦有效？",
  ["_CinnabarQuizQuestionsText5"] = "种类和等级相同的\n宝可梦也会有所不同？",
  ["_CinnabarQuizQuestionsText6"] = "招式学习器28里是\n墓碑摔？",
  ["_ClearSaveDataText"] = "清除所有\n保存数据？",
  ["_ClefableDexEntry"] = "似乎非常珍视\n自己的世界。\f是一种很少在人前\n现身的妖精。",
  ["_ClefairyDexEntry"] = "可爱的外表和\n活泼的性格深受喜爱。\f由于很少现身，\n被认为十分稀有。",
  ["_ClosedOaksPCText"] = "与大木博士电脑的\n连接已断开。",
  ["_CloysterDexEntry"] = "用比钻石还坚硬的\n外壳保护自己。\f也会从外壳中\n发射尖刺。",
  ["_CoinCaseNumCoinsText"] = "代币\n{NUM:wPlayerCoins, 2 | LEADING_ZEROES | LEFT_ALIGN} ",
  ["_CoinsScatteredText"] = "代币散落得\n到处都是！",
  ["_Colosseum3MonsText"] = "需要3只宝可梦\n才能对战！",
  ["_ColosseumCanceledText"] = "连接已取消。",
  ["_ColosseumDifferentMonsText"] = "宝可梦必须\n各不相同！",
  ["_ColosseumEvolvedText"] = "{RAM:wNameBuffer}是\n进化后的宝可梦！",
  ["_ColosseumHeightText"] = "{RAM:wNameBuffer}的身高\n超过6英尺8英寸！",
  ["_ColosseumIneligibleText"] = "对手不符合\n参赛资格。",
  ["_ColosseumMaxL20Text"] = "所有宝可梦\n都不得超过20级！",
  ["_ColosseumMaxL30Text"] = "所有宝可梦\n都不得超过30级！",
  ["_ColosseumMaxL55Text"] = "所有宝可梦\n都不得超过55级！",
  ["_ColosseumMewText"] = "抱歉，梦幻不能参赛！",
  ["_ColosseumMinL15Text"] = "所有宝可梦\n必须至少15级！",
  ["_ColosseumMinL25Text"] = "所有宝可梦\n必须至少25级！",
  ["_ColosseumMinL50Text"] = "所有宝可梦\n必须至少50级！",
  ["_ColosseumOpponentText"] = "!",
  ["_ColosseumPleaseWaitText"] = "好，请稍等片刻。",
  ["_ColosseumTotalL155Text"] = "宝可梦的等级总和\n超过155！",
  ["_ColosseumTotalL50Text"] = "宝可梦的等级总和\n超过50！",
  ["_ColosseumTotalL80Text"] = "宝可梦的等级总和\n超过80！",
  ["_ColosseumVersionText"] = "游戏版本不一致。",
  ["_ColosseumWeightText"] = "{RAM:wNameBuffer}的体重\n超过20千克！",
  ["_ColosseumWhereToText"] = "想去哪里？",
  ["_ComeBackText"] = "\n回来！",
  ["_ConfusedNoMoreText"] = "{USER}\n解除了混乱！",
  ["_ConnectCableText"] = "好，把连接线\n这样接上！",
  ["_ContCharText"] = "{_CONT}",
  ["_ConvertedTypeText"] = "属性变成了\n{TARGET}的属性！",
  ["_CopycatsHouse1FChanseyText"] = "吉利蛋：吉利\n蛋！",
  ["_CopycatsHouse1FMiddleAgedManText"] = "我女儿喜欢\n模仿别人。\f她模仿得惟妙惟肖，\n大家都叫她\v模仿少女！",
  ["_CopycatsHouse1FMiddleAgedWomanText"] = "我女儿太以自我为中心。\n她只有几个朋友。",
  ["_CopycatsHouse2FCopycatDoYouLikePokemonText"] = "{PLAYER}：你好！\n你喜欢宝可梦吗？\f{PLAYER}：呃，不是，\n是我在问你。\f{PLAYER}：咦？\n你真奇怪！\f模仿少女：嗯？\n别再模仿你？\f可这正是我\n最喜欢的爱好！",
  ["_CopycatsHouse2FCopycatReceivedTM31Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_CopycatsHouse2FCopycatTM31Explanation1Text"] = "\f招式学习器31里\n是我最爱的模仿！\f找只优秀的宝可梦\n来学吧！",
  ["_CopycatsHouse2FCopycatTM31Explanation2Text"] = "{PLAYER}：你好！\n谢谢你的招式学习器31！\f{PLAYER}：什么？\f{PLAYER}：模仿我的\n一举一动就这么好玩吗？\f模仿少女：当然！\n太好玩了！",
  ["_CopycatsHouse2FCopycatTM31NoRoomText"] = "你不想要这个吗？",
  ["_CopycatsHouse2FCopycatTM31PreReceiveText"] = "哇！\n是皮皮玩偶！\f送给我的吗？\n谢谢！\f那这个就\n送给你吧！",
  ["_CopycatsHouse2FDoduoText"] = "嘟嘟：嘎！\f魔镜啊魔镜，\n谁是世界上\v最美丽的人？",
  ["_CopycatsHouse2FPCCantSeeText"] = "咦？看不见！",
  ["_CopycatsHouse2FPCMySecretsText"] = "……\f我的秘密！\f特长：模仿！\n爱好：收集玩偶！\v最喜欢的宝可梦：\v皮皮！",
  ["_CopycatsHouse2FRareDollText"] = "这是珍稀的宝可梦！\n咦？只是个玩偶！",
  ["_CopycatsHouse2FSNESText"] = "马力欧头顶水桶的\n游戏！",
  ["_CriticalHitText"] = "击中要害！",
  ["_CuboneDexEntry"] = "头上戴着\n亡母的头骨。\f哭声在头骨中回荡，\n化作悲伤的旋律。",
  ["_CurrentTooFastText"] = "水流太急了！",
  ["_CyclingIsFunText"] = "骑自行车真开心！\n别想冲浪了！",
  ["_DaycareGentlemanAllRightThenText"] = "那好吧，\n",
  ["_DaycareGentlemanCantAcceptMonWithHMText"] = "我不能接收\n学会秘传招式的宝可梦。",
  ["_DaycareGentlemanComeAgainText"] = "欢迎再来。",
  ["_DaycareGentlemanComeSeeMeInAWhileText"] = "过一阵子\n再来看看吧。",
  ["_DaycareGentlemanGotMonBackText"] = "{PLAYER}领回了\n{RAM:wDayCareMonName}！",
  ["_DaycareGentlemanHeresYourMonText"] = "谢谢！这是\n你的宝可梦！",
  ["_DaycareGentlemanIntroText"] = "我经营着培育屋。\n要不要把一只宝可梦\v交给我培育？",
  ["_DaycareGentlemanMonHasGrownText"] = "你的{RAM:wNameBuffer}\n成长了很多！\f一共提升了\n{NUM:wDayCareNumLevelsGrown, 1, 3}级！\f我很厉害吧？",
  ["_DaycareGentlemanMonNeedsMoreTimeText"] = "这么快就回来了？\n你的{RAM:wNameBuffer}\v还需要在我这里\v待一阵子。",
  ["_DaycareGentlemanNoRoomForMonText"] = "没有空间\n带这只宝可梦了！",
  ["_DaycareGentlemanNotEnoughMoneyText"] = "喂，你没有足够的钱！",
  ["_DaycareGentlemanOnlyHaveOneMonText"] = "你身上只有\n一只宝可梦。",
  ["_DaycareGentlemanOweMoneyText"] = "要领回这只宝可梦，\n需支付¥{NUM:wDayCareTotalCost, 2 | LEADING_ZEROES | LEFT_ALIGN}。",
  ["_DaycareGentlemanWhichMonText"] = "要培育哪只\n宝可梦？",
  ["_DaycareGentlemanWillLookAfterMonText"] = "好，我会暂时\n照顾{RAM:wNameBuffer}。",
  ["_DepositHowManyText"] = "要寄放多少？",
  ["_DepositWhichMonText"] = "要寄放哪只\n宝可梦？",
  ["_DewgongDexEntry"] = "全身雪白。\n即使严寒也无法伤害它，\f能在冰冷水域中\n强劲地游动。",
  ["_DexCompletionText"] = "宝可梦图鉴完成度：\f已见{NUM:hDexRatingNumMonsSeen, 1, 3}种\n已捕获{NUM:hDexRatingNumMonsOwned, 1, 3}种\f大木博士的评价：",
  ["_DexRatingText"] = "宝可梦图鉴评价{COLON}",
  ["_DexRatingText_Own0To9"] = "还有很长的路要走。\n去草丛里寻找\v宝可梦吧！",
  ["_DexRatingText_Own100To109"] = "终于收集到\n至少100种了！\v你的表现好得\n令人难以置信！",
  ["_DexRatingText_Own10To19"] = "方向没错！\n去我的助手那里\v领取能学会闪光的\v秘传学习器吧！",
  ["_DexRatingText_Own110To119"] = "连宝可梦的\n进化形态都有！\v太棒了！",
  ["_DexRatingText_Own120To129"] = "非常出色！\n和朋友交换，\v再多收集一些吧！",
  ["_DexRatingText_Own130To139"] = "出类拔萃！\n你已经成为\v真正的专家了！",
  ["_DexRatingText_Own140To149"] = "我已经无话可说！\n现在你才是权威！",
  ["_DexRatingText_Own150To151"] = "你的宝可梦图鉴\n已经全部完成了！\v恭喜！",
  ["_DexRatingText_Own20To29"] = "还需要更多宝可梦！\n试着收服其他种类吧！",
  ["_DexRatingText_Own30To39"] = "做得不错，\n你很努力！\v去我的助手那里\n领取探宝器吧！",
  ["_DexRatingText_Own40To49"] = "进展不错！\n收集到50种后\v去找我的助手！",
  ["_DexRatingText_Own50To59"] = "终于收集到\n至少50种了！\v别忘了从我的助手那里\n领取学习装置！",
  ["_DexRatingText_Own60To69"] = "哦！进展\n越来越好了！",
  ["_DexRatingText_Own70To79"] = "非常好！\n去钓一些\v海里的宝可梦吧！",
  ["_DexRatingText_Own80To89"] = "太棒了！\n你喜欢收集东西吗？",
  ["_DexRatingText_Own90To99"] = "真令人佩服！\n一定很不容易吧！",
  ["_DexSeenOwnedText"] = "宝可梦图鉴 发现：{NUM:wDexRatingNumMonsSeen, 1, 3}种\n           收服：{NUM:wDexRatingNumMonsOwned, 1, 3}种",
  ["_DidNotLearnText"] = "{RAM:wLearnMoveMonName}\n没有学会\v{RAM:wStringBuffer}！",
  ["_DidntAffectText"] = "对{TARGET}\n没有效果！",
  ["_DiglettDexEntry"] = "喜欢阴暗的地方。\n大部分时间生活在地下，\f但偶尔会在洞窟中\n探出头来。",
  ["_DiglettSculptureText"] = "地鼠的雕像。",
  ["_DiglettsCaveRoute11GamblerText"] = "真惊人！\n地鼠挖出了\v这条长长的隧道！\f它一直通到\n常青市！",
  ["_DiglettsCaveRoute2FishingGuruText"] = "我去了岩山隧道，\n那里又暗又可怕。\f要是宝可梦的闪光\n能照亮那里就好了……",
  ["_DisabledNoMoreText"] = "{USER}的\n定身法状态解除了！",
  ["_DittoDexEntry"] = "发现敌人时，\n身体会变形，\f几乎完美地复制\n对手的模样。",
  ["_DoItText"] = "动手吧！",
  ["_DoYouWantToNicknameText"] = "要给{RAM:wNameBuffer}\n取昵称吗？",
  ["_DodrioDexEntry"] = "嘟嘟的一个头\n分裂后形成的独特种类。\f能以接近时速60公里\n的速度在草原奔跑。",
  ["_DoduoDexEntry"] = "翅膀短小，\n不擅长飞行。\f但发达的双腿\n能让它高速奔跑。",
  ["_DoesntAffectMonText"] = "对{TARGET}\n没有效果！",
  ["_DontHavePokemonText"] = "你没有宝可梦！",
  ["_DragonairDexEntry"] = "据目击者说，\n它的身体被奇异气场包围，\f显得神秘莫测。",
  ["_DragoniteDexEntry"] = "据说它生活在\n大海的某处，而且会飞。\f不过这只是传闻。",
  ["_DratiniDexEntry"] = "这种神话般的宝可梦\n直到最近才被证实存在。\f一位钓鱼人\n曾经捕获过它。",
  ["_DreamWasEatenText"] = "{TARGET}的梦\n被吃掉了！",
  ["_DroppedHiddenCoinsText"] = "\f哎呀！\n掉了一些代币！",
  ["_DrowzeeDexEntry"] = "如果总在它身边睡觉，\n它有时会让你看到\f过去吞食过的梦。",
  ["_DugAHoleText"] = "\n挖了一个洞！",
  ["_DugtrioDexEntry"] = "由三胞胎组成，\n挖掘速度超过时速100公里。\f因此有人会误以为\n发生了地震。",
  ["_EeveeDexEntry"] = "遗传基因不稳定，\n所以能以多种方式进化。\f现存数量非常稀少。",
  ["_EkansDexEntry"] = "年龄越大，\n身体就越长。\f夜晚会把长长的身体\n缠在树枝上休息。",
  ["_ElectabuzzDexEntry"] = "一旦发生大规模停电，\n一定是这种宝可梦\f吃掉了发电厂的电力。",
  ["_ElectrodeDexEntry"] = "把电能储存在体内。\n哪怕轻微刺激，\f也可能引发大爆炸。",
  ["_ElevatorText"] = "这是电梯。",
  ["_EndUsedMove1Text"] = "!",
  ["_EndUsedMove2Text"] = "!",
  ["_EndUsedMove3Text"] = "!",
  ["_EndUsedMove4Text"] = "!",
  ["_EndUsedMove5Text"] = "!",
  ["_EnemiesOnEverySideText"] = "四面都是敌人！",
  ["_EnemyAppearedText"] = "{RAM:wEnemyMonNick}\n出现了！",
  ["_EnemyMonFaintedText"] = "对手的{RAM:wEnemyMonNick}\n倒下了！",
  ["_EnemyRanText"] = "对手的{RAM:wEnemyMonNick}\n逃走了！",
  ["_EnemysWeakText"] = "对手已经很虚弱！\n上啊！",
  ["_EnoughText"] = "够了！",
  ["_EvadedAttackText"] = "{TARGET}\n避开了攻击！",
  ["_EvolvedText"] = "{RAM:wStringBuffer}",
  ["_ExchangeCoinsForPrizesText"] = "我们可以把代币\n兑换成奖品。",
  ["_ExclamationText"] = "!",
  ["_ExeggcuteDexEntry"] = "几颗头会互相吸引，\n围绕彼此旋转。\f必须凑齐6颗头\n才能保持平衡。",
  ["_ExeggutorDexEntry"] = "叫声非常嘈杂。\n这是因为3颗头\f各自在想\n自己喜欢的事。",
  ["_ExpPointsText"] = "{NUM:wExpAmountGained, 2, 4}点经验值！",
  ["_ExpressionText"] = "这个表情是\n第{NUM:wExpressionNumber, 1, 2}号。",
  ["_FanClubPicture1Text"] = "我可爱的烈焰马。",
  ["_FanClubPicture2Text"] = "我心爱的大嘴雀。",
  ["_FarfetchdDexEntry"] = "生活在芦苇丛生的地方。\n很少被人看到，\f据说数量正在减少。",
  ["_FastAsleepText"] = "{USER}\n睡得正香！",
  ["_FearowDexEntry"] = "从远古时代便存在的\n宝可梦。\f一旦察觉危险，\n就会立刻飞向高空远去。",
  ["_FellAsleepBecameHealthyText"] = "{USER}\n睡着后恢复了健康！",
  ["_FellAsleepText"] = "{TARGET}\n睡着了！",
  ["_FellText"] = "下降了！",
  ["_FightingDojoBetterNotGetGreedyText"] = "别太贪心……",
  ["_FightingDojoBlackbelt1AfterBattleText"] = "等你见到我们师父吧！\f和他相比，\n我只是个小角色！",
  ["_FightingDojoBlackbelt1BattleText"] = "喝啊！把鞋脱掉！",
  ["_FightingDojoBlackbelt1EndBattleText"] = "我\n认输！",
  ["_FightingDojoBlackbelt2AfterBattleText"] = "我们师父是\n格斗高手！",
  ["_FightingDojoBlackbelt2BattleText"] = "听说你很厉害！\n让我见识一下！",
  ["_FightingDojoBlackbelt2EndBattleText"] = "裁判！\n一分！",
  ["_FightingDojoBlackbelt3AfterBattleText"] = "我们唯一害怕的\n就是超能力！",
  ["_FightingDojoBlackbelt3BattleText"] = "再强的东西\n也吓不倒我！\f我靠劈碎岩石\n来训练！",
  ["_FightingDojoBlackbelt3EndBattleText"] = "哎哟！\n手指撞伤了！",
  ["_FightingDojoBlackbelt4AfterBattleText"] = "全国各地的\n顶尖格斗家都在这里训练。",
  ["_FightingDojoBlackbelt4BattleText"] = "喝啊！\f竟敢闯入我们的\n格斗道场！",
  ["_FightingDojoBlackbelt4EndBattleText"] = "呃！\n我认输！",
  ["_FightingDojoHitmonchanPokeBallText"] = "你想要拳击如活塞的\n快拳郎吗？",
  ["_FightingDojoHitmonleePokeBallText"] = "你想要踢击凌厉的\n飞腿郎吗？",
  ["_FightingDojoKarateMasterDefeatedText"] = "喝！\n啊！我输了！",
  ["_FightingDojoKarateMasterIWillGiveYouAPokemonText"] = "的确，是我输了！\f但我求你，\n别把我们的招牌\v当作战利品拿走！\f作为交换，\n我送你一只珍藏的\v格斗属性宝可梦！\f喜欢哪只就选哪只！",
  ["_FightingDojoKarateMasterStayAndTrainWithUsText"] = "喝！\f留下来和我们一起\n练空手道吧！",
  ["_FightingDojoKarateMasterText"] = "哼！\f我是空手道大王，\n这里的首领！\f你想挑战我们？\n那就别指望我手下留情！\f喝啊！",
  ["_FightingDojoText"] = "格斗道场",
  ["_FileDataDestroyedText"] = "存档数据损坏了！",
  ["_FireDefrostedText"] = "{TARGET}身上的冰\n被火焰融化了！",
  ["_FlareonDexEntry"] = "体内有一个火焰囊。\n吸气后，\f能喷出超过摄氏1600度\n的火焰。",
  ["_FlashLightsAreaText"] = "耀眼的闪光\n照亮了周围！",
  ["_FlewUpHighText"] = "\n飞向了高空！",
  ["_FlinchedText"] = "{USER}\n畏缩了！",
  ["_FluteWokeUpText"] = "所有睡着的宝可梦\n都醒了。",
  ["_ForgotAndText"] = "\f{RAM:wLearnMoveMonName}忘记了\n{RAM:wNameBuffer}！\f然后……",
  ["_FoundHiddenCoins2Text"] = "{PLAYER}找到了\n{NUM:hCoins, 2 | LEADING_ZEROES | LEFT_ALIGN}枚代币！",
  ["_FoundHiddenCoinsText"] = "{PLAYER}找到了\n{NUM:hCoins, 2 | LEADING_ZEROES | LEFT_ALIGN}枚代币！",
  ["_FoundHiddenItemText"] = "{PLAYER}找到了\n{RAM:wNameBuffer}！",
  ["_FoundItemText"] = "{PLAYER}找到了\n{RAM:wStringBuffer}！",
  ["_FrozenText"] = "{TARGET}\n陷入了冰冻状态！",
  ["_FuchsiaBillsGrandpasHouseBillsGrandpaText"] = "嗯？你见过正辉？\f他是我的孙子！\f他从小就喜欢\n收集东西！",
  ["_FuchsiaBillsGrandpasHouseMiddleAgedWomanText"] = "野生原野区的园长\n虽然上了年纪，\v却依然很有活力！\f不过，他的牙\n全是假牙。",
  ["_FuchsiaBillsGrandpasHouseYoungsterText"] = "正辉会把自己的\n宝可梦资料存在电脑里！\f他给你看过吗？",
  ["_FuchsiaCityChanseySignText"] = "名称：吉利蛋\f能否收服它\n全凭运气。",
  ["_FuchsiaCityErikText"] = "埃里克：莎拉在哪儿？\n说好在这里见面的。",
  ["_FuchsiaCityFossilSignKabutoText"] = "名称：化石盔\f从化石复活的\n宝可梦。",
  ["_FuchsiaCityFossilSignOmanyteText"] = "名称：菊石兽\f从化石复活的\n宝可梦。",
  ["_FuchsiaCityFossilSignUndeterminedText"] = "……",
  ["_FuchsiaCityGamblerText"] = "野生原野区的入口前\n有一座动物园。\f后方则是可以\n收服宝可梦的\v狩猎游戏区。",
  ["_FuchsiaCityGymSignText"] = "浅红市\n宝可梦道馆\v馆主：阿桔\f剧毒的忍者大师！",
  ["_FuchsiaCityKangaskhanSignText"] = "名称：袋兽\f会把孩子放在腹部的\n育儿袋中养育，\v充满母爱的宝可梦。",
  ["_FuchsiaCityLaprasSignText"] = "名称：拉普拉斯\f又名海上之王。",
  ["_FuchsiaCityPokecenterGuyText"] = "如果你在研究宝可梦，\n就去野生原野区吧。\f那里有各种\n珍稀宝可梦。",
  ["_FuchsiaCityPokemonText"] = "!",
  ["_FuchsiaCitySafariGameSignText"] = "狩猎游戏\n宝可梦任你抓！",
  ["_FuchsiaCitySafariZoneSignText"] = "宝可梦乐园\n野生原野区",
  ["_FuchsiaCitySignText"] = "浅红市\n看吧！热情的粉红之城！",
  ["_FuchsiaCitySlowpokeSignText"] = "名称：呆呆兽\f性格友善，\n动作非常迟缓。",
  ["_FuchsiaCityVoltorbSignText"] = "名称：霹雳电球\f外形酷似精灵球。",
  ["_FuchsiaCityWardensHomeSignText"] = "野生原野区\n园长的家",
  ["_FuchsiaCityYoungster1Text"] = "参加过狩猎游戏吗？\n有些宝可梦\v只能在那里收服。",
  ["_FuchsiaCityYoungster2Text"] = "里面的道具球\n其实是宝可梦。",
  ["_FuchsiaGoodRodHouseFishingGuruHowAreTheFishText"] = "你好，{PLAYER}！\f鱼儿上钩了吗？",
  ["_FuchsiaGoodRodHouseFishingGuruNoRoomText"] = "哎呀！\f没有空间放我的礼物了！",
  ["_FuchsiaGoodRodHouseFishingGuruReceivedGoodRodText"] = "太棒了！我喜欢\n你的作风！\f年轻人，拿着这个\n去钓鱼吧！\f{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_FuchsiaGoodRodHouseFishingGuruText"] = "我是钓鱼大师的哥哥！\f我最——喜欢钓鱼！\f你喜欢钓鱼吗？",
  ["_FuchsiaGoodRodHouseFishingGuruThatsSoDisappointingText"] = "哦……真令人失望……",
  ["_FuchsiaGymGymGuideBeatKogaText"] = "如今忍者仍然\n如此可怕，真惊人！",
  ["_FuchsiaGymGymGuideChampInMakingText"] = "哟！未来的冠军！\f浅红道馆里\n到处都是隐形墙！\f阿桔看似近在眼前，\n其实被墙挡住了！\f找到墙上的缺口\n才能走到他那里！",
  ["_FuchsiaGymKogaBeforeBattleText"] = "阿桔：哇哈哈哈！\f你这小孩子\n也敢挑战我？\f很好！就让你见识\n忍者大师真正的恐怖！\f感受剧毒和催眠招式\n带来的绝望吧！",
  ["_FuchsiaGymKogaPostBattleAdviceText"] = "中了剧毒后，\n宝可梦会随着战斗进行\v受到越来越多的伤害！\f它一定能让对手\n胆战心惊！",
  ["_FuchsiaGymKogaReceivedSoulBadgeText"] = "哼！\n你证明了自己的实力！\f拿去！\n这是粉红徽章！",
  ["_FuchsiaGymKogaReceivedTM06Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_FuchsiaGymKogaSoulBadgeInfoText"] = "拥有粉红徽章后，\n宝可梦的防御会提升！\f它还能让你在战斗外\n使用冲浪！\f啊！这个也拿去！",
  ["_FuchsiaGymKogaTM06ExplanationText"] = "\f招式学习器06里是\n剧毒！\f这是有400多年历史的\n秘密招式！",
  ["_FuchsiaGymKogaTM06NoRoomText"] = "孩子，先给这个\n腾出位置！",
  ["_FuchsiaGymRocker1AfterBattleText"] = "原来你把力量\n和头脑结合起来了？\v好策略！",
  ["_FuchsiaGymRocker1BattleText"] = "对宝可梦来说，\n力量不是关键！\f关键是策略！\f让你看看策略如何\n战胜蛮力！",
  ["_FuchsiaGymRocker1EndBattleText"] = "什么？\n太厉害了！",
  ["_FuchsiaGymRocker2AfterBattleText"] = "我要继续跟随\n忍者大师阿桔修行！",
  ["_FuchsiaGymRocker2BattleText"] = "我想成为忍者，\n所以加入了这座道馆！",
  ["_FuchsiaGymRocker2EndBattleText"] = "我完了！",
  ["_FuchsiaGymRocker3AfterBattleText"] = "我喜欢剧毒和\n催眠招式，\v因为对战结束后\v效果还会持续！",
  ["_FuchsiaGymRocker3BattleText"] = "看你能不能破解\n我的特殊招式！",
  ["_FuchsiaGymRocker3EndBattleText"] = "你\n骗过我了！",
  ["_FuchsiaGymRocker4AfterBattleText"] = "你让我刮目相看！\n给你一个提示！\f仔细寻找\n隐形墙的缺口！",
  ["_FuchsiaGymRocker4BattleText"] = "站住！\f隐形墙让你\n不知所措了吧？",
  ["_FuchsiaGymRocker4EndBattleText"] = "哇！\n他找到诀窍了！",
  ["_FuchsiaGymRocker5AfterBattleText"] = "我还有很多\n要学的东西！",
  ["_FuchsiaGymRocker5BattleText"] = "我也跟随阿桔大师\n修习忍者之道！\f忍者利用动物的历史\n十分悠久！",
  ["_FuchsiaGymRocker5EndBattleText"] = "嗷！",
  ["_FuchsiaGymRocker6AfterBattleText"] = "有光的地方\n就有影子！\f光与影！\n你会选择哪一边？",
  ["_FuchsiaGymRocker6BattleText"] = "阿桔大师出身于\n世代相传的忍者家族！\f你的祖先又是什么人？",
  ["_FuchsiaGymRocker6EndBattleText"] = "我的球\n掉了！",
  ["_FuchsiaMartCooltrainerFText"] = "试过速度强化吗？\n能在对战中\v提升宝可梦的速度！",
  ["_FuchsiaMartMiddleAgedManText"] = "你有野生原野区的\n旗帜吗？\f卡片或日历呢？",
  ["_FuchsiaMeetingRoomSafariZoneWorker1"] = "我们给园长起了个外号，\n叫“呆呆兽”。\f他和呆呆兽一样\n看起来总在发呆！",
  ["_FuchsiaMeetingRoomSafariZoneWorker2"] = "“呆呆兽”很了解宝可梦！\f他甚至收藏着\n珍稀灭绝宝可梦的化石！",
  ["_FuchsiaMeetingRoomSafariZoneWorker3"] = "“呆呆兽”刚才来了，\n可我听不懂他在说什么。\f我觉得他说话有问题！",
  ["_FuchsiaPokecenterCooltrainerFText"] = "常青市西边\n有一条狭窄的小路。\f那里通往\n宝可梦联盟总部。\v总部管理所有训练家。",
  ["_FuchsiaPokecenterRockerText"] = "只靠一只强大的宝可梦\n是无法获胜的。\f虽然很辛苦，\n但必须均衡培育它们。",
  ["_FullHealText"] = "{RAM:wNameBuffer}\n恢复正常了！",
  ["_FullyParalyzedText"] = "{USER}\n因麻痹无法行动！",
  ["_GainedText"] = "{RAM:wNameBuffer}获得了\n",
  ["_GameCornerBeauty1Text"] = "欢迎！\f你可以到隔壁\n用代币兑换\v丰厚的奖品。",
  ["_GameCornerBeauty2Text"] = "我觉得这些机器的\n中奖概率各不相同。",
  ["_GameCornerClerkCantAffordTheCoinsText"] = "你的钱不够，\n买不了代币！",
  ["_GameCornerClerkCoinCaseIsFullText"] = "哎呀！你的代币盒\n已经满了。",
  ["_GameCornerClerkDoYouNeedSomeGameCoinsText"] = "欢迎来到\n火箭队游戏城！\f需要代币吗？\f50枚代币售价¥1000。\n要买吗？",
  ["_GameCornerClerkDontHaveCoinCaseText"] = "你没有代币盒！",
  ["_GameCornerClerkPleaseComePlaySometimeText"] = "不买吗？有空来玩！",
  ["_GameCornerClerkThanksHereAre50CoinsText"] = "谢谢！这是\n你的50枚代币！",
  ["_GameCornerCoinCaseText"] = "必须持有\n代币盒！",
  ["_GameCornerFishingGuru1DontNeedMyCoinsText"] = "你不需要\n我的代币！",
  ["_GameCornerFishingGuru1Received10CoinsText"] = "{PLAYER}获得了\n10枚代币！",
  ["_GameCornerFishingGuru1WantToPlayText"] = "小子，想玩吗？",
  ["_GameCornerFishingGuru1WinsComeAndGoText"] = "有赢就有输。",
  ["_GameCornerFishingGuru2CloselyWatchTheReelsText"] = "诀窍是仔细\n盯住转轴！",
  ["_GameCornerFishingGuru2Received20CoinsText"] = "{PLAYER}获得了\n20枚代币！",
  ["_GameCornerFishingGuru2ThrowingMeOffText"] = "喂，怎么回事？\n你害我分心了！\v给你些代币，\n快走吧！",
  ["_GameCornerFishingGuru2YouGotYourOwnCoinsText"] = "你自己不是有代币吗！",
  ["_GameCornerGamblerText"] = "赌博真可怕！\n太容易上瘾了！",
  ["_GameCornerGymGuideChampInMakingText"] = "嘿！\f未来的冠军，\n你还有更该做的事吧！\f玉虹道馆的馆主\n是莉佳！\v她使用草属性宝可梦！\f她看起来很温顺，\n可别被骗了！",
  ["_GameCornerGymGuideTheyOfferRarePokemonText"] = "这里提供珍稀宝可梦，\n可以用代币兑换。\f可我就是赢不了！",
  ["_GameCornerMiddleAgedMan1Text"] = "别声张。\f听说这里由\n火箭队经营。",
  ["_GameCornerMiddleAgedMan2INeedMoreCoinsText"] = "可恶！我还需要\n更多代币，\v才能换到想要的宝可梦！",
  ["_GameCornerMiddleAgedMan2Received20CoinsText"] = "{PLAYER}获得了\n20枚代币！",
  ["_GameCornerMiddleAgedMan2WantSomeCoinsText"] = "怎么了？\n想要些代币吗？",
  ["_GameCornerMiddleAgedMan2YouHaveLotsOfCoinsText"] = "你已经有很多代币了！",
  ["_GameCornerMiddleAgedWomanText"] = "我玩得非常开心！",
  ["_GameCornerNoCoinsText"] = "你一枚代币也没有！",
  ["_GameCornerOopsForgotCoinCaseText"] = "哎呀！忘带代币盒了！",
  ["_GameCornerOutOfOrderText"] = "暂停使用\n机器坏了。",
  ["_GameCornerOutToLunchText"] = "外出用餐\n此机已被预留。",
  ["_GameCornerPosterSwitchBehindPosterText"] = "咦！\f海报后面有个开关！？\n按下去看看！",
  ["_GameCornerPrizeRoomBaldingGuyText"] = "我真想要那只\n多边兽！\f可老虎机太难赢了！",
  ["_GameCornerPrizeRoomGamblerText"] = "我今天赢了一大笔！",
  ["_GameCornerRocketAfterBattleText"] = "我们的藏身处\n可能会被发现！\v得赶快报告老大！",
  ["_GameCornerRocketBattleEndText"] = "可恶！",
  ["_GameCornerRocketImGuardingThisPosterText"] = "我负责看守这张海报！\n快走，不然有你好看！",
  ["_GameCornerSomeonesKeysText"] = "是某人的钥匙！\n对方还会回来的。",
  ["_GameOverText"] = "广播：你的狩猎游戏\n结束了！",
  ["_GameSavedText"] = "{PLAYER}保存了游戏！",
  ["_GastlyDexEntry"] = "据说会出现在\n破败无人的建筑中。\f似乎由气体构成，\n没有固定形态。",
  ["_GengarDexEntry"] = "如果突然感到寒意，\n说明耿鬼就在附近。\f它可能正想\n诅咒你。",
  ["_GeodudeDexEntry"] = "常见于山路附近。\f不小心踩到它，\n它就会生气。",
  ["_GetDexRatedText"] = "要请大木博士\n评价宝可梦图鉴吗？",
  ["_GetOutText"] = "幽灵：出去……\n出去……",
  ["_GetmText"] = "上啊！",
  ["_GettingPumpedText"] = "{USER}\n鼓足了干劲！",
  ["_GhostCantBeIDdText"] = "可恶！无法识别\n这个幽灵！",
  ["_GloomDexEntry"] = "气味难闻至极！\n不过每1000人中\f大约有1人喜欢\n闻这种刺鼻的臭味。",
  ["_GoText"] = "上吧！",
  ["_GolbatDexEntry"] = "会悄无声息地\n突然发动攻击。\f用锋利的獠牙\n咬住猎物吸血。",
  ["_GoldeenDexEntry"] = "产卵季节，\n它们会成群结队地\f逆流游过河川和瀑布。",
  ["_GolduckDexEntry"] = "修长的四肢末端\n长着宽大的蹼。\f会用它们在湖中\n优雅地游泳。",
  ["_GolemDexEntry"] = "蜕皮后，\n身体会变得柔软而发白。\f接触空气后，\n外皮便会变硬。",
  ["_GoodText"] = "很好！",
  ["_GotAwayText"] = "成功逃走了！",
  ["_GotMapText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_GotMonText"] = "{PLAYER}获得了\n{RAM:wNameBuffer}！",
  ["_GotOffBicycleText1"] = "{PLAYER}下了",
  ["_GotOffBicycleText2"] = "{RAM:wStringBuffer}。",
  ["_GotOnBicycleText1"] = "{PLAYER}骑上了",
  ["_GotOnBicycleText2"] = "{RAM:wStringBuffer}！",
  ["_GravelerDexEntry"] = "经常能看到它\n沿着山路滚下。\f遇到障碍也不会躲，\n而是直接碾过去。",
  ["_GreatlyFellText"] = "{SCROLL}大幅",
  ["_GreatlyRoseText"] = "{SCROLL}大幅",
  ["_GrewLevelText"] = "{RAM:wNameBuffer}升到了\n{NUM:wCurEnemyLevel, 1, 3}级！",
  ["_GrimerDexEntry"] = "由硬化的污泥构成，\n臭得令人不敢触碰。\f它经过的地方\n连杂草都无法生长。",
  ["_GroundRoseText"] = "某处的地面\n升了起来！",
  ["_GrowlitheDexEntry"] = "性格亲切友善。\n但有东西闯入领地时，\f就会凶猛地吠叫。",
  ["_GyaradosDexEntry"] = "性情极其凶暴，\n破坏力惊人。\f据说古代曾将\n整座城市彻底摧毁。",
  ["_GymStatueText1"] = "{RAM:wGymCityName}\n宝可梦道馆\v馆主：{RAM:wGymLeaderName}\f获胜的训练家：\n{RIVAL}",
  ["_GymStatueText2"] = "{RAM:wGymCityName}\n宝可梦道馆\v馆主：{RAM:wGymLeaderName}\f获胜的训练家：\n{RIVAL}\v{PLAYER}",
  ["_HMCantDeleteText"] = "秘传招式\n无法忘记！",
  ["_HallOfFameOakText"] = "大木博士：咳咳！\n恭喜你，{PLAYER}！\f这里是宝可梦\n名人堂！\f宝可梦联盟冠军的\n伟大功绩会在此受到表彰！\f他们的宝可梦\n也会被记录在名人堂！\f{PLAYER}！\n你付出了许多努力，\v终于成为新任\v联盟冠军！\f恭喜你，{PLAYER}！\n你和宝可梦都\v成为名人堂成员了！",
  ["_HasSubstituteText"] = "{USER}\n已经有替身了！",
  ["_HaunterDexEntry"] = "舔舐会夺走\n受害者的生命。\f会让对方不断颤抖，\n直到失去生命。",
  ["_HereYouGoText"] = "给你！",
  ["_HiddenItemBagFullText"] = "但是，{PLAYER}\n已经没有空间\v放其他道具了！",
  ["_HisNameIsText"] = "对了！我想起来了！\n他的名字是{RIVAL}！",
  ["_HitWithRecoilText"] = "{USER}\n受到了反作用力伤害！",
  ["_HitXTimesText"] = "击中了{NUM:wEnemyNumHits, 1, 1}次！",
  ["_HitmonchanDexEntry"] = "拳头像螺旋一样旋转。\n如同钻头一般，\f甚至能击穿混凝土墙。",
  ["_HitmonleeDexEntry"] = "踢击命中时，\n脚底会变得坚硬如钻石，\f以此重创敌人。",
  ["_HookedMonAttackedText"] = "上钩的{RAM:wEnemyMonNick}\n发动了攻击！",
  ["_HorseaDexEntry"] = "察觉危险时，\n会从嘴里猛烈喷出\f水或特殊的墨汁。",
  ["_HurtByBurnText"] = "灼伤使{USER}\n受到了伤害！",
  ["_HurtByLeechSeedText"] = "寄生种子吸取了\n{USER}的体力！",
  ["_HurtByPoisonText"] = "中毒使{USER}\n受到了伤害！",
  ["_HurtItselfText"] = "它在混乱中\n伤害了自己！",
  ["_HypnoDexEntry"] = "遇到它时要避免\n与它目光接触。\f它会摆动钟摆，\n试图让你入睡。",
  ["_IceHealText"] = "{RAM:wNameBuffer}\n解冻了！",
  ["_IgnoredOrdersText"] = "{RAM:wBattleMonNick}\n无视了指示！",
  ["_IndigoPlateauHQText"] = "石英高原\n宝可梦联盟总部",
  ["_IndigoPlateauLobbyCooltrainerFText"] = "从这里开始，\n你要逐一挑战四天王！\f每次获胜，\n通往下一位训练家的门\v就会打开！\v祝你好运！",
  ["_IndigoPlateauLobbyGymGuideText"] = "哟！未来的冠军！\f在宝可梦联盟，\n你必须连续挑战四天王。\f一旦落败，\n就得从头再来！\v决战时刻到了！\v加油吧！",
  ["_IndigoPlateauStatuesText1"] = "石英高原",
  ["_IndigoPlateauStatuesText2"] = "训练家的终极目标！\n宝可梦联盟总部",
  ["_IndigoPlateauStatuesText3"] = "宝可梦界的最高权威\n宝可梦联盟总部",
  ["_IntoText"] = "\n进化成了{RAM:wNameBuffer}！",
  ["_IntroducePlayerText"] = "首先，请告诉我\n你的名字。",
  ["_IntroduceRivalText"] = "这是我的孙子。\n他从小就是\v你的劲敌。\v……嗯？\f他的名字是\n什么来着？",
  ["_IsConfusedText"] = "{USER}\n陷入了混乱！",
  ["_IsEvolvingText"] = "什么？{RAM:wStringBuffer}\n正在进化！",
  ["_IsFrozenText"] = "{USER}\n被冻住了！",
  ["_IsItOKToTossItemText"] = "要丢弃\n{RAM:wStringBuffer}吗？",
  ["_IsUnaffectedText"] = "对{TARGET}\n没有影响！",
  ["_ItemUseBallText00"] = "它躲开了投出的\n精灵球！\f这只宝可梦\n无法收服！",
  ["_ItemUseBallText01"] = "没扔中\n宝可梦！",
  ["_ItemUseBallText02"] = "可恶！宝可梦\n挣脱了！",
  ["_ItemUseBallText03"] = "啊！看起来\n就要抓住了！",
  ["_ItemUseBallText04"] = "真可惜！明明\n只差一点了！",
  ["_ItemUseBallText05"] = "好！\n抓到{RAM:wEnemyMonNick}了！",
  ["_ItemUseBallText06"] = "将把{RAM:wEnemyMonNick}的\n新资料添加到\v宝可梦图鉴！",
  ["_ItemUseBallText07"] = "{RAM:wBoxMonNicks}\n传送到了正辉的电脑！",
  ["_ItemUseBallText08"] = "{RAM:wBoxMonNicks}\n传送到了某人的电脑！",
  ["_ItemUseNoEffectText"] = "没有任何效果。",
  ["_ItemUseNotTimeText"] = "大木博士：{PLAYER}！\n现在不是\v使用它的时候！",
  ["_ItemUseNotYoursToUseText"] = "这不是你的，\n不能使用！",
  ["_ItemUseText001"] = "{PLAYER}使用了",
  ["_ItemUseText002"] = "{RAM:wStringBuffer}！",
  ["_ItemWasStoredText"] = "{RAM:wNameBuffer}\n已存入电脑。",
  ["_ItemfinderFoundItemText"] = "好！探宝器显示\n附近有道具。",
  ["_ItemfinderFoundNothingText"] = "没有！探宝器\n毫无反应。",
  ["_ItemsCantBeUsedHereText"] = "这里不能\n使用道具。",
  ["_ItsABiteText"] = "哦！\n有鱼上钩了！",
  ["_IvysaurDexEntry"] = "背上的花苞通过\n吸收能量成长。\f快要开花时，\n会散发香气。",
  ["_JigglypuffDexEntry"] = "用迷人的眼睛\n吸引对手。\f接着唱出悦耳旋律，\n让对手睡着。",
  ["_JolteonDexEntry"] = "性情敏感，\n很容易悲伤或愤怒。\f每当情绪变化，\n都会积蓄电力。",
  ["_JustAMomentText"] = "请稍等。",
  ["_JynxDexEntry"] = "动作仿佛遵循着\n独特的节奏，像在跳舞。\f走路时会\n左右扭动腰部。",
  ["_KabutoDexEntry"] = "从化石中复原的\n宝可梦。\f潜伏在海底时，\n会用背上的眼睛观察。",
  ["_KabutopsDexEntry"] = "身形纤细，游速很快。\n会用锋利的镰刀\f切开猎物，\n吸取体液。",
  ["_KabutopsFossilText"] = "镰刀盔的化石\n原始而稀有的\v宝可梦。",
  ["_KadabraDexEntry"] = "只要它在附近，\n就会发生许多怪事。\f例如让时钟\n倒着走。",
  ["_KakunaDexEntry"] = "只能稍微移动。\n遇到危险时，\f会伸出毒针\n使敌人中毒。",
  ["_KangaskhanDexEntry"] = "把孩子养在\n腹部的育儿袋里。\f为了保护孩子，\n绝不会逃避任何战斗。",
  ["_KeptGoingAndCrashedText"] = "{USER}\n一直向前冲，\v撞了上去！",
  ["_KinglerDexEntry"] = "一只钳子变得\n巨大且坚硬如钢。\f拥有1万马力，\n但实在太重了。",
  ["_KoffingDexEntry"] = "在炎热的地方，\n体内气体可能膨胀，\f毫无预警地爆炸。\n务必小心！",
  ["_KrabbyDexEntry"] = "钳子是出色的武器。\n有时会在战斗中折断，\f但很快就能长回来。",
  ["_LancesRoomLanceAfterBattleText"] = "我还是不敢相信，\n我的龙竟然输给了你，\v{PLAYER}！\f现在你就是\n宝可梦联盟冠军了！\f……本来应该是这样，\n但前面还有一个挑战。\f你还得面对\n另一位训练家！\v他的名字是……\f{RIVAL}！\n他比你更早\v打败了四天王！\f他才是现任的\n宝可梦联盟冠军！",
  ["_LancesRoomLanceBeforeBattleText"] = "啊！我听说过你，\n{PLAYER}！\f我是四天王的首领！\n人称龙使者阿渡！\f你知道龙是\n传说中的宝可梦吧！\f它们很难收服和培育，\n但力量无比强大！\f几乎坚不可摧！\f怎么样，\n准备好落败了吗？\f你的联盟挑战\n就由我来终结，\v{PLAYER}！",
  ["_LancesRoomLanceEndBattleText"] = "就是这样！\f虽然不愿承认，\n但你是宝可梦大师！",
  ["_LaprasDexEntry"] = "性情温和，\n能读懂人类的心。\f会让人坐在背上\n渡过大海。",
  ["_LavenderCuboneHouseBrunetteGirlGhostIsGoneText"] = "宝可梦塔里的幽灵\n消失了！\f一定有人安抚了\n它不安的灵魂！",
  ["_LavenderCuboneHouseBrunetteGirlPoorCubonesMotherText"] = "我讨厌那些\n可恶的火箭队！\f可怜的卡拉卡拉，\n它的妈妈……\f为了逃离火箭队，\n被他们杀死了！",
  ["_LavenderCuboneHouseCuboneText"] = "卡拉卡拉：嘎噜！",
  ["_LavenderMartBaldingGuyText"] = "我在找能于单场对战中\n提升宝可梦能力的道具。\f力量强化、防御强化、\n速度强化和特攻强化，\v就是我要找的。\f你知道哪里能买到吗？",
  ["_LavenderMartCooltrainerMNuggetText"] = "我在山里找到一颗金珠。\f本以为没用，\n结果卖了¥5000！",
  ["_LavenderMartCooltrainerMReviveText"] = "你知道活力碎片吗？\n能让昏厥的宝可梦复活！",
  ["_LavenderPokecenterGentlemanText"] = "为了赚钱，\n火箭队什么都做得出来！",
  ["_LavenderPokecenterGuyText"] = "卡拉卡拉戴着头骨，\n对吧？\f有人愿意花大价钱买！",
  ["_LavenderPokecenterLittleGirlText"] = "我看见卡拉卡拉的妈妈\n为了逃离火箭队而死！",
  ["_LavenderTownCooltrainerMText"] = "这座镇以\n宝可梦墓地闻名。\f宝可梦塔会举行\n追悼仪式。",
  ["_LavenderTownLittleGirlDoYouBelieveInGhostsText"] = "你相信\n幽灵吗？",
  ["_LavenderTownLittleGirlHaHaGuessNotText"] = "哈哈哈，看来你不信。\f你肩上的那只白手，\n不是真的。",
  ["_LavenderTownLittleGirlSoThereAreBelieversText"] = "真的？原来有人相信……",
  ["_LavenderTownPokemonHouseSignText"] = "紫苑镇志愿者\n宝可梦之家",
  ["_LavenderTownPokemonTowerSignText"] = "愿宝可梦的灵魂安息\n宝可梦塔",
  ["_LavenderTownSignText"] = "紫苑镇\n高贵的紫色之镇",
  ["_LavenderTownSilphScopeSignText"] = "新型西尔佛检视镜！\f让隐形之物\n清晰可见！\f西尔佛公司",
  ["_LavenderTownSuperNerdText"] = "宝可梦塔里\n出现了幽灵。\f我想那是被火箭队杀害的\n宝可梦的灵魂。",
  ["_LearnedMove1Text"] = "{RAM:wLearnMoveMonName}学会了\n{RAM:wStringBuffer}！",
  ["_LickitungDexEntry"] = "舌头长近2米，\n比前肢灵活得多。\f被它舔到\n可能会陷入麻痹。",
  ["_LightScreenProtectedText"] = "光墙保护{USER}\n免受特殊攻击！",
  ["_LinedUpText"] = "排成一线！\n赢得{RAM:wStringBuffer}枚代币！",
  ["_LinkBattleLostText"] = "{PLAYER}输给了\n{RAM:wTrainerName}！",
  ["_LinkCableHelpText1"] = "训练家提示\f连接线的使用方法",
  ["_LinkCableHelpText2"] = "想阅读哪个标题？",
  ["_LinkCableInfoText1"] = "用连接线将你的\nGAME BOY与另一台\vGAME BOY连接后，\v去任意宝可梦中心\v和右边的服务员交谈。",
  ["_LinkCableInfoText2"] = "在对战场可以\n和朋友对战。",
  ["_LinkCableInfoText3"] = "交换中心用于\n交换宝可梦。",
  ["_LoafingAroundText"] = "{RAM:wBattleMonNick}\n正在偷懒。",
  ["_LooksContentText"] = "它睡得\n十分香甜。",
  ["_LoreleisRoomLoreleiAfterBattleText"] = "你比我想象中更强！\n继续前进吧！\f你尝到的不过是\n宝可梦联盟力量的\v冰山一角！",
  ["_LoreleisRoomLoreleiBeforeBattleText"] = "欢迎来到\n宝可梦联盟！\f我是四天王之一，\n科拿！\f说到冰属性宝可梦，\n没人能胜过我！\f冰冻招式威力强大！\f你的宝可梦一旦冻住，\n就只能任我摆布！\f哈哈哈！\n准备好了吗？",
  ["_LoreleisRoomLoreleiDontRunAwayText"] = "有人说道：\n不准逃走！",
  ["_LoreleisRoomLoreleiEndBattleText"] = "你\n好大的胆子！",
  ["_LoweredItsHeadText"] = "\n低下了头！",
  ["_MachampDexEntry"] = "仅用一只手臂\n就能推动山岳。\f四只手臂齐用时，\n会打出惊人的重拳。",
  ["_MachokeDexEntry"] = "腰间的带子\n抑制着它的能量。\f如果没有带子，\n它将无人能挡。",
  ["_MachopDexEntry"] = "体型虽小，\n力量却非常强大。\f精通多种格斗技，\n因此十分强悍。",
  ["_MadeWhirlwindText"] = "\n制造了旋风！",
  ["_MagazinesText"] = "宝可梦杂志！\f宝可梦笔记本！\f宝可梦图表！",
  ["_MagikarpDexEntry"] = "出了名地靠不住。\n在海洋、湖泊、河川\f甚至浅水坑中\n都能发现它游动。",
  ["_MagmarDexEntry"] = "诞生于活火山。\n身体始终被火焰包围，\f看起来像一颗\n巨大的火球。",
  ["_MagnemiteDexEntry"] = "天生拥有\n对抗重力的能力。\f借助强力电磁波\n漂浮在空中。",
  ["_MagnetonDexEntry"] = "会产生奇怪的无线电信号。\n在周围1000米内，\f能使气温升高2摄氏度。",
  ["_MankeyDexEntry"] = "动作敏捷，生活在树上。\n很容易发怒，\f会毫不犹豫地\n攻击任何东西。",
  ["_MarowakDexEntry"] = "体型小又弱，\n却很擅长使用骨棒。\f随着岁月流逝，\n性情变得更加凶猛。",
  ["_MartSignText"] = "所需道具一应俱全！\n友好商店",
  ["_MeowthDexEntry"] = "夜晚似乎更加活跃。\n喜欢又圆又亮的东西，\f一看到就忍不住\n捡起来。",
  ["_MetapodDexEntry"] = "硬化外壳保护自己。\n但受到强烈冲击时，\f身体可能会\n从壳里蹦出来。",
  ["_MewDexEntry"] = "用显微镜观察时，\n能看见这种宝可梦\f短而细腻的体毛。",
  ["_MewtwoBattleText"] = "咪呜！",
  ["_MewtwoDexEntry"] = "DNA几乎与梦幻相同。\n但体型和性情\f却截然不同。",
  ["_MimicLearnedMoveText"] = "{USER}\n学会了\v{RAM:wNameBuffer}！",
  ["_MirrorMoveFailedText"] = "鹦鹉学舌失败了！",
  ["_MoltresDexEntry"] = "传说中的鸟宝可梦。\n每当它扇动燃烧的翅膀，\f连夜空都会被染红。",
  ["_MonCannotLearnMachineMoveText"] = "{RAM:wNameBuffer}与\n{RAM:wStringBuffer}不兼容。\f无法学会\n{RAM:wStringBuffer}。",
  ["_MonIsTakenOutText"] = "取出了{RAM:wStringBuffer}。\v把{RAM:wStringBuffer}带在了身上。",
  ["_MonWasReleasedText"] = "放生了{RAM:wStringBuffer}。\v再见，{RAM:wStringBuffer}！",
  ["_MonWasStoredText"] = "把{RAM:wStringBuffer}寄放到\n{RAM:wBoxNumString}号盒子里了。",
  ["_MoneyForWinningText"] = "{PLAYER}获胜后\n得到了¥{NUM:wAmountMoneyWon, 3 | LEADING_ZEROES | LEFT_ALIGN}！",
  ["_MonsStatsFellText"] = "{TARGET}的\n{RAM:wStringBuffer}",
  ["_MonsStatsRoseText"] = "{USER}的\n{RAM:wStringBuffer}",
  ["_MoveDisabledText"] = "该招式\n无法使用！",
  ["_MoveIsDisabledText"] = "{USER}的\n{RAM:wNameBuffer}\v无法使用了！",
  ["_MoveNameText"] = "{RAM:wStringBuffer}！",
  ["_MoveNoPPText"] = "这个招式的\nPP用完了！",
  ["_MoveWasDisabledText"] = "{TARGET}的\n{RAM:wNameBuffer}\v无法使用了！",
  ["_MrFujisHouseLittleGirlPokemonAreNiceToHugText"] = "好温暖啊！\n宝可梦抱起来\v真舒服！",
  ["_MrFujisHouseLittleGirlThisIsMrFujisHouseText"] = "这里确实是\n富士老人的家。\f他真的很善良！\f他会照顾遭遗弃或\n失去亲人的宝可梦！",
  ["_MrFujisHouseMrFujiHasMyFluteHelpedYouText"] = "富士老人：我的笛子\n帮到你了吗？",
  ["_MrFujisHouseMrFujiIThinkThisMayHelpYourQuestText"] = "富士老人：{PLAYER}。\f没有对宝可梦的爱，\n图鉴之旅可能会失败。\f我想这个应该能\n助你一臂之力。",
  ["_MrFujisHouseMrFujiPokeFluteExplanationText"] = "\f宝可梦一听到\n宝可梦之笛，\v就会从睡梦中醒来。\f它对所有睡着的\n宝可梦都有效。",
  ["_MrFujisHouseMrFujiPokeFluteNoRoomText"] = "你得先腾出\n一个位置！",
  ["_MrFujisHouseMrFujiPokedexText"] = "《宝可梦月刊》\n豪华奖品抽奖！\f申请表……\f没了！\n被人剪走了！",
  ["_MrFujisHouseMrFujiReceivedPokeFluteText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_MrFujisHouseNidorinoText"] = "尼多力诺：嘎哦！",
  ["_MrFujisHousePsyduckText"] = "可达鸭：呱啪！",
  ["_MrFujisHouseSuperNerdMrFujiHadBeenPrayingText"] = "富士老人一直在\n独自为卡拉卡拉的\v母亲祈祷。",
  ["_MrFujisHouseSuperNerdMrFujiIsntHereText"] = "真奇怪，富士老人\n不在这里。\v他去哪儿了？",
  ["_MrMimeDexEntry"] = "总是在练习\n哑剧表演。\f它能让敌人相信\n本不存在的东西\v真的存在。",
  ["_MrPsychicsHouseMrPsychicReceivedTM29Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_MrPsychicsHouseMrPsychicTM29ExplanationText"] = "招式学习器29是\n精神强念！\f它有时能降低\n对手的特殊能力。",
  ["_MrPsychicsHouseMrPsychicTM29NoRoomText"] = "你打算把它\n放在哪里？",
  ["_MrPsychicsHouseMrPsychicYouWantedThisText"] = "……等等！\n别出声！\f你想要的是这个！",
  ["_MtMoon1FBewareZubatSign"] = "小心！超音蝠会\n吸血！",
  ["_MtMoon1FCooltrainerF1AfterBattleText"] = "这里要怎么\n出去啊？",
  ["_MtMoon1FCooltrainerF1BattleText"] = "哇！这里比\n我想的\v大多了！",
  ["_MtMoon1FCooltrainerF1EndBattleText"] = "啊！\n我输了！",
  ["_MtMoon1FCooltrainerF2AfterBattleText"] = "听说这里有\n非常稀有的\v化石。",
  ["_MtMoon1FCooltrainerF2BattleText"] = "什么？我在这里\n等朋友们来\v找我呢。",
  ["_MtMoon1FCooltrainerF2EndBattleText"] = "我输了？",
  ["_MtMoon1FHikerAfterBattleText"] = "你这种小孩\n不该到\v这里来！",
  ["_MtMoon1FHikerBattleText"] = "哇！你吓到\n我了！原来\v只是个小孩！",
  ["_MtMoon1FHikerEndBattleText"] = "哇！\n又被吓到了！",
  ["_MtMoon1FSuperNerdAfterBattleText"] = "我得去找\n更强的宝可梦。",
  ["_MtMoon1FSuperNerdBattleText"] = "什么！别偷偷\n靠近我！",
  ["_MtMoon1FSuperNerdEndBattleText"] = "我的\n宝可梦还不够强！",
  ["_MtMoon1FYoungster1AfterBattleText"] = "我是来这里\n向女孩子们\v炫耀的。",
  ["_MtMoon1FYoungster1BattleText"] = "你也是来\n探险的吗？",
  ["_MtMoon1FYoungster1EndBattleText"] = "输掉对战\n真糟糕！",
  ["_MtMoon1FYoungster2AfterBattleText"] = "我见过他们！\n他们肯定是\v火箭队的人！",
  ["_MtMoon1FYoungster2BattleText"] = "山洞里有\n可疑的人。\v你呢？",
  ["_MtMoon1FYoungster2EndBattleText"] = "居然被你\n打败了！",
  ["_MtMoon1FYoungster3AfterBattleText"] = "超音蝠很难对付！\n不过，如果\v能抓到一只，\v就会很有用。",
  ["_MtMoon1FYoungster3BattleText"] = "穿过这座\n山洞就能到\v华蓝市！",
  ["_MtMoon1FYoungster3EndBattleText"] = "我\n输了。",
  ["_MtMoonB1FUnusedText"] = "（未使用）",
  ["_MtMoonB2FDomeFossilYouWantText"] = "你要\n甲壳化石？",
  ["_MtMoonB2FHelixFossilYouWantText"] = "你要\n贝壳化石？",
  ["_MtMoonB2FReceivedFossilText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_MtMoonB2FRocket2AfterBattleText"] = "可恶！我的\n同伴不会\v放过你的！",
  ["_MtMoonB2FRocket2BattleText"] = "我们火箭队，\n可是宝可梦\v犯罪集团！",
  ["_MtMoonB2FRocket2EndBattleText"] = "我搞\n砸了！",
  ["_MtMoonB2FRocket3AfterBattleText"] = "找到化石就\n交给我，\v然后滚开！",
  ["_MtMoonB2FRocket3BattleText"] = "我们正在干\n一票大买卖！\v小鬼，滚开！",
  ["_MtMoonB2FRocket3EndBattleText"] = "原来你\n还挺厉害。",
  ["_MtMoonB2FRocket4AfterBattleText"] = "人类来到这里前，\n宝可梦早就\v住在这里了。",
  ["_MtMoonB2FRocket4BattleText"] = "小孩子\n别来打扰\v大人！",
  ["_MtMoonB2FRocket4EndBattleText"] = "我真\n火大！",
  ["_MtMoonB2FSuperNerdOkIllShareText"] = "好吧！\n分你一个！",
  ["_MtMoonB2FSuperNerdThenThisIsMineText"] = "好吧。那么\n这个归我！",
  ["_MtMoonB2FSuperNerdTheresAPokemonLabText"] = "在遥远的\n红莲镇，\v有一座宝可梦\v研究所。\f那里正在研究\n如何复原\v化石。",
  ["_MtMoonB2FSuperNerdTheyreBothMineText"] = "喂，住手！\f这些化石\n是我找到的！\v全都归我！",
  ["_MtMoonB2FYouHaveNoRoomText"] = "看，你已经\n没空间放它了。",
  ["_MtMoonB2fSuperNerdEachTakeOneText"] = "我们一人拿\n一个！\v不许贪心！",
  ["_MtMoonJessieJamesText1"] = "站住！",
  ["_MtMoonJessieJamesText2"] = "那块化石\n是火箭队的！\f立刻投降，\n否则就开战！",
  ["_MtMoonJessieJamesText3"] = "我们竟被\n小鬼打败了？",
  ["_MtMoonJessieJamesText4"] = "火箭队要\n以光速\v飞走啦！",
  ["_MtMoonPokecenterBenchGuyText"] = "宝可梦太多时，\n就应该用\v电脑把它们\v存起来！",
  ["_MtMoonPokecenterGentlemanText"] = "火箭队正在\n袭击华蓝市的\v居民……\f火箭队总是\n出现在\v新闻里！",
  ["_MtMoonPokecenterClipboardText"] = "（未使用）",
  ["_MtMoonPokecenterMagikarpSalesmanIGotADealText"] = "男子：你好！\n有个好买卖\v只留给你！\f这只厉害的\n鲤鱼王\v只卖¥500！\v怎么样？",
  ["_MtMoonPokecenterMagikarpSalesmanNoMoneyText"] = "你的钱\n还不够！",
  ["_MtMoonPokecenterMagikarpSalesmanNoRefundsText"] = "男子：这个嘛，\n我可不会退款！",
  ["_MtMoonPokecenterMagikarpSalesmanNoText"] = "不要？我可是\n为了帮你才\v这么做的！",
  ["_MtMoonPokecenterYoungsterText"] = "我的腰带上\n挂着6个精灵球。\f最多只能携带\n6只宝可梦。",
  ["_MukDexEntry"] = "恶臭强烈到足以\n让人昏厥。\f由于身体退化，\n它已经失去嗅觉。",
  ["_MultiHitText"] = "击中对手\n{NUM:wPlayerNumHits, 1, 1}次！",
  ["_Museum1FGamblerText"] = "这化石\n真是壮观！",
  ["_Museum1FOldAmberText"] = "这块琥珀\n清澈又金黄！",
  ["_Museum1FScientist1AmberIsFossilizedTreeSapText"] = "琥珀是\n树脂形成的化石。",
  ["_Museum1FScientist1ComeAgainText"] = "欢迎再来！",
  ["_Museum1FScientist1DoYouKnowWhatAmberIsText"] = "不许从后门\n偷偷溜进来！\f哎，算了！\n你知道琥珀是什么吗？",
  ["_Museum1FScientist1DontHaveEnoughMoneyText"] = "你的钱\n不够。",
  ["_Museum1FScientist1GoToOtherSideText"] = "请从\n另一边进去！",
  ["_Museum1FScientist1TakePlentyOfTimeText"] = "请慢慢参观！",
  ["_Museum1FScientist1ThankYouText"] = "好的，¥50！\n谢谢！",
  ["_Museum1FScientist1TheresALabSomewhereText"] = "有家研究所\n正在尝试用琥珀\v复活古代宝可梦。",
  ["_Museum1FScientist1WouldYouLikeToComeInText"] = "儿童票价是\n¥50。\f要进来参观吗？",
  ["_Museum1FScientist2GetTheOldAmberCheckText"] = "嘘！拿秘密琥珀\n去鉴定吧！",
  ["_Museum1FScientist2ReceivedOldAmberText"] = "{PLAYER}获得了\n秘密琥珀！",
  ["_Museum1FScientist2TakeThisToAPokemonLabText"] = "嘘！我认为这块\n琥珀里含有\v宝可梦的DNA！\f如果真能用它\n复活宝可梦，\v那就太棒了！\f可同事们\n根本不理我！\f所以，我有件事\n想拜托你！\f把它带到\n宝可梦研究所，\v请他们鉴定吧！",
  ["_Museum1FScientist2YouDontHaveSpaceText"] = "你没有\n多余的空间！",
  ["_Museum1FScientist3Text"] = "我们以这两块\n极为稀有的\v史前宝可梦化石\v为荣！",
  ["_Museum2FBrunetteGirlText"] = "我想要皮卡丘！\n它太可爱了！\f我让爸爸\n给我捉一只！",
  ["_Museum2FGrampsText"] = "1969年7月20日！\f人类首次\n登上月球！\f我特意买了彩电\n观看直播！",
  ["_Museum2FHikerText"] = "我保证，很快\n就给你皮卡丘！",
  ["_Museum2FMoonStoneSignText"] = "坠落在月见山的\n陨石。\v（是月之石吗？）",
  ["_Museum2FPikachuText1"] = "你的皮卡丘\n还不太亲近人。\v能把它送给\n我女儿吗？",
  ["_Museum2FPikachuText2"] = "我很想要\n那只皮卡丘，\v可它太依恋你了。",
  ["_Museum2FScientistText"] = "现在正举办\n太空展。",
  ["_Museum2FSpaceShuttleSignText"] = "哥伦比亚号\n航天飞机",
  ["_Museum2FYoungsterText"] = "月之石？\f它有什么特别的？",
  ["_MustRechargeText"] = "{USER}\n必须休息！",
  ["_NameRatersHouseNameRaterATrulyImpeccableNameText"] = "{RAM:wNameBuffer}，对吧？\n真是个\v无可挑剔的名字！\f要好好照顾\n{RAM:wNameBuffer}！",
  ["_NameRatersHouseNameRaterComeAnyTimeYouLikeText"] = "好！想来随时都可以！",
  ["_NameRatersHouseNameRaterGiveItANiceNameText"] = "{RAM:wNameBuffer}，对吧？\n这昵称还不错！\f不过，要不要让我\n给它取个更好的名字？\f怎么样？",
  ["_NameRatersHouseNameRaterPokemonHasBeenRenamedText"] = "好！这只宝可梦\n已经改名为\v{RAM:wBuffer}！\f比原来的名字\n更棒！",
  ["_NameRatersHouseNameRaterWantMeToRateText"] = "你好，你好！\n我是官方认证的\v姓名判断师！\f想让我评价一下\n你宝可梦的昵称吗？",
  ["_NameRatersHouseNameRaterWhatShouldWeNameItText"] = "好！要给它\n取什么名字？",
  ["_NameRatersHouseNameRaterWhichPokemonText"] = "要看哪只\n宝可梦？",
  ["_NeedYourPokemonText"] = "好的，请把\n宝可梦交给我们。",
  ["_NewBadgeRequiredText"] = "不行！需要获得\n新的徽章。",
  ["_NewBicycleText"] = "崭新的\n闪亮自行车！",
  ["_NidokingDexEntry"] = "钢铁般的皮肤\n增强了撞击的威力。\f它的角极其坚硬，\n甚至能刺穿钻石。",
  ["_NidoqueenDexEntry"] = "坚硬的鳞片\n覆盖着结实的身体。\f这些鳞片似乎会\n周期性生长。",
  ["_NidoranFDexEntry"] = "性情温顺，\n不喜欢战斗。\f但要小心，它的小角\n会分泌毒液。",
  ["_NidoranMDexEntry"] = "大耳朵总是高高竖起。\n一旦察觉危险，\f就会用带毒的尖刺\n发动攻击。",
  ["_NidorinaDexEntry"] = "在洞穴深处休息时，\n尖刺总会收起。\f这正说明它已经\n放松下来。",
  ["_NidorinoDexEntry"] = "它的角里有毒。\n刺入敌人身体时，\f冲击会让毒液\n从角中渗出。",
  ["_NinetalesDexEntry"] = "古老传说称，\n9位高贵的圣者\f合为一体，\n转生为这种宝可梦。",
  ["_NoCyclingAllowedHereText"] = "这里禁止骑自行车。",
  ["_NoEffectText"] = "没有效果！",
  ["_NoMonText"] = "什么？这里\n没有宝可梦！",
  ["_NoMoreRoomForItemText"] = "没有空间\n放更多道具！",
  ["_NoMovesLeftText"] = "{RAM:wBattleMonNick}\n没有招式可用了！",
  ["_NoNibbleText"] = "完全没有动静！",
  ["_NoPokemonText"] = "这里没有\n宝可梦！",
  ["_NoRoomToStoreText"] = "没有空间\n存放道具了。",
  ["_NoRunningText"] = "不行！\n训练家对战时\v不能逃跑！",
  ["_NoSurfingHereText"] = "这里不能让\n{RAM:wNameBuffer}使出冲浪！",
  ["_NoTrade1Text"] = "唉！\n那就算了……",
  ["_NoTrade2Text"] = "好吧，既然你\n不愿意……",
  ["_NoTrade3Text"] = "真可惜。",
  ["_NoWillText"] = "已经无心\n再战了！",
  ["_NotEnoughCoinsSlotMachineText"] = "代币\n不够！",
  ["_NotEnoughMemoryText"] = "《宝可梦 黄》的\n存储空间不足。",
  ["_NotHealthyEnoughText"] = "体力\n不足。",
  ["_NotThisTimeText"] = "这次不行！",
  ["_NotVeryEffectiveText"] = "效果不理想……",
  ["_NothingHappenedText"] = "什么也没发生！",
  ["_NothingHereText"] = "这里好像\n什么都没有。",
  ["_NothingStoredText"] = "没有存放\n任何东西。",
  ["_NothingToCutText"] = "没有可以用居合斩\n砍断的东西！",
  ["_NothingToDepositText"] = "你没有东西\n可以存放。",
  ["_NurseChanseyText"] = "吉利蛋：吉利——\n蛋！",
  ["_OHKOText"] = "一击必杀！",
  ["_OKExclamationText"] = "好！",
  ["_OakLabEmailText"] = "这里有一封\n电子邮件！\f……\f致所有\n宝可梦训练家！\f宝可梦联盟的\n顶尖训练家\v已准备好接受\v任何挑战！\f带上你最强的\n宝可梦，看看\v自己是怎样的\v训练家吧！\f宝可梦联盟总部\n石英高原\f附言：大木博士，\n请来拜访我们！\v……",
  ["_OakSpeechText1"] = "你好！\n欢迎来到\v宝可梦的世界！\f我叫大木！\n大家都称我为\v宝可梦博士！",
  ["_OakSpeechText2A"] = "这个世界中\n生活着\v被称为\v宝可梦的生物！",
  ["_OakSpeechText2B"] = "\f对有些人来说，\n宝可梦是\v宠物；有些人\v让它们对战。\f而我……\f我的职业是研究\n宝可梦。",
  ["_OakSpeechText3"] = "{PLAYER}！\f属于你自己的\n宝可梦传说\v即将拉开帷幕！\f梦想与冒险的\n宝可梦世界\v正等待着你！\v出发吧！",
  ["_OaksAideComeBackText"] = "哦，我明白了。\f等你收服了{NUM:hOaksAideRequirement, 1, 3}种\n宝可梦，再来领取\v{RAM:wOaksAideRewardItemName}。",
  ["_OaksAideGotItemText"] = "{PLAYER}获得了\n{RAM:wOaksAideRewardItemName}！",
  ["_OaksAideHereYouGoText"] = "太棒了！你已经\n收服了{NUM:hOaksAideNumMonsOwned, 1, 3}种宝可梦！\v恭喜你！\f拿去吧！",
  ["_OaksAideHiText"] = "嗨！还记得我吗？\n我是大木博士的助手！\f如果你收服了{NUM:hOaksAideRequirement, 1, 3}种\n宝可梦，博士就让我\v送你一个\v{RAM:wOaksAideRewardItemName}！\f所以，{PLAYER}！\n你至少收服了\v{NUM:hOaksAideRequirement, 1, 3}种宝可梦吗？",
  ["_OaksAideNoRoomText"] = "哦！看来你\n没有多余空间\v存放{RAM:wOaksAideRewardItemName}。",
  ["_OaksAideUhOhText"] = "我看看……\n糟糕！你只收服了\v{NUM:hOaksAideNumMonsOwned, 1, 3}种宝可梦！\f你需要收服{NUM:hOaksAideRequirement, 1, 3}种\n宝可梦，才能得到\v{RAM:wOaksAideRewardItemName}。",
  ["_OaksLabGirlText"] = "大木博士是\n宝可梦研究领域的\v权威！\f许多宝可梦训练家\n都非常敬重他！",
  ["_OaksLabGivePokeballsExplanationText"] = "\f遇到野生宝可梦时，\n谁都可以收服它。\f就像我示范的那样，\n扔出精灵球，\v试着收服它！\f但不一定每次成功。\f健康的宝可梦\v可能会挣脱。\v还得靠一点运气！",
  ["_OaksLabOak1ComeSeeMeSometimesText"] = "大木博士：有空就来看看。\f我想知道你的\n宝可梦图鉴\v完成得怎么样了。",
  ["_OaksLabOak1DeliverParcelText"] = "大木博士：哦，{PLAYER}！\f我托付给你的宝可梦\n怎么样了？\f看来它很喜欢你。\f你一定很有\n训练家的天分！\f什么？有东西给我？\f{PLAYER}交出了\n大木博士的包裹。",
  ["_OaksLabOak1GoAheadItsYours"] = "大木博士：去吧，\n它归你了！",
  ["_OaksLabOak1HowIsYourPokedexComingText"] = "大木博士：你来了！\n图鉴完成得怎么样？\v让我看看！",
  ["_OaksLabOak1ParcelThanksText"] = "\f啊！这是我订制的\n精灵球！\v谢谢你，{PLAYER}！\f对了，我有件事\n想拜托你。",
  ["_OaksLabOak1PokemonAroundTheWorldText"] = "世界各地的宝可梦\n都在等着你，{PLAYER}！",
  ["_OaksLabOak1ReceivedPokeballsText"] = "大木博士：只看见宝可梦，\n是得不到详细资料的。\f你必须收服它们！\n用这些精灵球\v去收服野生宝可梦吧。\f{PLAYER}获得了\n5个精灵球！",
  ["_OaksLabOak1YouShouldTalkToIt"] = "大木博士：和它说说话，\n看看它心情如何吧。",
  ["_OaksLabOak1YourPokemonCanFightText"] = "大木博士：遇到野生宝可梦，\n你的宝可梦就能\v和它对战！\f之后继续前往\n下一个城镇吧。",
  ["_OaksLabOak2Text"] = "？",
  ["_OaksLabOakBePatientText"] = "大木博士：别急，{RIVAL}。\n之后也会给你一只。",
  ["_OaksLabOakChooseMonText"] = "大木博士：嗯？{RIVAL}？\n你怎么已经来了？\f我不是叫你晚点来吗……\f算了！\n先在那里等着。\f看，{PLAYER}！\n看到桌上的球了吗？\f那叫精灵球，\n里面装着一只宝可梦。\f你可以拿走它！\n去吧，拿起来！",
  ["_OaksLabOakDontGoAwayYetText"] = "大木博士：喂！\n先别走！",
  ["_OaksLabOakGivesText"] = "大木博士：{PLAYER}，\n这是我刚才收服的\v宝可梦。\f你可以带走它。\n它刚从野外被收服，\v还不太亲近人。",
  ["_OaksLabOakGotPokedexText"] = "大木博士：{PLAYER}、{RIVAL}！\n把这个带上！\f{PLAYER}从大木博士那里\n获得了宝可梦图鉴！",
  ["_OaksLabOakIHaveARequestText"] = "大木博士：啊，{RIVAL}，\n来得正好！\f我有件事\n要拜托你们两个。",
  ["_OaksLabOakMyInventionPokedexText"] = "桌上放着我的发明——\n宝可梦图鉴！\f它会自动记录\n你见过或收服的\v宝可梦资料！\f这是一本高科技百科全书！",
  ["_OaksLabOakThatWasMyDreamText"] = "制作一本记录\n全世界所有宝可梦的\v完整图鉴……\f那曾是我的梦想！\f但我已经老了，\n没法亲自完成！\f所以，我希望你们两个\n替我实现梦想！\f快出发吧！\f这将是宝可梦历史上的\n伟大事业！",
  ["_OaksLabPikachuDislikesPokeballsText1"] = "大木博士：什么？",
  ["_OaksLabPikachuDislikesPokeballsText2"] = "大木博士：快看！\f真奇怪，看来你的\n皮卡丘不喜欢精灵球。\f就让它跟在你身边吧。\f这样它应该会很开心！\f你可以和它说话，\n看看它有多喜欢你。",
  ["_OaksLabPokedexText"] = "看起来像百科全书，\n但里面一片空白！",
  ["_OaksLabReceivedText"] = "{PLAYER}获得了\n{RAM:wNameBuffer}！",
  ["_OaksLabRivalAmIGreatOrWhatText"] = "{RIVAL}：怎么样！\n我很厉害吧？",
  ["_OaksLabRivalFedUpWithWaitingText"] = "{RIVAL}：爷爷！\n我都等烦了！",
  ["_OaksLabRivalGrampsIsntAroundText"] = "{RIVAL}：哟，{PLAYER}！\n爷爷不在！\f他说要给我一只宝可梦，\n所以我就跑来了。",
  ["_OaksLabRivalGrampsText"] = "{RIVAL}：爷爷！",
  ["_OaksLabRivalIPickedTheWrongPokemonText"] = "什么？\n不可能！\v我选错宝可梦了！",
  ["_OaksLabRivalIllGetABetterPokemonThanYou"] = "{RIVAL}：哼！\n我会抓到比你的\v更好的宝可梦！",
  ["_OaksLabRivalIllTakeYouOnText"] = "{RIVAL}：等等，{PLAYER}！\n来看看我们的宝可梦吧！\f来吧，和我对战！",
  ["_OaksLabRivalLeaveItAllToMeText"] = "{RIVAL}：好，爷爷！\n全都交给我吧！\f{PLAYER}，虽说不好意思，\n但我不需要你帮忙！\f对了！我要向姐姐\n借一张城镇地图！\f我会叫她别借给你的，\n{PLAYER}！哈哈哈！",
  ["_OaksLabRivalMyPokemonHasGrownStrongerText"] = "{RIVAL}：爷爷，\n我的宝可梦变强了！\v快看看！",
  ["_OaksLabRivalMyPokemonLooksStrongerText"] = "{RIVAL}：嘿嘿，\n我的宝可梦看起来\v强多了。",
  ["_OaksLabRivalSmellYouLaterText"] = "{RIVAL}：好！\n我要让宝可梦不断对战，\v变得更强！\f{PLAYER}！爷爷！\n回头见！",
  ["_OaksLabRivalTakesText1"] = "{RIVAL}：不行！\n{PLAYER}，我想要\v这只宝可梦！",
  ["_OaksLabRivalTakesText2"] = "{RIVAL}抢走了\n那只宝可梦！",
  ["_OaksLabRivalTakesText3"] = "大木博士：{RIVAL}！\n你在干什么？",
  ["_OaksLabRivalTakesText4"] = "{RIVAL}：爷爷，\n我就要这只！",
  ["_OaksLabRivalTakesText5"] = "大木博士：可是，我……\n好吧。\v那只宝可梦归你了。\f反正我本来也打算\n给你一只……\f{PLAYER}，到这边来。",
  ["_OaksLabRivalWhatAboutMeText"] = "{RIVAL}：喂！\n爷爷！\v那我呢？",
  ["_OaksLabScientistText"] = "我是大木博士的助手，\n负责研究宝可梦。",
  ["_OaksLabThatsAPokeball"] = "那是精灵球。\n里面装着宝可梦！",
  ["_OddishDexEntry"] = "有时会被误认成\n一丛杂草。\f要是想把它从地里拔出，\n它会发出可怕的尖叫。",
  ["_OfficerJennyText1"] = "我刚捉到一只\n总爱恶作剧的\v杰尼龟。\f我想它需要一位\n好训练家来\v引导它。",
  ["_OfficerJennyText2"] = "你有橙色徽章！？\f你一定是位\n优秀的训练家！\f我刚捉到一只\n总爱恶作剧的\v杰尼龟。\f你愿意好好\n照顾它吗？",
  ["_OfficerJennyText3"] = "好！请善待\n杰尼龟！",
  ["_OfficerJennyText4"] = "哦……现在\n该怎么办呢？",
  ["_OfficerJennyText5"] = "杰尼龟\n过得好吗？",
  ["_OhFineThenText"] = "哦，那好吧。",
  ["_OlderFileWillBeErasedText"] = "旧存档将被覆盖。\n确定要保存吗？",
  ["_OmanyteDexEntry"] = "从化石中复原的\n古代宝可梦。\f它会灵活转动10条触手\n在水中游动。",
  ["_OmastarDexEntry"] = "嘴边环绕着锋利的喙。\n它的壳太大，\f无法自由行动，\n因此灭绝了。",
  ["_OnceReleasedText"] = "一旦放生，\n{RAM:wStringBuffer}就\v永远回不来了。确定吗？",
  ["_OneMoreGoSlotMachineText"] = "再玩一次？",
  ["_OneTwoAndText"] = "1、2，然后……",
  ["_OnixDexEntry"] = "为了寻找食物，\n会高速钻入地下。\f留下的隧道\n会成为地鼠的住所。",
  ["_OopsYouDontHaveEnoughRoomText"] = "哎呀！你的空间\n不够了。",
  ["_OutOfCoinsSlotMachineText"] = "糟糕！\n代币用完了！",
  ["_OutOfSafariBallsText"] = "广播：叮咚！\f你的狩猎球\n用完了！",
  ["_PPIncreasedText"] = "{RAM:wStringBuffer}的PP\n提高了。",
  ["_PPMaxedOutText"] = "{RAM:wStringBuffer}的PP\n已经达到最大值。",
  ["_PPRestoredText"] = "PP恢复了。",
  ["_PalletTownFisherText"] = "科技真了不起！\f如今可以通过电脑\n以数据形式\v存取道具和宝可梦！",
  ["_PalletTownGirlText"] = "我也在培育宝可梦！\f等它们变强后，\n就能保护我了！",
  ["_PalletTownOakComeWithMe"] = "大木博士：草丛里随时可能\n出现宝可梦。\f你需要自己的宝可梦\n来保护自己。\v有了！\f跟我来！",
  ["_PalletTownOakHeyWaitDontGoOutText"] = "大木博士：喂！等等！\n别出去！",
  ["_PalletTownOakThatWasCloseText"] = "大木博士：好险！\f草丛里生活着\n野生宝可梦！",
  ["_PalletTownOakWhewText"] = "大木博士：呼……",
  ["_PalletTownOaksLabSignText"] = "大木博士的\n宝可梦研究所",
  ["_PalletTownPlayersHouseSignText"] = "{PLAYER}的家",
  ["_PalletTownRivalsHouseSignText"] = "{RIVAL}的家",
  ["_PalletTownSignText"] = "真新镇\n纯白色的起点",
  ["_ParalyzedMayNotAttackText"] = "{TARGET}\n陷入了麻痹状态，\v可能无法行动！",
  ["_ParasDexEntry"] = "钻入地下啃食树根。\n背上的蘑菇\f会吸走它获得的\n大部分养分。",
  ["_ParasectDexEntry"] = "虫子宿主的能量\n被背上的蘑菇吸走。\f看起来所有思考\n都由蘑菇完成。",
  ["_ParlyzHealText"] = "{RAM:wNameBuffer}的\n麻痹状态解除了！",
  ["_PartyMenuBattleText"] = "要派哪只\n宝可梦出场？",
  ["_PartyMenuItemUseText"] = "要对哪只宝可梦\n使用道具？",
  ["_PartyMenuNormalText"] = "请选择一只宝可梦。",
  ["_PartyMenuSwapMonText"] = "要把宝可梦\n移到哪里？",
  ["_PartyMenuUseTMText"] = "要教给哪只\n宝可梦？",
  ["_PersianDexEntry"] = "额头上的宝石\n会自行发光！\f走路时流露出\n高傲女王般的优雅气质。",
  ["_PewterCityCooltrainerFText"] = "听说皮皮是从\n月亮上来的！\f月之石坠落到\n月见山后，它们\v就出现了。",
  ["_PewterCityCooltrainerMText"] = "这里没几个认真的\n宝可梦训练家！\f大家都像捕虫少年，\n不过深灰道馆的小刚\v可是认真得很！",
  ["_PewterCityGymSignText"] = "深灰市\n宝可梦道馆\v馆主：小刚\f坚如磐石的\n宝可梦训练家！",
  ["_PewterCityMuseumSignText"] = "深灰科学博物馆",
  ["_PewterCityPokecenterGuyText"] = "哈欠——！\f胖丁一唱歌，\n宝可梦就会\v昏昏欲睡……\f……我也一样……\n呼噜……",
  ["_PewterCityPoliceNoticeSignText"] = "告示！\f有盗贼在月见山\n偷走了宝可梦化石！\v如有线索，\n请通知深灰市警方！",
  ["_PewterCitySignText"] = "深灰市\n坚若磐石的\v灰黑之城",
  ["_PewterCitySuperNerd1DidYouCheckOutMuseumText"] = "你去过博物馆了吗？",
  ["_PewterCitySuperNerd1ItsRightHereText"] = "就在这儿！\n虽然要买票，\v但很值得！\v回头见！",
  ["_PewterCitySuperNerd1WerentThoseFossilsAmazingText"] = "月见山的那些\n化石是不是很棒？",
  ["_PewterCitySuperNerd1YouHaveToGoText"] = "真的？\n你一定得去看看！",
  ["_PewterCitySuperNerd2DoYouKnowWhatImDoingText"] = "嘘！\n你知道我在\v做什么吗？",
  ["_PewterCitySuperNerd2ImSprayingRepelText"] = "我在喷除虫喷雾，\n让宝可梦远离我的花园！",
  ["_PewterCitySuperNerd2ThatsRightText"] = "没错！\n这可是个辛苦活！",
  ["_PewterCityTrainerTipsText"] = "训练家提示\f只要参加过对战，\n无论时间多短，\v宝可梦都能获得经验值！",
  ["_PewterCityYoungsterGoTakeOnBrockText"] = "如果你有真本事，\n就去挑战小刚吧！",
  ["_PewterCityYoungsterYoureATrainerFollowMeText"] = "你是训练家吧？\n小刚正等着\v新的挑战者！\v跟我来！",
  ["_PewterGymBrockBoulderBadgeInfoText"] = "\f这是宝可梦联盟\n正式认可的徽章！\f持有者的宝可梦\n会变得更强！\f现在你随时都能\n使用闪光了！",
  ["_PewterGymBrockPostBattleAdviceText"] = "世界上有各种各样的\n训练家！\f有人为对战培育宝可梦，\n有人把它们当宠物。\f我正在修行，\n想成为宝可梦培育家。\f如果你认真训练\n自己的宝可梦，\v就去华蓝市的道馆\v测试实力吧！",
  ["_PewterGymBrockPreBattleText"] = "我是小刚！\n深灰道馆的馆主！\f我信奉坚如磐石的\n防御和意志！\f所以我的宝可梦\n全都是岩石属性！\f你还是要挑战我吗？\n那好！\v拿出你的全部实力吧！",
  ["_PewterGymBrockReceivedBoulderBadgeText"] = "是我小看你了。\f作为你获胜的证明，\n这枚灰色徽章给你！\f{PLAYER}获得了\n灰色徽章！",
  ["_PewterGymBrockWaitTakeThisText"] = "等等！\n把这个带上！",
  ["_PewterGymCooltrainerMAfterBattleText"] = "你确实很强，\n但还比不上小刚！",
  ["_PewterGymCooltrainerMBattleText"] = "站住，小子！\f你离挑战小刚\n还差好几光年呢！",
  ["_PewterGymCooltrainerMEndBattleText"] = "可恶！\f光年不是时间单位！\n而是距离单位！",
  ["_PewterGymGuideAdviceText"] = "对战时第一个出场的\n就是宝可梦列表里\v排在最上面的那只！\f调整宝可梦的顺序，\n也许能让对战更轻松！",
  ["_PewterGymGuideBeginAdviceText"] = "好！\n那就开始吧！",
  ["_PewterGymGuideFreeServiceText"] = "这是免费服务！\n那就开始吧！",
  ["_PewterGymGuidePostBattleText"] = "果然不出我所料！\n你有成为宝可梦冠军的潜质！",
  ["_PewterGymGuidePreAdviceText"] = "嗨！我看得出来，\n你有成为宝可梦冠军的\v潜质！\f我虽然不是训练家，\n却能教你获胜的诀窍！\f让我带你登上巅峰吧！",
  ["_PewterGymGuyText"] = "好！\n那就开始吧！\f你的皮卡丘在这座道馆\n会打得很辛苦！\f电属性招式对小刚的\n地面属性宝可梦无效。",
  ["_PewterGymReceivedTM34Text"] = "{PLAYER}获得了\n招式学习器34！",
  ["_PewterGymTM34NoRoomText"] = "背包里已经\n装不下这个了！",
  ["_PewterMartSuperNerdText"] = "即使是弱小的宝可梦，\n只要用心培育，\v也会有好事发生！",
  ["_PewterMartYoungsterText"] = "有个可疑的老头\n让我买下这只\v奇怪的鱼宝可梦！\f它弱得要命，\n还花了我¥500！",
  ["_PewterNidoranHouseLittleBoyText"] = "尼多朗，坐下！",
  ["_PewterNidoranHouseMiddleAgedManText"] = "我们的宝可梦是\n从别人那里来的，\v所以很难管教。\f所谓外来的宝可梦，\n就是通过交换\v得到的宝可梦。\f它成长得很快，\n但在对战时，\v可能不听\v实力不足的训练家！\f要是我们也有\n几枚徽章就好了……",
  ["_PewterNidoranHouseNidoranText"] = "尼多朗：汪汪！",
  ["_PewterPokecenterGentlemanText"] = "什么！？\f火箭队在月见山？\n啊？\v我在打电话呢！\f快走开！",
  ["_PewterPokecenterJigglypuffText"] = "胖丁：噗——\n噗噗！",
  ["_PewterPokecenterText3"] = "宝可梦中心真棒！\f不但能让宝可梦\n完全恢复健康，\f连睡眠、灼伤、\n中毒等异常状态\v也能治好。",
  ["_PewterSpeechHouseGamblerText"] = "宝可梦成长时会\n学会新的招式！\f不过有些招式\n必须由训练家\v教给它们！",
  ["_PewterSpeechHouseYoungsterText"] = "宝可梦受伤或睡着时，\n会更容易收服！\f但也不一定\n每次都能成功！",
  ["_PickUpPayDayMoneyText"] = "{PLAYER}捡到了\n¥{NUM:wTotalPayDayMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}！",
  ["_PidgeotDexEntry"] = "这种宝可梦会以\n2马赫的速度飞行，\n寻找猎物。\f它巨大的利爪\n被视为凶恶的武器。",
  ["_PidgeottoDexEntry"] = "这种宝可梦活力十足。\n会不停地\f飞遍广阔领地，\n寻找猎物。",
  ["_PidgeyDexEntry"] = "性情非常温顺。\n遭到攻击时，\f常会扬起沙尘保护自己，\n而不是还击。",
  ["_PikachuDexEntry"] = "会竖起尾巴\n观察周围动静。\f如果拉它的尾巴，\n它就会试着咬你。",
  ["_PikachuUnhappyText"] = "{RAM:wNameBuffer}看起来\n很不高兴！",
  ["_PinsirDexEntry"] = "用钳子夹住猎物，\n再狠狠挤压！\f天冷时它无法活动，\n所以生活在温暖地区。",
  ["_PlaySlotMachineText"] = "是老虎机！\n要玩吗？",
  ["_PlayedFluteHadEffectText"] = "{PLAYER}吹奏了\n宝可梦之笛。",
  ["_PlayedFluteNoEffectText"] = "吹响了\n宝可梦之笛。\f真是一段\n动听的旋律！",
  ["_PlayerBlackedOutText"] = "{PLAYER}已没有\n能战斗的宝可梦！\f{PLAYER}眼前\n一黑！",
  ["_PlayerBlackedOutText2"] = "{PLAYER}已没有\n能战斗的宝可梦！\f{PLAYER}眼前\n一黑！",
  ["_PlayerMon1Text"] = "{RAM:wBattleMonNick}！",
  ["_PlayerMon2Text"] = "{RAM:wBattleMonNick} ",
  ["_PlayerMonFaintedText"] = "{RAM:wBattleMonNick}\n倒下了！",
  ["_PoisonedText"] = "{TARGET}\n中毒了！",
  ["_PokeCenterSignText"] = "治愈你的宝可梦！\n宝可梦中心",
  ["_PokemartAnythingElseText"] = "还需要别的吗？",
  ["_PokemartBoughtItemText"] = "给你！\n谢谢惠顾！",
  ["_PokemartBuyingGreetingText"] = "请慢慢挑选。",
  ["_PokemartGreetingText"] = "欢迎光临！\n需要帮忙吗？",
  ["_PokemartItemBagEmptyText"] = "你没有可以卖的\n东西。",
  ["_PokemartItemBagFullText"] = "你不能再携带\n更多道具了。",
  ["_PokemartNotEnoughMoneyText"] = "你的钱不够。",
  ["_PokemartTellBuyPriceText"] = "{RAM:wStringBuffer}？\n价格是\v¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}。确定吗？",
  ["_PokemartTellSellPriceText"] = "我可以出价\n¥{NUM:hMoney, 3 | LEADING_ZEROES | LEFT_ALIGN}。",
  ["_PokemartThankYouText"] = "谢谢惠顾！",
  ["_PokemartUnsellableItemText"] = "这个我不能收购。",
  ["_PokemonBooksText"] = "塞满了\n宝可梦书籍！",
  ["_PokemonCenterFarewellText"] = "期待您\n再次光临！",
  ["_PokemonCenterWelcomeText"] = "欢迎来到\n宝可梦中心！\f我们会让你的\n宝可梦恢复到\v最佳状态！",
  ["_PokemonFaintedText"] = "{RAM:wNameBuffer}\n倒下了！",
  ["_PokemonFanClubBagFullText"] = "先腾出一个\n位置吧！",
  ["_PokemonFanClubChairFinalText"] = "你好，{PLAYER}！\f你又来听我\n说宝可梦了吗？\f不是？真遗憾！",
  ["_PokemonFanClubChairmanIntroText"] = "我是宝可梦\n发烧友俱乐部会长！\f我有100多只\n宝可梦，\v每一只都很爱！\f说到宝可梦，\n我可是很讲究的！\f所以……\f你是来听我\n夸宝可梦的吗？",
  ["_PokemonFanClubChairmanStoryText"] = "好！\n那就听好！\f我最喜欢的\n烈焰马……\f它……可爱……\n漂亮……聪明……\v还有……惊人……\v你也这么觉得？……\v没错……它……\v耀眼……温柔……\v我太喜欢了！\f睡觉时……抱住它……\n暖暖的……\v软绵绵……\v太棒了……\v迷人极了……\v……哎呀！已经\n这个时间了！\v耽误你太久了！\f谢谢你听我说！\n这个送给你！",
  ["_PokemonFanClubClefairyFanBetterText"] = "哼！我的皮皮\n比那只可爱\v一倍！",
  ["_PokemonFanClubClefairyFanNormalText"] = "不来欣赏一下\n我家皮皮\v可爱的尾巴吗？",
  ["_PokemonFanClubClefairyFanText"] = "我们会长的新爱好\n是给宝可梦拍照。\f他送了我一张\n可爱皮皮的照片。",
  ["_PokemonFanClubClefairyText"] = "皮皮：皮皮——！",
  ["_PokemonFanClubExplainBikeVoucherText"] = "\f用它可以兑换\n一辆自行车！\f别担心，我的大嘴雀\n会用飞翔\v带我去任何地方！\f所以我不需要\n自行车！\f希望你喜欢骑车！",
  ["_PokemonFanClubNoStoryText"] = "哦。想听我的故事时\n再来吧！",
  ["_PokemonFanClubReceivedBikeVoucherText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_PokemonFanClubReceptionistText"] = "我们会长\n一说起宝可梦\v就停不下来。",
  ["_PokemonFanClubSeelFanBetterText"] = "哎呀！\f我的小海狮\n可迷人多了！",
  ["_PokemonFanClubSeelFanNormalText"] = "我最喜欢我的\n小海狮！\f我一抱它，\n它就会叫！",
  ["_PokemonFanClubSeelFanText"] = "我要接上连接线，\n把我家小海狮的\v照片打印出来！",
  ["_PokemonFanClubSeelText"] = "小海狮：啾呜！",
  ["_PokemonFightingFitText"] = "谢谢！\n你的宝可梦\v都恢复精神了！",
  ["_PokemonMansion1FScientistAfterBattleText"] = "钥匙？我不知道\n你在说什么。",
  ["_PokemonMansion1FScientistBattleText"] = "你是谁？这里\n不该有人。",
  ["_PokemonMansion1FScientistEndBattleText"] = "好痛！",
  ["_PokemonMansion1FSwitchNotPressedText"] = "还是算了！",
  ["_PokemonMansion1FSwitchPressedText"] = "当然要按！",
  ["_PokemonMansion1FSwitchText"] = "是秘密开关！\f要按下去吗？",
  ["_PokemonMansion2FDiary1Text"] = "日记：7月5日\n南美洲，圭亚那\f在丛林深处\n发现了一种\v新宝可梦。",
  ["_PokemonMansion2FDiary2Text"] = "日记：7月10日\n我们把新发现的\v宝可梦命名为\v梦幻。",
  ["_PokemonMansion2FSuperNerdAfterBattleText"] = "开关会让不同的门\n交替开启和关闭！",
  ["_PokemonMansion2FSuperNerdBattleText"] = "我出不去了！\n这栋老宅简直是\v一座大迷宫！",
  ["_PokemonMansion2FSuperNerdEndBattleText"] = "糟了！\n我的战利品！",
  ["_PokemonMansion2FSwitchNotPressedText"] = "还是算了！",
  ["_PokemonMansion2FSwitchPressedText"] = "当然要按！",
  ["_PokemonMansion2FSwitchText"] = "是秘密开关！\f要按下去吗？",
  ["_PokemonMansion3FDiaryText"] = "日记：2月6日\n梦幻产下了宝宝。\f我们给这个\n新生儿取名为超梦。",
  ["_PokemonMansion3FScientistAfterBattleText"] = "你也被困住了？\n试试从那边跳下去！",
  ["_PokemonMansion3FScientistBattleText"] = "我的导师曾经\n住在这里。",
  ["_PokemonMansion3FScientistEndBattleText"] = "呼！\n太强了！",
  ["_PokemonMansion3FSuperNerdAfterBattleText"] = "我的同伴\n去哪儿了呢？",
  ["_PokemonMansion3FSuperNerdBattleText"] = "这里也\n太大了吧！",
  ["_PokemonMansion3FSuperNerdEndBattleText"] = "哎呀！",
  ["_PokemonMansionB1FBurglarAfterBattleText"] = "地上随处都能\n找到东西。",
  ["_PokemonMansionB1FBurglarBattleText"] = "糟糕，我现在\n在哪儿？",
  ["_PokemonMansionB1FBurglarEndBattleText"] = "嗷呜！",
  ["_PokemonMansionB1FDiaryText"] = "日记：9月1日\n超梦实在太过\v强大。\f我们没能抑制\n它凶暴的本性……",
  ["_PokemonMansionB1FScientistAfterBattleText"] = "我喜欢这里！\n这里很适合\v进行研究！",
  ["_PokemonMansionB1FScientistBattleText"] = "这里很适合\n建实验室。",
  ["_PokemonMansionB1FScientistEndBattleText"] = "为什么\n要打我？",
  ["_PokemonSellingGreetingText"] = "你想卖掉\n什么？",
  ["_PokemonStuffText"] = "哇！好多\n宝可梦周边！",
  ["_PokemonText"] = "宝可梦！",
  ["_PokemonTower1FBaldingGuyText"] = "我来为我的皮皮\n祈祷。\f呜……眼泪\n怎么也止不住……",
  ["_PokemonTower1FChannelerText"] = "我是祈祷师！\n有幽灵在\v到处作祟！",
  ["_PokemonTower1FGirlText"] = "我的卡蒂狗……\n你为什么死了？",
  ["_PokemonTower1FMiddleAgedWomanText"] = "你是来祭拜的吗？\n愿你得到保佑！",
  ["_PokemonTower1FReceptionistText"] = "宝可梦塔是为\n纪念逝去的宝可梦\v而建。",
  ["_PokemonTower2FChannelerText"] = "连我们也看不出\n那些游荡幽灵的\v真面目！\f西尔佛检视镜\n也许能让它们\v现形。",
  ["_PokemonTower2FRivalDefeatedText"] = "什么？\n你这臭小子！\f我还手下留情了！",
  ["_PokemonTower2FRivalHowsYourDexText"] = "你的图鉴进展\n怎么样了，老兄？\v我刚捉到一只\v卡拉卡拉！\f可我还没找到\n成年的嘎啦嘎啦！\f我看它们已经绝种了！\n好了，我得走了！\v还有很多事\v等着我去完成呢！\f回头见！",
  ["_PokemonTower2FRivalVictoryText"] = "{RIVAL}：哟，\n看看你这些\v弱不禁风的宝可梦！\f再多锻炼一下吧！",
  ["_PokemonTower2FRivalWhatBringsYouHereText"] = "{RIVAL}：嘿，\n{PLAYER}！你来这里\v干什么？\v你的宝可梦\v看着又没死！\f至少我能\n把它们打倒！\v来吧，老兄！",
  ["_PokemonTower3FChanneler1AfterBattleText"] = "用西尔佛检视镜\n就能看出幽灵的\v真面目。",
  ["_PokemonTower3FChanneler1BattleText"] = "呃啊……啊哇……\n呼呼……嘎啊……",
  ["_PokemonTower3FChanneler1EndBattleText"] = "哇！\n我得救了！",
  ["_PokemonTower3FChanneler2AfterBattleText"] = "对不起！\n我刚才被附身了！",
  ["_PokemonTower3FChanneler2BattleText"] = "嘻嘻嘻……\n呜啊！",
  ["_PokemonTower3FChanneler2EndBattleText"] = "嗯？\n我在做什么？",
  ["_PokemonTower3FChanneler3AfterBattleText"] = "我的朋友们\n也被附身了！",
  ["_PokemonTower3FChanneler3BattleText"] = "退散！\n恶灵！",
  ["_PokemonTower3FChanneler3EndBattleText"] = "呼！\n恶灵离开了！",
  ["_PokemonTower4FChanneler1AfterBattleText"] = "我一定是在\n做梦……",
  ["_PokemonTower4FChanneler1BattleText"] = "幽灵！不要！\n呜啊！",
  ["_PokemonTower4FChanneler1EndBattleText"] = "幽灵\n在哪里？",
  ["_PokemonTower4FChanneler2AfterBattleText"] = "我们无法识破\n幽灵的真面目。",
  ["_PokemonTower4FChanneler2BattleText"] = "和我一起\n受诅咒吧！呜啊！",
  ["_PokemonTower4FChanneler2EndBattleText"] = "什么！",
  ["_PokemonTower4FChanneler3AfterBattleText"] = "愿逝去的\n宝可梦灵魂\v得以安息……",
  ["_PokemonTower4FChanneler3BattleText"] = "呼呼呼……\n别打败我！",
  ["_PokemonTower4FChanneler3EndBattleText"] = "咦？\n谁？什么？",
  ["_PokemonTower5FChanneler1Text"] = "过来，孩子！\n我用白魔法\v封住了这片区域！\f你可以在这里休息！",
  ["_PokemonTower5FChanneler2AfterBattleText"] = "我刚才\n被附身了！",
  ["_PokemonTower5FChanneler2BattleText"] = "把……你的……\n灵魂……给我……",
  ["_PokemonTower5FChanneler2EndBattleText"] = "啊！",
  ["_PokemonTower5FChanneler3AfterBattleText"] = "我被附身了！",
  ["_PokemonTower5FChanneler3BattleText"] = "你……也会……\n加入……我们……",
  ["_PokemonTower5FChanneler3EndBattleText"] = "真是一场\n噩梦！",
  ["_PokemonTower5FChanneler4AfterBattleText"] = "我恢复\n神智了！",
  ["_PokemonTower5FChanneler4BattleText"] = "僵尸！",
  ["_PokemonTower5FChanneler4EndBattleText"] = "哈？",
  ["_PokemonTower5FChanneler5AfterBattleText"] = "尽管受过修行，\n我还是败给了\v恶灵！",
  ["_PokemonTower5FChanneler5BattleText"] = "呃啊……\n呜呃……",
  ["_PokemonTower5FChanneler5EndBattleText"] = "呜！",
  ["_PokemonTower5FPurifiedZoneText"] = "进入了净化过的\n安全区域！\f{PLAYER}的宝可梦\n全部恢复了！",
  ["_PokemonTower6FBeGoneText"] = "滚出去……\n入侵者……",
  ["_PokemonTower6FChanneler1AfterBattleText"] = "我感觉贫血，\n浑身无力……",
  ["_PokemonTower6FChanneler1BattleText"] = "把……血……\n给我……",
  ["_PokemonTower6FChanneler1EndBattleText"] = "呃啊！",
  ["_PokemonTower6FChanneler2AfterBattleText"] = "掉出来的不是头发！\n是恶灵！",
  ["_PokemonTower6FChanneler2BattleText"] = "呜呃……呜啊！",
  ["_PokemonTower6FChanneler2EndBattleText"] = "有……\n东西掉出来了！",
  ["_PokemonTower6FChanneler3AfterBattleText"] = "这里发生了\n什么？",
  ["_PokemonTower6FChanneler3BattleText"] = "嘻……嘻……嘻……\n嘻……嘻……嘻！！",
  ["_PokemonTower6FChanneler3EndBattleText"] = "嘻——！",
  ["_PokemonTower6FGhostWasCubonesMotherText"] = "幽灵原来是\n卡拉卡拉母亲\v无法安息的灵魂！",
  ["_PokemonTower6FSoulWasCalmedText"] = "母亲的灵魂\n平静了下来。\f它前往了\n另一个世界！",
  ["_PokemonTower7FMrFujiRescueText"] = "富士老人：咦？你\n是来救我的吗？\f谢谢。不过，\n我是自愿来这里的。\f我是来安抚\n卡拉卡拉母亲的\v灵魂。\f看来嘎啦嘎啦的\n灵魂已经前往\v另一个世界。\f谢谢你这么\n关心我！\f跟我回家吧，\n就在这座塔脚下的\v宝可梦之家。",
  ["_PokemonTowerJessieJamesText1"] = "站住！",
  ["_PokemonTowerJessieJamesText2"] = "这位老爷爷想抱怨，\n我们正在教他\v懂点规矩。\f识相的话就消失，\n否则准备开战！",
  ["_PokemonTowerJessieJamesText3"] = "你会\n后悔的！",
  ["_PokemonTowerJessieJamesText4"] = "火箭队又一次\n被打飞了！",
  ["_PoliwagDexEntry"] = "腹部螺旋的方向\n会因地区而异。\f比起走路，\n它更擅长游泳。",
  ["_PoliwhirlDexEntry"] = "遭到攻击时，\n会用腹部的螺旋花纹\f催眠敌人，\n然后趁机逃走。",
  ["_PoliwrathDexEntry"] = "调动全身肌肉\n强劲地游泳。\f甚至能超过\n游泳冠军。",
  ["_PonytaDexEntry"] = "能跳得非常高。\n强健的双腿和蹄子\f能吸收落地时的\n猛烈冲击。",
  ["_PoofText"] = " 噗！",
  ["_PorygonDexEntry"] = "人们认为它是\n唯一有望飞向太空的\n宝可梦。\f不过至今还没有\n成功的记录。",
  ["_PotionText"] = "{RAM:wNameBuffer}\n恢复了{NUM:wHPBarHPDifference, 2, 3}点HP！",
  ["_PowerPlantVoltorbBattleText"] = "滋滋！",
  ["_PowerPlantZapdosBattleText"] = "嘎嗷！",
  ["_PrimeapeDexEntry"] = "只有周围空无一人时，\n它才会息怒。\f想看到这一刻\n非常困难。",
  ["_PsyduckDexEntry"] = "总是饱受头痛折磨。\n它会使用超能力，\f但没人知道\n它是否有意为之。",
  ["_PushStartText"] = "按下START键\n打开菜单！",
  ["_RaichuDexEntry"] = "体内积聚电力后，\n会变得暴躁。\f它还会在黑暗中\n发光。",
  ["_RaisePPWhichTechniqueText"] = "要提高哪个招式的\nPP？",
  ["_RanAwayScaredText"] = "{TARGET}\n吓得逃走了！",
  ["_RanFromBattleText"] = "{USER}\n逃离了战斗！",
  ["_RapidashDexEntry"] = "最喜欢奔跑。\n如果发现比自己\n更快的东西，\f就会以最高速度\n追赶对方。",
  ["_RareCandyText"] = "{RAM:wNameBuffer}升到了\n{NUM:wCurEnemyLevel, 1, 3}级！",
  ["_RaticateDexEntry"] = "后脚长有蹼，\n能像脚蹼一样\n发挥作用。\f因此能在河里游泳\n并捕捉猎物。",
  ["_RattataDexEntry"] = "会用门牙啃咬\n任何东西。\n只要看到1只，\f附近肯定还住着\n另外40只。",
  ["_RedBedroomSNESText"] = "{PLAYER}正在玩\n超级任天堂！\v……好！\v该出发了！",
  ["_RedsHouse1FMomLookingGreatText"] = "妈妈：太好了！\n你和宝可梦\v看起来都很精神！\v路上小心！",
  ["_RedsHouse1FMomWakeUpText"] = "妈妈：对了。\n男孩子总有一天\v要离开家。\v电视上也这么说。\f隔壁的大木博士\n正在找你。",
  ["_RedsHouse1FMomYouShouldRestText"] = "妈妈：{PLAYER}，\n要是让宝可梦太累，\v它们会不喜欢你的。\f你休息一下吧。",
  ["_RedsHouse1FTVStandByMeMovieText"] = "电视上正在播电影。\n四个男孩沿着铁轨走。\f我也该出发了。",
  ["_RedsHouse1FTVWrongSideText"] = "哎呀，看反了。",
  ["_ReflectGainedArmorText"] = "{USER}\n获得了防护！",
  ["_RefusingText"] = "{RAM:wNameBuffer}\n拒绝行动！",
  ["_RegainedHealthText"] = "{USER}\n恢复了体力！",
  ["_ReleaseWhichMonText"] = "要放生哪只\n宝可梦？",
  ["_RepelWoreOffText"] = "除虫喷雾的效果\n消失了。",
  ["_RequireCoinCaseText"] = "必须持有\n代币盒！",
  ["_RestorePPWhichTechniqueText"] = "要恢复哪个招式的\nPP？",
  ["_ReviveText"] = "{RAM:wNameBuffer}\n恢复了活力！",
  ["_RhydonDexEntry"] = "用后腿行走，\n显露出智慧的迹象。\f铠甲般的皮肤\n甚至能抵御熔岩。",
  ["_RhyhornDexEntry"] = "一根筋的宝可梦。\n一旦开始冲撞，\f就会一直奔跑，\n直到睡着为止。",
  ["_Rival1WinText"] = "{RIVAL}：怎么样！\n我是不是很厉害？",
  ["_RivalDefeatedText"] = "不！\n这不可能！\v你打败了我最强的队伍！\f我费尽力气\n才当上联盟冠军！\f我的冠军生涯\n就这么结束了？\v太不公平了！",
  ["_RivalVictoryText"] = "哈哈哈！\n我赢了，我赢了！\f我比你强太多了，\n{PLAYER}！\f你竟然能一路\n来到天才训练家\v{RIVAL}面前，\v已经很不错了！\f继续努力吧，手下败将！\n哈哈哈！",
  ["_RockTunnel1FCooltrainerF1AfterBattleText"] = "我在这隧道里\n见过腕力！",
  ["_RockTunnel1FCooltrainerF1BattleText"] = "呀！别想趁黑\n使坏！",
  ["_RockTunnel1FCooltrainerF1EndBattleText"] = "太黑了，\n看不清！",
  ["_RockTunnel1FCooltrainerF2AfterBattleText"] = "你看起来可爱又无害！",
  ["_RockTunnel1FCooltrainerF2BattleText"] = "我是为宝可梦\n才走到这里的！",
  ["_RockTunnel1FCooltrainerF2EndBattleText"] = "我的宝可梦\n全倒下了！",
  ["_RockTunnel1FCooltrainerF3AfterBattleText"] = "呼！我现在\n浑身是汗！",
  ["_RockTunnel1FCooltrainerF3BattleText"] = "你有宝可梦！\n开始吧！",
  ["_RockTunnel1FCooltrainerF3EndBattleText"] = "你打得\n真狠！",
  ["_RockTunnel1FHiker1AfterBattleText"] = "小心大岩蛇！\n它会把你\v紧紧勒住！",
  ["_RockTunnel1FHiker1BattleText"] = "这条隧道很长，\n小子！",
  ["_RockTunnel1FHiker1EndBattleText"] = "可恶！\n你赢了！",
  ["_RockTunnel1FHiker2AfterBattleText"] = "12号道路上\n那只睡着的宝可梦\v逼我绕了远路。",
  ["_RockTunnel1FHiker2BattleText"] = "嗯。我可能\n在这里迷路了……",
  ["_RockTunnel1FHiker2EndBattleText"] = "轻点！\n我在干什么？\v出口在哪边？",
  ["_RockTunnel1FHiker3AfterBattleText"] = "你很有徒步旅行的\n天分！",
  ["_RockTunnel1FHiker3BattleText"] = "你这种外来者\n得对我放尊重点！",
  ["_RockTunnel1FHiker3EndBattleText"] = "我认输！",
  ["_RockTunnel1FSignText"] = "岩山隧道\n华蓝市—紫苑镇",
  ["_RockTunnel1FSuperNerdAfterBattleText"] = "算了，我边走\n边捉只超音蝠吧！",
  ["_RockTunnel1FSuperNerdBattleText"] = "宝可梦对战！\n预备，开始！",
  ["_RockTunnel1FSuperNerdEndBattleText"] = "游戏\n结束！",
  ["_RockTunnelB1FCooltrainerF1AfterBattleText"] = "我想\n回家！",
  ["_RockTunnelB1FCooltrainerF1BattleText"] = "登山的人会留下树枝\n当作路标。",
  ["_RockTunnelB1FCooltrainerF1EndBattleText"] = "哦！\n我尽力了！",
  ["_RockTunnelB1FCooltrainerF2AfterBattleText"] = "我喜欢小巧的宝可梦，\n大个头的太吓人了！",
  ["_RockTunnelB1FCooltrainerF2BattleText"] = "我不常来这里，\n但还是会和你对战。",
  ["_RockTunnelB1FCooltrainerF2EndBattleText"] = "啊！\n我输了！",
  ["_RockTunnelB1FHiker1AfterBattleText"] = "我追求力量，\n因为我讨厌动脑！",
  ["_RockTunnelB1FHiker1BattleText"] = "哈哈哈！你能\n胜过我的力量吗？",
  ["_RockTunnelB1FHiker1EndBattleText"] = "哎呀！\n力量输给你了！",
  ["_RockTunnelB1FHiker2AfterBattleText"] = "山里经常能发现\n岩石属性的宝可梦。",
  ["_RockTunnelB1FHiker2BattleText"] = "我家宝可梦的招式\n会把你打哭！",
  ["_RockTunnelB1FHiker2EndBattleText"] = "我认输！\n你的技巧更胜一筹！",
  ["_RockTunnelB1FHiker3AfterBattleText"] = "我要把宝可梦练强，\n再打败你的宝可梦，小子！",
  ["_RockTunnelB1FHiker3BattleText"] = "使出你的\n看家本领吧！",
  ["_RockTunnelB1FHiker3EndBattleText"] = "火力\n全开了！",
  ["_RockTunnelB1FSuperNerd1AfterBattleText"] = "等你完成图鉴，\n能送给我吗？",
  ["_RockTunnelB1FSuperNerd1BattleText"] = "你有宝可梦图鉴？\n我也想要！",
  ["_RockTunnelB1FSuperNerd1EndBattleText"] = "可恶！\n真让人嫉妒！",
  ["_RockTunnelB1FSuperNerd2AfterBattleText"] = "角色扮演者会打扮成\n宝可梦取乐。",
  ["_RockTunnelB1FSuperNerd2BattleText"] = "你知道\n角色扮演者吗？",
  ["_RockTunnelB1FSuperNerd2EndBattleText"] = "好吧，\n就这样了。",
  ["_RockTunnelB1FSuperNerd3AfterBattleText"] = "我是艺术家，\n不是战士。",
  ["_RockTunnelB1FSuperNerd3BattleText"] = "我在家时\n会画宝可梦。",
  ["_RockTunnelB1FSuperNerd3EndBattleText"] = "呼！\n累死了！",
  ["_RockTunnelPokecenterFisherText"] = "我把没用的金珠\n卖了¥5000！",
  ["_RockTunnelPokecenterGentlemanText"] = "宝可梦的属性\n会让它们面对\v某些属性时更强，\v面对另一些时更弱！",
  ["_RockTunnelPokecenterGuyText"] = "听说紫苑镇\n有幽灵出没！",
  ["_RocketHide3AfterBattleText3"] = "你走吧！\n不过，没有电梯钥匙\v就开不了电梯！",
  ["_RocketHideout3BattleText"] = "楼上传来消息，\n说你要来了！",
  ["_RocketHideout3EndBattleText3"] = "什么？\n我输了？不！",
  ["_RocketHideoutB1FRocket1AfterBattleText"] = "你敢瞧不起\n火箭队？",
  ["_RocketHideoutB1FRocket1BattleText"] = "你是谁？\n怎么进来的？",
  ["_RocketHideoutB1FRocket1EndBattleText"] = "好痛！\n被打败了！",
  ["_RocketHideoutB1FRocket2AfterBattleText"] = "这事没完，\n小鬼！",
  ["_RocketHideoutB1FRocket2BattleText"] = "你竟敢闯进\n我们的基地？",
  ["_RocketHideoutB1FRocket2EndBattleText"] = "惨败！",
  ["_RocketHideoutB1FRocket3AfterBattleText"] = "西尔佛检视镜？\n我不知道\v它在哪里！",
  ["_RocketHideoutB1FRocket3BattleText"] = "发现入侵者！",
  ["_RocketHideoutB1FRocket3EndBattleText"] = "我\n办不到！",
  ["_RocketHideoutB1FRocket4AfterBattleText"] = "好，我说！\n乘电梯去见老大吧！",
  ["_RocketHideoutB1FRocket4BattleText"] = "你为什么\n来这里？",
  ["_RocketHideoutB1FRocket4EndBattleText"] = "这样\n可不行！",
  ["_RocketHideoutB1FRocket5AfterBattleText"] = "糟了，刚才的战斗\n把门震开了！",
  ["_RocketHideoutB1FRocket5BattleText"] = "迷路了吗，\n小老鼠？",
  ["_RocketHideoutB1FRocket5EndBattleText"] = "为什么……？",
  ["_RocketHideoutB2FRocketAfterBattleText"] = "火箭队总部\n有地下4层。\v你能走到老大面前吗？",
  ["_RocketHideoutB2FRocketBattleText"] = "老大说西尔佛检视镜\n能看见幽灵！",
  ["_RocketHideoutB2FRocketEndBattleText"] = "我\n投降！",
  ["_RocketHideoutB3FRocket1AfterBattleText"] = "西尔佛检视镜？\n就是老大偷来的机器。\v它就在这里某处。",
  ["_RocketHideoutB3FRocket1BattleText"] = "别插手\n火箭队的事！",
  ["_RocketHideoutB3FRocket1EndBattleText"] = "呜！\n被打倒了！",
  ["_RocketHideoutB4FGiovanniHopeWeMeetAgainText"] = "看得出来，\n你用心培育着\v宝可梦。\f像你这样的孩子\n不会明白\v我的宏图。\f这次我就\n先退让一步！\f希望我们\n还能再见……",
  ["_RocketHideoutB4FGiovanniImpressedYouGotHereText"] = "哦！你竟能\n来到这里，\v真让我刮目相看！",
  ["_RocketHideoutB4FGiovanniWhatCannotBeText"] = "什么！\n这不可能！",
  ["_RocketHideoutB4FRocketAfterBattleText"] = "糟了！我把\n电梯钥匙弄掉了！",
  ["_RocketHideoutB4FRocketBattleText"] = "电梯不动了？\n电梯钥匙在谁手里？",
  ["_RocketHideoutB4FRocketEndBattleText"] = "不！",
  ["_RocketHideoutElevatorAppearsToNeedKeyText"] = "看来需要\n一把钥匙。",
  ["_RocketHideoutJessieJamesText1"] = "不许再往前了，\n小鬼！",
  ["_RocketHideoutJessieJamesText2"] = "你竟敢在月见山\n羞辱我们！\f该算账了，\n小鬼！",
  ["_RocketHideoutJessieJamesText3"] = "真是个\n讨厌的小鬼！",
  ["_RocketHideoutJessieJamesText4"] = "火箭队又一次\n被打飞了！",
  ["_RoseText"] = "提升了！",
  ["_Route10CooltrainerF1AfterBattleText"] = "我注意到有几个\n怪兽狂在附近\v鬼鬼祟祟的。",
  ["_Route10CooltrainerF1BattleText"] = "我去过几次\n宝可梦道馆，\v但每次都输了。",
  ["_Route10CooltrainerF1EndBattleText"] = "唉！\n又搞砸了！",
  ["_Route10CooltrainerF2AfterBattleText"] = "这里的宝可梦\n都圆滚滚的！\v应该有一只粉红色，\v身上还有花纹的！",
  ["_Route10CooltrainerF2BattleText"] = "这趟艰苦的徒步\n让我有点头晕。",
  ["_Route10CooltrainerF2EndBattleText"] = "我\n撑不住了！",
  ["_Route10Hiker1AfterBattleText"] = "哈——哈啾！\n哈啾！\v吸！抽鼻子！",
  ["_Route10Hiker1BattleText"] = "哈、哈哈、哈——哈！",
  ["_Route10Hiker1EndBattleText"] = "哈、哈哈！\n我没在笑！\v是花粉症！\v哈——哈啾！",
  ["_Route10Hiker2AfterBattleText"] = "山里的空气\n都快把我撑饱了！",
  ["_Route10Hiker2BattleText"] = "啊！这山里的空气\n真美味！",
  ["_Route10Hiker2EndBattleText"] = "这下\n头脑清醒了！",
  ["_Route10PowerPlantSignText"] = "无人发电厂",
  ["_Route10RockTunnelSignText"] = "岩山隧道",
  ["_Route10SuperNerd1AfterBattleText"] = "我家里还有更多\n稀有宝可梦！",
  ["_Route10SuperNerd1BattleText"] = "哇，你也是怪兽狂？\n想看看我的收藏吗？",
  ["_Route10SuperNerd1EndBattleText"] = "哼。\n我才没生气！",
  ["_Route10SuperNerd2AfterBattleText"] = "你打败了我，\n所以我讨厌你！",
  ["_Route10SuperNerd2BattleText"] = "嗨，小子，想看看\n我的宝可梦吗？",
  ["_Route10SuperNerd2EndBattleText"] = "不！\n我的宝可梦！",
  ["_Route11DiglettsCaveSignText"] = "地鼠洞穴",
  ["_Route11Gambler1AfterBattleText"] = "宝可梦就是人生！\n人生就是一场赌博！",
  ["_Route11Gambler1BattleText"] = "不论输赢还是平局！",
  ["_Route11Gambler1EndBattleText"] = "哎呀！\n运气不在我这边！",
  ["_Route11Gambler2AfterBattleText"] = "在宝可梦的世界里\n可不能当胆小鬼！",
  ["_Route11Gambler2BattleText"] = "比赛再多\n我也嫌不够！",
  ["_Route11Gambler2EndBattleText"] = "我本来\n有机会的！",
  ["_Route11Gambler3AfterBattleText"] = "抽到什么全凭运气！\n只是运气！",
  ["_Route11Gambler3BattleText"] = "哇哈哈！\n我从没输过！",
  ["_Route11Gambler3EndBattleText"] = "第一次\n输了！",
  ["_Route11Gambler4AfterBattleText"] = "只是运气。\n全看抽到什么牌。",
  ["_Route11Gambler4BattleText"] = "我以前\n从没赢过……",
  ["_Route11Gambler4EndBattleText"] = "我早就\n料到了……",
  ["_Route11Gate1FGuardText"] = "捉到很多宝可梦后，\n是不是很难\v想出名字？\f紫苑镇有位先生\n专门评价宝可梦的\v昵称。\f他也能帮你\n改名字！",
  ["_Route11Gate2FLeftBinocularsNoSnorlaxText"] = "看向望远镜。\f景色真美！",
  ["_Route11Gate2FLeftBinocularsSnorlaxText"] = "看向望远镜。\f路上睡着一只\n巨大的宝可梦！",
  ["_Route11Gate2FOaksAideItemfinderDescriptionText"] = "地上有些道具\n用眼睛看不到。\f探宝器能发现\n你附近的道具。\f但它无法指出\n准确位置，\v还得靠你自己找！",
  ["_Route11Gate2FRightBinocularsText"] = "看向望远镜。\f从华蓝市\n前往紫苑镇，\v只有岩山隧道\v这一条路。",
  ["_Route11SuperNerd1AfterBattleText"] = "告诉大家\n要节约能源！",
  ["_Route11SuperNerd1BattleText"] = "小心！\n我正在铺电缆！",
  ["_Route11SuperNerd1EndBattleText"] = "真是\n电力十足！",
  ["_Route11SuperNerd2AfterBattleText"] = "好吧，该回去\n工作了。",
  ["_Route11SuperNerd2BattleText"] = "小心带电的\n电线！",
  ["_Route11SuperNerd2EndBattleText"] = "哇！\n你这火花塞！",
  ["_Route11Youngster1AfterBattleText"] = "我尽力了！\n没有遗憾！",
  ["_Route11Youngster1BattleText"] = "来吧，\n但不许作弊！",
  ["_Route11Youngster1EndBattleText"] = "咦？\n不该是这样！",
  ["_Route11Youngster2AfterBattleText5"] = "你想干吗？\n别烦我！",
  ["_Route11Youngster2BattleText"] = "我刚成为训练家！\n但我觉得能赢！",
  ["_Route11Youngster2EndBattleText"] = "我的\n宝可梦没能赢！",
  ["_Route11Youngster3AfterBattleText"] = "有只胖胖的宝可梦\n会从山里下来。\f要是能捉到它，\n它可是很强的！",
  ["_Route11Youngster3BattleText"] = "我是班里\n最厉害的！",
  ["_Route11Youngster3EndBattleText"] = "可恶！\n我得让宝可梦\v变得更强！",
  ["_Route11Youngster4AfterBattleText"] = "我还是去找\n更强的宝可梦吧！",
  ["_Route11Youngster4BattleText"] = "我的宝可梦\n现在应该准备好了！",
  ["_Route11Youngster4EndBattleText"] = "太强了，\n我还太嫩！",
  ["_Route12CooltrainerMAfterBattleText"] = "我本来能用月之石\n让宝可梦进化！",
  ["_Route12CooltrainerMBattleText"] = "你找到过\n月之石吗？",
  ["_Route12CooltrainerMEndBattleText"] = "好痛！",
  ["_Route12Fisher1AfterBattleText"] = "等等！我的钓线\n缠住了！",
  ["_Route12Fisher1BattleText"] = "嘿！这里有鱼\n上钩了！",
  ["_Route12Fisher1EndBattleText"] = "啧！\n只是条小鱼！",
  ["_Route12Fisher2AfterBattleText"] = "有更好的钓竿，\n就能钓到\v更好的宝可梦！",
  ["_Route12Fisher2BattleText"] = "耐心点！\n钓鱼就是等待！",
  ["_Route12Fisher2EndBattleText"] = "那条\n逃掉了！",
  ["_Route12Fisher3AfterBattleText"] = "宝可梦对战我输了，\n但钓鱼可是我的强项！",
  ["_Route12Fisher3BattleText"] = "钓鱼狂人\n对宝可梦小子！",
  ["_Route12Fisher3EndBattleText"] = "太\n强了！",
  ["_Route12Fisher4AfterBattleText"] = "没关系。\n现在输了我也不在乎了。",
  ["_Route12Fisher4BattleText"] = "我宁愿\n去工作！",
  ["_Route12Fisher4EndBattleText"] = "真\n不容易……",
  ["_Route12Fisher5AfterBattleText"] = "我总能钓到鲤鱼王，\n可它们太弱了！",
  ["_Route12Fisher5BattleText"] = "谁也不知道\n会钓到什么！",
  ["_Route12Fisher5EndBattleText"] = "让它\n跑了！",
  ["_Route12Gate1FGuardText"] = "楼上有个\n瞭望台。",
  ["_Route12Gate2FBrunetteGirlReceivedTM39Text"] = "{PLAYER}获得了\n招式学习器39！",
  ["_Route12Gate2FBrunetteGirlTM39ExplanationText"] = "招式学习器39是\n高速星星。\f它的命中率很高，\n在不能输的对战中\v很有用。",
  ["_Route12Gate2FBrunetteGirlTM39NoRoomText"] = "背包里没地方\n放这个了。",
  ["_Route12Gate2FBrunetteGirlYouCanHaveThisText"] = "我的宝可梦骨灰\n供奉在宝可梦塔。\f这个招式学习器\n送给你。\v我已经不需要了……",
  ["_Route12Gate2FLeftBinocularsText"] = "看向望远镜。\f有人在钓鱼！",
  ["_Route12Gate2FRightBinocularsText"] = "看向望远镜。\f是宝可梦塔！",
  ["_Route12SignText"] = "12号道路\n向北前往紫苑镇",
  ["_Route12SnorlaxCalmedDownText"] = "卡比兽平静下来！\n它打了个大哈欠，\v回山里去了！",
  ["_Route12SnorlaxText"] = "一只睡着的宝可梦\n挡住了路！",
  ["_Route12SnorlaxWokeUpText"] = "卡比兽醒了！\f它满肚子起床气，\n发动了攻击！",
  ["_Route12SportFishingSignText"] = "垂钓区",
  ["_Route12SuperNerdAfterBattleText"] = "水能导电，\n所以应该用电\v攻击海里的宝可梦！",
  ["_Route12SuperNerdBattleText"] = "电属性是我的\n专长！",
  ["_Route12SuperNerdEndBattleText"] = "断电了！",
  ["_Route12SuperRodHouseFishingGuruDoYouLikeToFishText"] = "我是钓鱼大师的\n弟弟！\f我最——喜欢\n钓鱼！\f你喜欢钓鱼吗？",
  ["_Route12SuperRodHouseFishingGuruFishingWayOfLifeText"] = "\f钓鱼就是人生！\f从大海到河流，\n都去试试看，\v钓条大家伙吧！",
  ["_Route12SuperRodHouseFishingGuruNoRoomText"] = "糟糕！\f我本来有礼物\n要送你，\v但你没地方放！",
  ["_Route12SuperRodHouseFishingGuruReceivedSuperRodText"] = "太好了！我喜欢\n你这股劲！\f拿上这个去钓鱼吧，\n年轻人！\f{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_Route12SuperRodHouseFishingGuruThatsDisappointingText"] = "哦……真是\n令人失望……",
  ["_Route12SuperRodHouseFishingGuruTryFishingText"] = "你好，{PLAYER}！\f在任何水域都能\n使用厉害钓竿！\v可以钓到\v不同种类的宝可梦。\f能钓鱼的地方\n都试试吧！",
  ["_Route13Beauty1AfterBattleText"] = "雄性和雌性的宝可梦，\n哪一边更强呢？",
  ["_Route13Beauty1BattleText"] = "好啊，我来\n陪你玩！",
  ["_Route13Beauty1EndBattleText"] = "哎呀！\n你这小蛮牛！",
  ["_Route13Beauty2AfterBattleText"] = "我不懂宝可梦，\n只是喜欢帅气的！",
  ["_Route13Beauty2BattleText"] = "要和我来一场\n宝可梦对战吗？",
  ["_Route13Beauty2EndBattleText"] = "已经\n结束了？",
  ["_Route13BikerAfterBattleText"] = "滚开！",
  ["_Route13BikerBattleText"] = "你看\n什么看？",
  ["_Route13BikerEndBattleText"] = "可恶！\n齿轮崩了！",
  ["_Route13CooltrainerF1AfterBattleText"] = "我想成为\n优秀的训练家。\v我要努力训练。",
  ["_Route13CooltrainerF1BattleText"] = "大家都说，\n以小孩来说我很厉害！",
  ["_Route13CooltrainerF1EndBattleText"] = "唉！\n我输了！",
  ["_Route13CooltrainerF2AfterBattleText"] = "我知道！那些徽章\n是从道馆馆主那里赢来的！",
  ["_Route13CooltrainerF2BattleText"] = "哇！你的徽章\n太酷了！",
  ["_Route13CooltrainerF2EndBattleText"] = "还\n不够！",
  ["_Route13CooltrainerF3AfterBattleText"] = "要让宝可梦对战，\n它们才会变强！",
  ["_Route13CooltrainerF3BattleText"] = "我可爱的宝可梦想\n认识一下你。",
  ["_Route13CooltrainerF3EndBattleText"] = "哇！\n你赢得太漂亮了！",
  ["_Route13CooltrainerF4AfterBattleText"] = "速度增强剂提高了\n我宝可梦的速度。",
  ["_Route13CooltrainerF4BattleText"] = "我曾在洞穴里\n找到速度增强剂。",
  ["_Route13CooltrainerF4EndBattleText"] = "刚才\n搞砸了！",
  ["_Route13CooltrainerM1AfterBattleText"] = "我的宝可梦虽然输了，\n看起来还是很开心。",
  ["_Route13CooltrainerM1BattleText"] = "我的鸟宝可梦\n想打一架！",
  ["_Route13CooltrainerM1EndBattleText"] = "我的鸟宝可梦阵容\n竟然输了？",
  ["_Route13CooltrainerM2AfterBattleText"] = "我累坏了。\n还是用飞翔回家吧。",
  ["_Route13CooltrainerM2BattleText"] = "风正吹向\n我这一边！",
  ["_Route13CooltrainerM2EndBattleText"] = "风向\n变了！",
  ["_Route13CooltrainerM3AfterBattleText"] = "真希望我能像波波\n和比比鸟一样飞……",
  ["_Route13CooltrainerM3BattleText"] = "我永远选择\n鸟宝可梦！",
  ["_Route13CooltrainerM3EndBattleText"] = "力量\n用尽了！",
  ["_Route13SignText"] = "13号道路\n向北前往寂静桥",
  ["_Route13TrainerTips1Text"] = "训练家提示\f看看那根柱子的\n左边！",
  ["_Route13TrainerTips2Text"] = "训练家提示\f在道具窗口按SELECT\n可以调整道具顺序！",
  ["_Route14Biker1AfterBattleText"] = "什么，什么，什么？\n你想干吗？",
  ["_Route14Biker1BattleText"] = "来啊，来啊。\n开打，开打，开打！",
  ["_Route14Biker1EndBattleText"] = "啊！\n输了！滚开！",
  ["_Route14Biker2AfterBattleText"] = "培育宝可梦\n真麻烦啊。",
  ["_Route14Biker2BattleText"] = "正好！我正想\n打发时间！",
  ["_Route14Biker2EndBattleText"] = "什么？\n就凭你！？",
  ["_Route14Biker3AfterBattleText"] = "你把宝可梦\n练得这么强，真酷！\f强者为王！\n你也明白吧！",
  ["_Route14Biker3BattleText"] = "我们来这里骑车，\n因为地方更宽敞！",
  ["_Route14Biker3EndBattleText"] = "被横扫了！",
  ["_Route14Biker4AfterBattleText"] = "要是你我单挑，\n谁赢还用说吗！",
  ["_Route14Biker4BattleText"] = "宝可梦对战？\n好啊！来打！",
  ["_Route14Biker4EndBattleText"] = "被打\n飞了！",
  ["_Route14CooltrainerM1AfterBattleText"] = "你有秘传学习器吧？\n宝可梦永远无法忘记\v那些招式。",
  ["_Route14CooltrainerM1BattleText"] = "得用招式学习器\n教宝可梦厉害招式！",
  ["_Route14CooltrainerM1EndBattleText"] = "还\n不够好！",
  ["_Route14CooltrainerM2AfterBattleText"] = "它们得学习\n更好的招式。",
  ["_Route14CooltrainerM2BattleText"] = "我的鸟宝可梦\n应该准备好对战了。",
  ["_Route14CooltrainerM2EndBattleText"] = "还没\n准备好！",
  ["_Route14CooltrainerM3AfterBattleText"] = "教宝可梦使用\n与自身属性相同的招式，\v威力会更强。",
  ["_Route14CooltrainerM3BattleText"] = "玉虹市有卖\n招式学习器！\v但秘传学习器\v只有少数人拥有！",
  ["_Route14CooltrainerM3EndBattleText"] = "唉，\n真倒霉！",
  ["_Route14CooltrainerM4AfterBattleText"] = "鸟宝可梦\n才是我的真爱！",
  ["_Route14CooltrainerM4BattleText"] = "你教鸟宝可梦\n使用飞翔了吗？",
  ["_Route14CooltrainerM4EndBattleText"] = "被击落了！",
  ["_Route14CooltrainerM5AfterBattleText"] = "3只传说中的宝可梦\n都是猛禽。",
  ["_Route14CooltrainerM5BattleText"] = "你听说过\n传说的宝可梦吗？",
  ["_Route14CooltrainerM5EndBattleText"] = "为什么？\n我为什么会输？",
  ["_Route14CooltrainerM6AfterBattleText"] = "从长远看，\n输赢都不重要！",
  ["_Route14CooltrainerM6BattleText"] = "我没什么兴致，\n不过好吧！来！",
  ["_Route14CooltrainerM6EndBattleText"] = "我\n就知道！",
  ["_Route14SignText"] = "14号道路\n向西前往浅红市",
  ["_Route15Beauty1AfterBattleText"] = "我原谅你！\n这点打击我受得住！",
  ["_Route15Beauty1BattleText"] = "哦，你真是个\n小可爱！",
  ["_Route15Beauty1EndBattleText"] = "你明明也\n那么可爱！",
  ["_Route15Beauty2AfterBattleText"] = "我只想回家\n陪我的宝可梦！",
  ["_Route15Beauty2BattleText"] = "我一个人生活，\n所以才培育宝可梦！",
  ["_Route15Beauty2EndBattleText"] = "我可没\n自找这事！",
  ["_Route15Biker1AfterBattleText"] = "人只活一次，\n所以我就当亡命徒！\v火箭队万岁！",
  ["_Route15Biker1BattleText"] = "嘿，小鬼！来吧！\n我刚弄到这些！",
  ["_Route15Biker1EndBattleText"] = "怎么\n会？",
  ["_Route15Biker2AfterBattleText"] = "要钱的事\n我只是开玩笑！",
  ["_Route15Biker2BattleText"] = "小鬼，输给我后\n把钱全交出来！",
  ["_Route15Biker2EndBattleText"] = "这\n不可能！",
  ["_Route15CooltrainerF1AfterBattleText"] = "交换得到的宝可梦\n不能更改昵称。\f只有初训家\n才能改。",
  ["_Route15CooltrainerF1BattleText"] = "让我试试刚交换来的\n宝可梦！",
  ["_Route15CooltrainerF1EndBattleText"] = "还\n不够好！",
  ["_Route15CooltrainerF2AfterBattleText"] = "我害怕飙车族，\n他们看起来又凶又丑！",
  ["_Route15CooltrainerF2BattleText"] = "你看起来很温和，\n我应该能打赢你！",
  ["_Route15CooltrainerF2EndBattleText"] = "不，\n我错了！",
  ["_Route15CooltrainerF3AfterBattleText"] = "我会和朋友\n交换宝可梦！",
  ["_Route15CooltrainerF3BattleText"] = "什么最酷？\n交换宝可梦！",
  ["_Route15CooltrainerF3EndBattleText"] = "我说的是\n交换！",
  ["_Route15CooltrainerF4AfterBattleText"] = "我要去找\n更弱的人训练。",
  ["_Route15CooltrainerF4BattleText"] = "想和我的宝可梦\n玩吗？",
  ["_Route15CooltrainerF4EndBattleText"] = "我太\n心急了！",
  ["_Route15CooltrainerM1AfterBattleText"] = "也许我不适合\n对战。",
  ["_Route15CooltrainerM1BattleText"] = "我一吹口哨，\n就能召来鸟宝可梦！",
  ["_Route15CooltrainerM1EndBattleText"] = "好痛！\n真惨！",
  ["_Route15CooltrainerM2AfterBattleText"] = "你知道地震这类招式\n对鸟宝可梦无效吗？",
  ["_Route15CooltrainerM2BattleText"] = "嗯？我的鸟宝可梦\n在发抖！\v你很强，对吧？",
  ["_Route15CooltrainerM2EndBattleText"] = "果然不出我所料！",
  ["_Route15Gate1FGuardText"] = "你在制作\n宝可梦图鉴吗？\f大木博士的助手\n刚来过这里。",
  ["_Route15Gate2FBinocularsText"] = "看向望远镜。\f看起来像一座\n小岛！",
  ["_Route15Gate2FOaksAideExpAllText"] = "学习装置会让\n同行的所有宝可梦\v获得经验值，\v即使没有参加战斗。\f不过，每只宝可梦\n分到的经验值会减少。\f如果用不到，\n就存进电脑吧。",
  ["_Route15SignText"] = "15号道路\n向西前往浅红市",
  ["_Route15UpstairsBinocularsText"] = "看向望远镜……\f一只巨大而闪耀的鸟\n正飞向大海。",
  ["_Route16Biker1AfterBattleText"] = "我们只喜欢\n待在这里，\v关你什么事？",
  ["_Route16Biker1BattleText"] = "你想干吗？",
  ["_Route16Biker1EndBattleText"] = "不许笑我！",
  ["_Route16Biker2AfterBattleText"] = "算了，谁稀罕\n你的自行车！",
  ["_Route16Biker2BattleText"] = "自行车不错！\n交出来！",
  ["_Route16Biker2EndBattleText"] = "被击\n倒了！",
  ["_Route16Biker3AfterBattleText"] = "我讨厌输！\n离我远点！",
  ["_Route16Biker3BattleText"] = "出来玩吧，\n小老鼠！",
  ["_Route16Biker3EndBattleText"] = "你这\n小老鼠！",
  ["_Route16Biker4AfterBattleText"] = "从枯叶市沿着海岸路\n也能到浅红市。",
  ["_Route16Biker4EndBattleText"] = "轰隆！",
  ["_Route16Biker5AfterBattleText"] = "我喜欢凶猛的宝可梦！\n它们会撕碎敌人！",
  ["_Route16Biker5BattleText"] = "我现在又饿\n又暴躁！",
  ["_Route16Biker5EndBattleText"] = "糟，\n糟，糟！",
  ["_Route16Biker6AfterBattleText"] = "我喜欢用凶恶的\n宝可梦骚扰别人！",
  ["_Route16Biker6BattleText"] = "好，我来！",
  ["_Route16Biker6EndBattleText"] = "别惹\n我生气！",
  ["_Route16CyclingRoadSignText"] = "享受下坡吧！\n自行车道",
  ["_Route16FlyHouseBrunetteGirlHM02ExplanationText"] = "秘传学习器02是\n飞翔。\v能带你回到\v去过的任何城镇。\f好好利用吧！",
  ["_Route16FlyHouseBrunetteGirlHM02NoRoomText"] = "背包里没地方\n放这个了。",
  ["_Route16FlyHouseBrunetteGirlReceivedHM02Text"] = "{PLAYER}获得了\n秘传学习器02！",
  ["_Route16FlyHouseBrunetteGirlText"] = "哦，你发现了\n我的秘密住处！\f请别告诉别人\n我在这里。\v这个送给你，\v算作回报！",
  ["_Route16FlyHouseFearowText"] = "大嘴雀：啾——！",
  ["_Route16Gate1FGamblerText"] = "你怎么进来的？\n干得不错！",
  ["_Route16Gate1FGuardCyclingRoadExplanationText"] = "自行车道是\n沿海的下坡路线。\v骑起来很过瘾。",
  ["_Route16Gate1FGuardNoPedestriansAllowedText"] = "自行车道\n不许行人进入！",
  ["_Route16Gate1FGuardWaitUpText"] = "不好意思！\n请等一下！",
  ["_Route16Gate2FLeftBinocularsText"] = "看向望远镜。\f是玉虹百货大楼！",
  ["_Route16Gate2FLittleBoyText"] = "我要和女朋友\n一起骑车！",
  ["_Route16Gate2FLittleGirlText"] = "我们要一起\n骑车！",
  ["_Route16Gate2FRightBinocularsText"] = "看向望远镜。\f水面上有一条\n长长的道路！",
  ["_Route16SignText"] = "16号道路\n玉虹市—浅红市",
  ["_Route16SnorlaxReturnedToMountainsText"] = "卡比兽打了个大哈欠，\n回山里去了！",
  ["_Route16SnorlaxWokeUpText"] = "卡比兽醒了！\f它满肚子起床气，\n发动了攻击！",
  ["_Route16Text7"] = "一只睡着的宝可梦\n挡住了路！",
  ["_Route16biker4BattleText"] = "嘿，你刚才\n撞到我了！",
  ["_Route17Biker10AfterBattleText"] = "我得睡上\n一会儿！",
  ["_Route17Biker10BattleText"] = "滚开，小鬼！\n我累坏了！",
  ["_Route17Biker10EndBattleText"] = "你满意\n了吧？",
  ["_Route17Biker1AfterBattleText"] = "自行车道上\n散落着好东西！",
  ["_Route17Biker1BattleText"] = "和小孩打架\n又赚不到钱！",
  ["_Route17Biker1EndBattleText"] = "燃尽\n了！",
  ["_Route17Biker2AfterBattleText"] = "我能用肚子\n把你撞出去！",
  ["_Route17Biker2BattleText"] = "小家伙，\n你想干吗？",
  ["_Route17Biker2EndBattleText"] = "呜！",
  ["_Route17Biker3AfterBattleText"] = "我最喜欢\n冲下坡！",
  ["_Route17Biker3BattleText"] = "你要去\n浅红市吗？",
  ["_Route17Biker3EndBattleText"] = "摔得\n真惨！",
  ["_Route17Biker4AfterBattleText"] = "你在寻找\n刺激吗？",
  ["_Route17Biker4BattleText"] = "我们是飙车族！\n公路明星！",
  ["_Route17Biker4EndBattleText"] = "输惨了！",
  ["_Route17Biker5AfterBattleText"] = "我的霹雳电球\n是在无人发电厂抓的。",
  ["_Route17Biker5BattleText"] = "让霹雳电球\n电你一下！",
  ["_Route17Biker5EndBattleText"] = "短路\n了！",
  ["_Route17Biker6AfterBattleText"] = "也许有些宝可梦\n需要进化石才能进化。",
  ["_Route17Biker6BattleText"] = "我的宝可梦\n怎么不进化？",
  ["_Route17Biker6EndBattleText"] = "你这\n家伙！",
  ["_Route17Biker7AfterBattleText"] = "我肯定瘦了不少！",
  ["_Route17Biker7BattleText"] = "我需要\n活动一下！",
  ["_Route17Biker7EndBattleText"] = "呼！\n锻炼得不错！",
  ["_Route17Biker8AfterBattleText"] = "准备好为自己的信念\n而战吧！",
  ["_Route17Biker8BattleText"] = "做个叛逆者！",
  ["_Route17Biker8EndBattleText"] = "啊——！",
  ["_Route17Biker9AfterBattleText"] = "下坡时很难\n控制方向！",
  ["_Route17Biker9BattleText"] = "自行车不错！\n操控起来怎么样？",
  ["_Route17Biker9EndBattleText"] = "可恶！",
  ["_Route17CyclingRoadEndsSignText"] = "自行车道\n下坡到此结束！",
  ["_Route17NoticeSign1Text"] = "是告示！\f小心被丢弃的\n道具！",
  ["_Route17NoticeSign2Text"] = "是告示！\f别故意输掉比赛，\n要扔就扔精灵球！",
  ["_Route17SignText"] = "17号道路\n玉虹市—浅红市",
  ["_Route17TrainerTips1Text"] = "训练家提示\f每只宝可梦\n都独一无二。\f即使属性和等级相同，\n成长速度也会不同。",
  ["_Route17TrainerTips2Text"] = "训练家提示\f在斜坡上按A键或B键，\n可以停在原地。",
  ["_Route18CooltrainerM1AfterBattleText"] = "真希望我有\n自行车！",
  ["_Route18CooltrainerM1BattleText"] = "我总会检查每片草丛，\n寻找新的宝可梦。",
  ["_Route18CooltrainerM1EndBattleText"] = "啧！",
  ["_Route18CooltrainerM2AfterBattleText"] = "周末我还会收集\n海里的宝可梦！",
  ["_Route18CooltrainerM2BattleText"] = "咕噜咕咕！\n我的鸟叫学得怎么样？",
  ["_Route18CooltrainerM2EndBattleText"] = "打扰你了！",
  ["_Route18CooltrainerM3AfterBattleText"] = "这里是我最喜欢的\n宝可梦狩猎区！",
  ["_Route18CooltrainerM3BattleText"] = "这是我的地盘！\n滚出去！",
  ["_Route18CooltrainerM3EndBattleText"] = "可恶！",
  ["_Route18CyclingRoadSignText"] = "自行车道\n禁止行人进入！",
  ["_Route18Gate1FGuardCyclingRoadUphillText"] = "从这里开始，\n自行车道全是上坡。",
  ["_Route18Gate1FGuardExcuseMeText"] = "不好意思！",
  ["_Route18Gate1FGuardYouNeedABicycleText"] = "要进入自行车道，\n你需要自行车！",
  ["_Route18Gate2FLeftBinocularsText"] = "看向望远镜。\f真新镇在西边！",
  ["_Route18Gate2FRightBinocularsText"] = "看向望远镜。\f有人在游泳！",
  ["_Route18SignText"] = "18号道路\n玉虹市—浅红市",
  ["_Route19CooltrainerM1AfterBattleText"] = "谢了，小鬼！\n我准备好去游泳了！",
  ["_Route19CooltrainerM1BattleText"] = "游泳前\n得先热身！",
  ["_Route19CooltrainerM1EndBattleText"] = "热身\n完成！",
  ["_Route19CooltrainerM2AfterBattleText"] = "小心\n玛瑙水母！",
  ["_Route19CooltrainerM2BattleText"] = "等等！你会\n心脏病发作的！",
  ["_Route19CooltrainerM2EndBattleText"] = "哦！\n真冷！",
  ["_Route19SignText"] = "19号水路\n浅红市—双子岛",
  ["_Route19Swimmer1AfterBattleText"] = "游泳比赛中，\n我能赢过宝可梦！",
  ["_Route19Swimmer1BattleText"] = "我喜欢游泳！\n你呢？",
  ["_Route19Swimmer1EndBattleText"] = "肚皮\n着水！",
  ["_Route19Swimmer2AfterBattleText"] = "我看见了\n两座岛！",
  ["_Route19Swimmer2BattleText"] = "海平线那边\n有什么？",
  ["_Route19Swimmer2EndBattleText"] = "咕噜！",
  ["_Route19Swimmer3AfterBattleText"] = "海里的宝可梦\n得用钓的！",
  ["_Route19Swimmer3BattleText"] = "我试过潜水\n捉宝可梦，\v但根本行不通！",
  ["_Route19Swimmer3EndBattleText"] = "救命！",
  ["_Route19Swimmer4AfterBattleText"] = "我望着大海，\n想忘掉烦恼！",
  ["_Route19Swimmer4BattleText"] = "我看着大海，\n想忘掉烦恼！",
  ["_Route19Swimmer4EndBattleText"] = "哦！\n真受打击！",
  ["_Route19Swimmer5AfterBattleText"] = "到双子岛\n还有很远的路。",
  ["_Route19Swimmer5BattleText"] = "我太喜欢你的坐骑了！\n要是我赢了能给我吗？",
  ["_Route19Swimmer5EndBattleText"] = "哦！\n我输了！",
  ["_Route19Swimmer6AfterBattleText"] = "我男朋友想\n游去双子岛。",
  ["_Route19Swimmer6BattleText"] = "游泳很棒！\n晒伤就不棒了！",
  ["_Route19Swimmer6EndBattleText"] = "真没想到！",
  ["_Route19Swimmer7AfterBattleText"] = "我抽筋了！\n咕噜，咕噜……",
  ["_Route19Swimmer7BattleText"] = "这片水域\n很危险！",
  ["_Route19Swimmer7EndBattleText"] = "哦！\n太危险了！",
  ["_Route19Swimmer8AfterBattleText"] = "拉普拉斯那么大，\n骑着它肯定不会被水弄湿！",
  ["_Route19Swimmer8BattleText"] = "我是游过来的，\n但已经累了。",
  ["_Route19Swimmer8EndBattleText"] = "我\n筋疲力尽了……",
  ["_Route1SignText"] = "1号道路\n真新镇—常青市",
  ["_Route1Youngster1AlsoGotPokeballsText"] = "我们也卖用来收服\n宝可梦的精灵球！",
  ["_Route1Youngster1GotPotionText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_Route1Youngster1MartSampleText"] = "你好！我在友好商店工作。\f店里购物很方便，\n请到常青市的店里看看。\f对了，送你一份试用装！\n拿好！",
  ["_Route1Youngster1NoRoomText"] = "你带的东西太多了！",
  ["_Route1Youngster2Text"] = "看到路边的台阶了吗？\f虽然有点吓人，\n但可以从上面跳下去。\f这样能更快回到真新镇。",
  ["_Route20CooltrainerMAfterBattleText"] = "我的鸟不能用飞翔\n载我回去了！",
  ["_Route20CooltrainerMBattleText"] = "我是骑着鸟宝可梦\n来这里的！",
  ["_Route20CooltrainerMEndBattleText"] = "哦，\n不！",
  ["_Route20SeafoamIslandsSignText"] = "双子岛",
  ["_Route20Swimmer1AfterBattleText"] = "真希望能骑着\n我的宝可梦。",
  ["_Route20Swimmer1BattleText"] = "这里的水\n很浅。",
  ["_Route20Swimmer1EndBattleText"] = "扑通！",
  ["_Route20Swimmer2AfterBattleText"] = "这座岛下面\n有个巨大洞窟。",
  ["_Route20Swimmer2BattleText"] = "双子岛是个\n安静的度假地！",
  ["_Route20Swimmer2EndBattleText"] = "住手！",
  ["_Route20Swimmer3AfterBattleText"] = "想和我一起\n漂着吗？",
  ["_Route20Swimmer3BattleText"] = "我喜欢和鱼群\n一起漂浮！",
  ["_Route20Swimmer3EndBattleText"] = "好痛！",
  ["_Route20Swimmer4AfterBattleText"] = "双子岛以前\n是一座岛！",
  ["_Route20Swimmer4BattleText"] = "你也是来\n度假的吗？",
  ["_Route20Swimmer4EndBattleText"] = "一点都\n不留情！",
  ["_Route20Swimmer5AfterBattleText"] = "我该锻炼的是\n宝可梦，不是自己！",
  ["_Route20Swimmer5BattleText"] = "看看我这\n壮实的身材！",
  ["_Route20Swimmer5EndBattleText"] = "太弱了！",
  ["_Route20Swimmer6AfterBattleText"] = "骑着宝可梦\n看起来真有趣！",
  ["_Route20Swimmer6BattleText"] = "你为什么骑宝可梦？\n不会游泳吗？",
  ["_Route20Swimmer6EndBattleText"] = "好痛！\n被鱼雷击中了！",
  ["_Route20Swimmer7AfterBattleText"] = "我的珍珠放在刺甲贝里\n会不会长大？",
  ["_Route20Swimmer7BattleText"] = "男朋友送了我\n大珍珠！",
  ["_Route20Swimmer7EndBattleText"] = "别碰\n我的珍珠！",
  ["_Route20Swimmer8AfterBattleText"] = "宝可梦占领了\n红莲镇上一栋\v废弃的宅邸！",
  ["_Route20Swimmer8BattleText"] = "我是从红莲镇\n游过来的！",
  ["_Route20Swimmer8EndBattleText"] = "我\n太失望了！",
  ["_Route20Swimmer9AfterBattleText"] = "红莲镇位于\n一座火山岛上！",
  ["_Route20Swimmer9BattleText"] = "西边的红莲镇\n有座宝可梦研究所。",
  ["_Route20Swimmer9EndBattleText"] = "等等！",
  ["_Route21Fisher1AfterBattleText"] = "我怎么都钓不到\n好东西！",
  ["_Route21Fisher1BattleText"] = "你想知道\n有没有鱼上钩吗？",
  ["_Route21Fisher1EndBattleText"] = "可恶！",
  ["_Route21Fisher2AfterBattleText"] = "我好像只会\n钓到鲤鱼王！",
  ["_Route21Fisher2BattleText"] = "我大丰收了！\n你想试试吗？",
  ["_Route21Fisher2EndBattleText"] = "可恶的\n鲤鱼王！",
  ["_Route21Fisher3AfterBattleText"] = "我只是因为\n什么都钓不到才生气。",
  ["_Route21Fisher3BattleText"] = "喂，别把鱼\n吓跑了！",
  ["_Route21Fisher3EndBattleText"] = "对不起！\n我不是故意的！",
  ["_Route21Fisher4AfterBattleText"] = "等等！有鱼\n上钩了！太好了！",
  ["_Route21Fisher4BattleText"] = "在鱼上钩前\n陪陪我吧！",
  ["_Route21Fisher4EndBattleText"] = "这下\n打发了点时间。",
  ["_Route21Swimmer1AfterBattleText"] = "我也喜欢\n山！",
  ["_Route21Swimmer1BattleText"] = "大海净化了\n我的身心！",
  ["_Route21Swimmer1EndBattleText"] = "哎呀！",
  ["_Route21Swimmer2AfterBattleText"] = "我看起来像什么？\n带刺的游泳圈？滚开！",
  ["_Route21Swimmer2BattleText"] = "我游泳\n有什么问题？",
  ["_Route21Swimmer2EndBattleText"] = "偷袭！",
  ["_Route21Swimmer3AfterBattleText"] = "你的宝可梦\n是在哪里捉的？",
  ["_Route21Swimmer3BattleText"] = "我的宝可梦\n全是在海里捉的！",
  ["_Route21Swimmer3EndBattleText"] = "潜水员！！\n下潜！！",
  ["_Route21Swimmer4AfterBattleText"] = "我累坏了！\n但还有自行车赛\v和马拉松等着我！",
  ["_Route21Swimmer4BattleText"] = "我正在参加\n铁人三项！",
  ["_Route21Swimmer4EndBattleText"] = "呼哧……\n呼哧……呼哧……",
  ["_Route21Swimmer5AfterBattleText"] = "我晒得\n焦黑了！",
  ["_Route21Swimmer5BattleText"] = "啊！感受阳光\n和海风吧！",
  ["_Route21Swimmer5EndBattleText"] = "哎哟！\n我输了！",
  ["_Route22GateGuardGoRightAheadText"] = "哦！是灰色徽章！\n请通过吧！",
  ["_Route22GateGuardICantLetYouPassText"] = "\f规定就是规定。\n我不能让你通过。",
  ["_Route22GateGuardNoBoulderbadgeText"] = "只有真正出色的\n训练家才能通过。\f你还没有\n灰色徽章！",
  ["_Route22PokemonLeagueSignText"] = "宝可梦联盟\n正门",
  ["_Route22Rival1DefeatedText"] = "唉！\n你只是走运！",
  ["_Route22Rival1VictoryText"] = "{RIVAL}：怎么？\n我有2只宝可梦，\v很奇怪吗？\f你也该多捉几只！",
  ["_Route22Rival2DefeatedText"] = "什么！？\f我只是\n一时大意！",
  ["_Route22Rival2VictoryText"] = "{RIVAL}：哈哈哈！\n{PLAYER}！这就是\v你的全力？\v你还远远比不上我，\v老兄！\f再去练练吧！\n手下败将！",
  ["_Route22RivalAfterBattleText1"] = "听说宝可梦联盟里\n有很多强劲训练家！\f我得想办法\n通过他们！\f你也别磨蹭了，\n赶快行动吧！",
  ["_Route22RivalAfterBattleText2"] = "这下活动开了！\n我已准备好挑战\v宝可梦联盟！\f{PLAYER}，你还得\n多多练习！\f不过你自己也知道！\n我走了，回头见！",
  ["_Route22RivalBeforeBattleText1"] = "{RIVAL}：嘿！\n{PLAYER}！\f你要去\n宝可梦联盟？\f省省吧！你大概\n一枚徽章都没有！\f守卫不会\n让你通过！\f话说，你的宝可梦\n变强了吗？",
  ["_Route22RivalBeforeBattleText2"] = "{RIVAL}：什么？\n{PLAYER}！没想到\v会在这里见到你！\f你要去\n宝可梦联盟？\f你也集齐了\n所有徽章？\v挺酷嘛！\f{PLAYER}，那我就先\n拿你热热身，\v再去挑战联盟！\f来吧！",
  ["_Route23GoRightAheadText"] = "\f好！请继续\n前进吧！",
  ["_Route23OhThatIsTheBadgeText"] = "只有持有\n{RAM:wNameBuffer}才能通过！\f哦！你有\n{RAM:wNameBuffer}！",
  ["_Route23VictoryRoadGateSignText"] = "冠军之路关卡\n—宝可梦联盟",
  ["_Route23YouDontHaveTheBadgeYetText"] = "只有持有\n{RAM:wNameBuffer}才能通过！\f你还没有\n{RAM:wNameBuffer}！\f想前往宝可梦联盟，\n必须先得到它！",
  ["_Route24CooltrainerF1AfterBattleText"] = "我尽力了，\n所以没有遗憾！",
  ["_Route24CooltrainerF1BattleText"] = "我是4号！\n开始累了吗？",
  ["_Route24CooltrainerF1EndBattleText"] = "我也\n输了！",
  ["_Route24CooltrainerF2AfterBattleText"] = "我尽力了，\n没有遗憾！",
  ["_Route24CooltrainerF2BattleText"] = "我是第2个！\n现在要来真的了！",
  ["_Route24CooltrainerF2EndBattleText"] = "我怎么\n会输？",
  ["_Route24CooltrainerM1DefeatedText"] = "啊！\n你很厉害！",
  ["_Route24CooltrainerM1JoinTeamRocketText"] = "对了，你想加入\n火箭队吗？\f我们是利用宝可梦\n犯罪的集团！\f想加入吗？\f确定不加入？\f来吧，加入我们！\f我叫你加入！\f好吧，看来得\n说服你！\f我会开出一个\n你无法拒绝的条件！",
  ["_Route24CooltrainerM1NoRoomText"] = "你没有\n多余空间！",
  ["_Route24CooltrainerM1ReceivedNuggetText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_Route24CooltrainerM1YouBeatOurContestText"] = "恭喜！\n你打败了我们的\v5位挑战者！",
  ["_Route24CooltrainerM1YouCouldBecomeATopLeaderText"] = "凭你的实力，\n在火箭队里\v一定能当上高层！",
  ["_Route24CooltrainerM1YouJustEarnedAPrizeText"] = "\f你刚刚赢得了\n一份豪华奖品！",
  ["_Route24CooltrainerM2AfterBattleText"] = "桥上的人太吓人了，\n所以我躲了起来！",
  ["_Route24CooltrainerM2BattleText"] = "我从草丛里\n看到了你的表现！",
  ["_Route24CooltrainerM2EndBattleText"] = "果然\n不行！",
  ["_Route24CooltrainerM3AfterBattleText"] = "我尽力了，\n没有遗憾！",
  ["_Route24CooltrainerM3BattleText"] = "好！我是5号！\n我要把你踩扁！",
  ["_Route24CooltrainerM3EndBattleText"] = "哇！\n太强了！",
  ["_Route24DamianText1"] = "我不擅长\n培育宝可梦。\f我没把小火龙\n照顾好，\v应该把它放生……\f如果你答应\n好好照顾它，\v它就是你的了。",
  ["_Route24DamianText2"] = "请好好照顾\n我的小火龙！",
  ["_Route24DamianText3"] = "哦……那我还是\n把它放生吧。",
  ["_Route24DamianText4"] = "小火龙\n过得好吗？",
  ["_Route24Youngster1AfterBattleText"] = "我尽力了，\n没有遗憾！",
  ["_Route24Youngster1BattleText"] = "三号上场！\n我可没那么好对付！",
  ["_Route24Youngster1EndBattleText"] = "哎哟！\n被打趴了！",
  ["_Route24Youngster2AfterBattleText"] = "我已经尽力了，\n毫无遗憾！",
  ["_Route24Youngster2BattleText"] = "这里是金珠桥！\n打败我们5名\v训练家，就能赢得\v超棒的奖品！\f你觉得自己\n有这个本事吗？",
  ["_Route24Youngster2EndBattleText"] = "呜哇！\n真厉害！",
  ["_Route25BillSignText"] = "海边小屋\n正辉住在这里！",
  ["_Route25CooltrainerF1AfterBattleText"] = "真希望我的男友\n也和你一样厉害！",
  ["_Route25CooltrainerF1BattleText"] = "嗨！我的男朋友\n可帅了！",
  ["_Route25CooltrainerF1EndBattleText"] = "我陷入了\n低潮！",
  ["_Route25CooltrainerF2AfterBattleText"] = "你从月见山来？\n可以把\v一只皮皮给我吗？",
  ["_Route25CooltrainerF2BattleText"] = "我的朋友有只\n可爱的宝可梦。\v真让人羡慕！",
  ["_Route25CooltrainerF2EndBattleText"] = "我已经\n没那么羡慕了！",
  ["_Route25CooltrainerMAfterBattleText"] = "算啦，我的女友\n会安慰我的。",
  ["_Route25CooltrainerMBattleText"] = "我可是很酷的。\n我还有女朋友哦！",
  ["_Route25CooltrainerMEndBattleText"] = "啊，\n可恶……",
  ["_Route25Hiker1AfterBattleText"] = "真倒霉！\n我在里面被\v超音蝠咬了。",
  ["_Route25Hiker1BattleText"] = "我刚从\n月见山下来，\v但已经准备好了！",
  ["_Route25Hiker1EndBattleText"] = "你\n很努力啊！",
  ["_Route25Hiker2AfterBattleText"] = "那位收藏家\n收藏了许多种\v稀有宝可梦。",
  ["_Route25Hiker2BattleText"] = "我要去海角拜访\n宝可梦收藏家！",
  ["_Route25Hiker2EndBattleText"] = "被你\n拿下了。",
  ["_Route25Hiker3AfterBattleText"] = "下方的小路\n是通往\v华蓝市的近路。",
  ["_Route25Hiker3BattleText"] = "你要去见正辉？\n先来\v对战吧！",
  ["_Route25Hiker3EndBattleText"] = "你\n真不简单。",
  ["_Route25Youngster1AfterBattleText"] = "每种宝可梦都有\n弱点。最好\v培育不同种类的\v宝可梦。",
  ["_Route25Youngster1BattleText"] = "本地训练家\n会来这里\v练习！",
  ["_Route25Youngster1EndBattleText"] = "你\n还挺行的。",
  ["_Route25Youngster2AfterBattleText"] = "在圣特安努号上，\n我见过来自\v世界各地的训练家。",
  ["_Route25Youngster2BattleText"] = "爸爸带我参加了\n枯叶市\v圣特安努号上的\v盛大派对！",
  ["_Route25Youngster2EndBattleText"] = "我\n没生气！",
  ["_Route25Youngster3AfterBattleText"] = "宝可梦混乱或\n睡着时，\v就把它\v替换下来！",
  ["_Route25Youngster3BattleText"] = "我就知道\n得和你对战！",
  ["_Route25Youngster3EndBattleText"] = "我也知道\n自己会输！",
  ["_Route2DiglettsCaveSignText"] = "地鼠洞穴",
  ["_Route2GateOaksAideFlashExplanationText"] = "秘传招式闪光\n可以照亮\v最黑暗的洞窟。",
  ["_Route2GateYoungsterText"] = "宝可梦学会闪光后，\n就能穿过\v岩山隧道。",
  ["_Route2SignText"] = "2号道路\n常青市—深灰市",
  ["_Route2TradeHouseScientistText"] = "昏厥的宝可梦\n无法对战，\v但还能使用\v居合斩等招式！",
  ["_Route3CooltrainerF1AfterBattleText"] = "不想对战的话，\n就不要\v盯着我看！",
  ["_Route3CooltrainerF1BattleText"] = "你刚才在看我，\n对吧？",
  ["_Route3CooltrainerF1EndBattleText"] = "你真\n过分！",
  ["_Route3CooltrainerF2AfterBattleText"] = "不让别人看到你，\n就能避开\v对战！",
  ["_Route3CooltrainerF2BattleText"] = "你刚才的眼神，\n真是\v耐人寻味！",
  ["_Route3CooltrainerF2EndBattleText"] = "对人家好一点嘛！",
  ["_Route3CooltrainerF3AfterBattleText"] = "4号道路就在\n月见山脚下。",
  ["_Route3CooltrainerF3BattleText"] = "呀！你刚才\n碰到我了吗？",
  ["_Route3CooltrainerF3EndBattleText"] = "就这样？",
  ["_Route3SignText"] = "3号道路\n前方是月见山",
  ["_Route3Text1"] = "呼……我最好\n休息一下……\v唉……\f从华蓝市过来的\n那条隧道，\v真让人累坏了！",
  ["_Route3Youngster1AfterBattleText"] = "森林以外还能找到\n其他种类的宝可梦！",
  ["_Route3Youngster1BattleText"] = "嘿！我在\n常青森林见过你！",
  ["_Route3Youngster1EndBattleText"] = "你又\n打败我了！",
  ["_Route3Youngster2AfterBattleText"] = "你把宝可梦\n存进电脑了吗？\v每个盒子能\v存放20只宝可梦！",
  ["_Route3Youngster2BattleText"] = "嗨！我喜欢短裤！\n穿着很舒服，\v也方便活动！",
  ["_Route3Youngster2EndBattleText"] = "我不\n敢相信！",
  ["_Route3Youngster3AfterBattleText"] = "电脑里的盒子\n装满后，\v只要换到\v另一个盒子！",
  ["_Route3Youngster3BattleText"] = "你是训练家吗？\n来对战吧！",
  ["_Route3Youngster3EndBattleText"] = "要是我\n有新的宝可梦，\v一定能赢！",
  ["_Route3Youngster4AfterBattleText"] = "即使在冬天，\n我也总是\v穿短裤！",
  ["_Route3Youngster4BattleText"] = "嘿！你怎么\n没穿短裤！",
  ["_Route3Youngster4EndBattleText"] = "输了！\n输了！输了！",
  ["_Route3Youngster5AfterBattleText"] = "训练过的宝可梦\n比野生的\v更强！",
  ["_Route3Youngster5BattleText"] = "来和我的\n新宝可梦对战吧！",
  ["_Route3Youngster5EndBattleText"] = "彻底\n完蛋了！",
  ["_Route4CooltrainerF1Text"] = "好痛！我被\n岩石宝可梦\v小拳石绊倒了！",
  ["_Route4CooltrainerF2AfterBattleText"] = "这里可能\n已经没有\v蘑菇了。\f我想我已经\n把它们全抓走了。",
  ["_Route4CooltrainerF2BattleText"] = "我是来抓\n蘑菇宝可梦的！",
  ["_Route4CooltrainerF2EndBattleText"] = "啊！我可爱的\n蘑菇宝可梦！",
  ["_Route4MtMoonSignText"] = "月见山\n隧道入口",
  ["_Route4SignText"] = "4号道路\n月见山—\v华蓝市",
  ["_Route5UndergroundPathSignText"] = "地下通道\n华蓝市－\v枯叶市",
  ["_Route6CooltrainerF1AfterBattleText"] = "我现在明白了，\n宝可梦并不是\v单靠计算\v数字就能理解的。",
  ["_Route6CooltrainerF1BattleText"] = "我在为爱情\n特训。别来\v烦我！",
  ["_Route6CooltrainerF1EndBattleText"] = "我的\n教科书上没写……",
  ["_Route6CooltrainerF2AfterBattleText"] = "我想变得\n更强！你的\v秘诀是什么？",
  ["_Route6CooltrainerF2BattleText"] = "我吗？好吧。\n陪你玩玩！",
  ["_Route6CooltrainerF2EndBattleText"] = "就是\n行不通！",
  ["_Route6CooltrainerM1AfterBattleText"] = "我的爱人会\n嫌弃我的。",
  ["_Route6CooltrainerM1BattleText"] = "我这是\n为了爱情。\v别管我！",
  ["_Route6CooltrainerM1EndBattleText"] = "不，\n这不可能……",
  ["_Route6CooltrainerM2AfterBattleText"] = "为了安全，\n我应该多带几只\v宝可梦。",
  ["_Route6CooltrainerM2BattleText"] = "咦？你想\n和我说话？",
  ["_Route6CooltrainerM2EndBattleText"] = "可不是\n我先动手的！",
  ["_Route6UndergroundPathSignText"] = "地下通道\n华蓝市－\v枯叶市",
  ["_Route6Youngster1AfterBattleText"] = "我喜欢虫宝可梦，\n所以要回\v常青森林了。",
  ["_Route6Youngster1BattleText"] = "这里没多少\n虫宝可梦。",
  ["_Route6Youngster1EndBattleText"] = "不！\n开玩笑吧！",
  ["_Route6Youngster2AfterBattleText"] = "是我的宝可梦\n太弱？还是\v我太差？",
  ["_Route6Youngster2BattleText"] = "我从没在\n附近见过你！\v你厉害吗？",
  ["_Route6Youngster2EndBattleText"] = "你\n太厉害了！",
  ["_Route7UndergroundPathSignText"] = "地下通道\n玉虹市－\v紫苑镇",
  ["_Route8CooltrainerF1AfterBattleText"] = "宝可梦长大后\n会变丑！\v它们不该\v进化！",
  ["_Route8CooltrainerF1BattleText"] = "我喜欢尼多兰，\n所以一直收集！",
  ["_Route8CooltrainerF1EndBattleText"] = "为什么？为什么？",
  ["_Route8CooltrainerF2AfterBattleText"] = "我觉得波波\n和小拉达\v也很可爱！",
  ["_Route8CooltrainerF2BattleText"] = "喵喵太可爱了，\n喵喵喵！",
  ["_Route8CooltrainerF2EndBattleText"] = "喵！",
  ["_Route8CooltrainerF3AfterBattleText"] = "金黄市的守卫\n不让我们通过。\v他太\v过分了！",
  ["_Route8CooltrainerF3BattleText"] = "我们这样站着\n看起来一定\v很傻！",
  ["_Route8CooltrainerF3EndBattleText"] = "看你\n干的好事！",
  ["_Route8CooltrainerF4AfterBattleText"] = "听说皮皮\n接触到月之石后\v就会\v进化。",
  ["_Route8CooltrainerF4BattleText"] = "又可爱、\n又圆又毛茸茸的\v宝可梦是什么？",
  ["_Route8CooltrainerF4EndBattleText"] = "住手！\f别再欺负\n我的皮皮了！",
  ["_Route8Gambler1AfterBattleText"] = "幸运女神今天\n没站在我这边！",
  ["_Route8Gambler1BattleText"] = "好！来\n掷骰子吧！",
  ["_Route8Gambler1EndBattleText"] = "可恶！\n差一点就赢了！",
  ["_Route8Gambler2AfterBattleText"] = "赌博和宝可梦\n就像吃花生一样，\v一吃就停不下来！",
  ["_Route8Gambler2BattleText"] = "我是四处漂泊的\n赌徒！",
  ["_Route8Gambler2EndBattleText"] = "没中\n大奖！",
  ["_Route8SuperNerd1AfterBattleText"] = "这方面我不行，\n但学习可好多了！",
  ["_Route8SuperNerd1BattleText"] = "你很会训练宝可梦，\n但化学学得怎么样？",
  ["_Route8SuperNerd1EndBattleText"] = "哎哟！\n彻底熔毁！",
  ["_Route8SuperNerd2AfterBattleText"] = "先派臭泥\n然后……\v……然后……",
  ["_Route8SuperNerd2BattleText"] = "想赢就得\n讲究策略！",
  ["_Route8SuperNerd2EndBattleText"] = "这\n不合逻辑！",
  ["_Route8SuperNerd3AfterBattleText"] = "因为金黄市的\n城门，我们被\v困在这里了。",
  ["_Route8SuperNerd3BattleText"] = "上学很有趣，\n宝可梦也一样。",
  ["_Route8SuperNerd3EndBattleText"] = "我还是\n专心上学吧。",
  ["_Route8UndergroundSignText"] = "地下通道\n玉虹市－\v紫苑镇",
  ["_Route9AJAfterBattleText"] = "我要用穿山鼠\n重新开始\v百连胜。",
  ["_Route9AJBattleText"] = "我的目标是成为\n最强的训练家！",
  ["_Route9AJEndBattleText"] = "我的\n穿山鼠输了？",
  ["_Route9CooltrainerF1AfterBattleText"] = "要通过前面的\n黑暗隧道，你\v需要光亮。",
  ["_Route9CooltrainerF1BattleText"] = "你带着宝可梦！\n你是我的\v对手了！",
  ["_Route9CooltrainerF1EndBattleText"] = "你\n骗了我！",
  ["_Route9CooltrainerF2AfterBattleText"] = "你显然\n很有天分！祝你\v好运！",
  ["_Route9CooltrainerF2BattleText"] = "你可别\n小看我！",
  ["_Route9CooltrainerF2EndBattleText"] = "不！\n你太强了！",
  ["_Route9CooltrainerM2AfterBattleText"] = "你也要去\n岩山隧道吗？",
  ["_Route9CooltrainerM2BattleText"] = "我要穿过\n岩山隧道去\v紫苑镇……",
  ["_Route9CooltrainerM2EndBattleText"] = "完全\n比不过！",
  ["_Route9Hiker1AfterBattleText"] = "你敢站出来\n跟我较量，\v很有胆量嘛！",
  ["_Route9Hiker1BattleText"] = "哇哈哈！\n太好了！我正\v无聊呢！",
  ["_Route9Hiker1EndBattleText"] = "继续\n来啊！\f等等，我已经\n没有宝可梦了！",
  ["_Route9Hiker2AfterBattleText"] = "哈哈哈！小孩子\n就该坚强！",
  ["_Route9Hiker2BattleText"] = "哈哈哈！\n你还挺\v硬气的嘛！",
  ["_Route9Hiker2EndBattleText"] = "什么\n情况？",
  ["_Route9Hiker3AfterBattleText"] = "哈哈哈哈！\n我们这些硬汉\v总是笑口常开！",
  ["_Route9Hiker3BattleText"] = "哈哈哈哈！\n来吧，小子！",
  ["_Route9Hiker3EndBattleText"] = "哈哈哈哈！\n你堂堂正正赢了我！",
  ["_Route9SignText"] = "9号道路\n华蓝市－\v岩山隧道",
  ["_Route9Youngster1AfterBattleText"] = "想变得更强，\n不能只收集\v虫宝可梦……",
  ["_Route9Youngster1BattleText"] = "我每天都早起，\n从虫蛹阶段开始\v培育宝可梦！",
  ["_Route9Youngster1EndBattleText"] = "什么？\f我的时间\n全白费了！",
  ["_Route9Youngster2AfterBattleText"] = "如果你不喜欢\n虫宝可梦，\v就别来烦我！",
  ["_Route9Youngster2BattleText"] = "上吧，我的\n超级虫宝可梦！",
  ["_Route9Youngster2EndBattleText"] = "我的\n虫宝可梦……",
  ["_RunAwayText"] = "快逃！",
  ["_SSAnne1FRoomsCooltrainerFAfterBattleText"] = "你伤害了我那些\n来自世界各地的\v可怜宝可梦！\f我要求你带它们去\n宝可梦中心\v治疗！",
  ["_SSAnne1FRoomsCooltrainerFBattleText"] = "我从\n世界各地收集了\v这些宝可梦！",
  ["_SSAnne1FRoomsCooltrainerFEndBattleText"] = "不会吧！\n我可是走遍世界\v才找到它们！",
  ["_SSAnne1FRoomsGentleman1AfterBattleText"] = "对朋友\n要友善！",
  ["_SSAnne1FRoomsGentleman1BattleText"] = "我的旅途\n总是独自一人！\f宝可梦是我\n唯一的朋友！",
  ["_SSAnne1FRoomsGentleman1EndBattleText"] = "我的……\n朋友们……",
  ["_SSAnne1FRoomsGentleman2AfterBattleText"] = "我想一个人\n静静！出去！",
  ["_SSAnne1FRoomsGentleman2BattleText"] = "你这小鬼！竟敢\n闯进来！",
  ["_SSAnne1FRoomsGentleman2EndBattleText"] = "哼！\n没礼貌的小孩！",
  ["_SSAnne1FRoomsGentleman3Text"] = "嘘！我是国际\n警察的特工！\f我正在追踪\n火箭队！",
  ["_SSAnne1FRoomsGirl1Text"] = "服务员，请给我\n一份樱桃派！",
  ["_SSAnne1FRoomsGirl2Text"] = "我们正在\n环游世界。",
  ["_SSAnne1FRoomsLittleGirlText"] = "我旅行时总带着\n胖可丁！",
  ["_SSAnne1FRoomsMiddleAgedManText"] = "邮轮旅行既优雅\n又舒适！",
  ["_SSAnne1FRoomsWigglytuffText"] = "胖可丁：噗噗\n噗呜！",
  ["_SSAnne1FRoomsYoungsterAfterBattleText"] = "和我做\n朋友，好吗？\f这样我们就能\n交换宝可梦了！",
  ["_SSAnne1FRoomsYoungsterBattleText"] = "我喜欢宝可梦！\n你呢？",
  ["_SSAnne1FRoomsYoungsterEndBattleText"] = "哇！\n你好厉害！",
  ["_SSAnne1FSailorText"] = "乘客们\n坐不住了！\f那些无聊的人\n可能会向你\v发起挑战！",
  ["_SSAnne1FWaiterText"] = "你好！\n我是本船的\v服务员！\f无论您想要\n什么，我都很乐意\v为您服务！\f啊！您是个\n沉默的硬汉！",
  ["_SSAnne2FRivalCutMasterText"] = "{RIVAL}：我听说\n船上有位\v居合斩大师。\f但他只是个\n晕船的老头！\f不过居合斩本身\n真的很好用！\f你应该去见见\n他！回头见！",
  ["_SSAnne2FRivalDefeatedText"] = "哼！\f至少你有在\n好好培育\v宝可梦！",
  ["_SSAnne2FRivalText"] = "{RIVAL}：你好！\n{PLAYER}！\f没想到会在\n这里见到你！\f{PLAYER}，你真的\n收到邀请了吗？\f你的宝可梦图鉴\n进展如何？\f我已经抓到\n40种了，老兄！\f各种各样的宝可梦\n到处都有！\f多在草丛里\n找找吧！",
  ["_SSAnne2FRivalVictoryText"] = "{PLAYER}！你怎么\n晕船了？\f振作一点，老兄！",
  ["_SSAnne2FRoomsBeautyText"] = "听说很多人\n都会晕船！",
  ["_SSAnne2FRoomsBrunetteGirlText"] = "船长看起来\n脸色苍白，病得\v很严重！",
  ["_SSAnne2FRoomsCooltrainerFAfterBattleText"] = "哎呀，我好喜欢\n你强大的宝可梦！",
  ["_SSAnne2FRoomsCooltrainerFBattleText"] = "我在派对上\n没见过你。",
  ["_SSAnne2FRoomsCooltrainerFEndBattleText"] = "别\n太拼命！",
  ["_SSAnne2FRoomsFisherAfterBattleText"] = "派对？\f邮轮上的派对\n现在应该\v结束了。",
  ["_SSAnne2FRoomsFisherBattleText"] = "看看我\n钓到了什么！",
  ["_SSAnne2FRoomsFisherEndBattleText"] = "我已经\n用光了！",
  ["_SSAnne2FRoomsGentleman1AfterBattleText"] = "要是15年前，\n我一定能赢！",
  ["_SSAnne2FRoomsGentleman1BattleText"] = "与年轻人切磋\n能让我\v保持年轻。",
  ["_SSAnne2FRoomsGentleman1EndBattleText"] = "打得\n真好！啊，我又\v感觉年轻了！",
  ["_SSAnne2FRoomsGentleman2AfterBattleText"] = "我喜欢强大\n又稀有的宝可梦。",
  ["_SSAnne2FRoomsGentleman2BattleText"] = "你喜欢哪种，\n强大的还是\v稀有的宝可梦？",
  ["_SSAnne2FRoomsGentleman2EndBattleText"] = "我必须\n向你致敬！",
  ["_SSAnne2FRoomsGentleman3Text"] = "我走遍各地，\n从没见过\v像这样睡觉的\v宝可梦！\f它大概\n长这样！",
  ["_SSAnne2FRoomsGentleman4Text"] = "嗯，我见过\n有些宝可梦\v载着人们\v渡过水面！",
  ["_SSAnne2FRoomsGentleman5Text"] = "你去过\n浅红市的野生原野区\v吗？\f那里有很多\n稀有的宝可梦！！",
  ["_SSAnne2FRoomsGrampsText"] = "宝可梦可以用居合斩\n砍倒小树。",
  ["_SSAnne2FRoomsLittleBoyText"] = "我和爸爸都觉得\n野生原野区\v超棒！",
  ["_SSAnne2FWaiterText"] = "这艘船是\n训练家专用的\v豪华邮轮！\f每到一个港口，\n我们都会为\v受邀训练家办派对！",
  ["_SSAnne3FSailorText"] = "我们的船长是\n剑术大师！\f他甚至会教\n宝可梦使用居合斩！",
  ["_SSAnneB1FRoomsFisherAfterBattleText"] = "我本来还想\n让你当我的\v助手呢！",
  ["_SSAnneB1FRoomsFisherBattleText"] = "陌生人，你好！\n停下来聊聊！\f我的宝可梦\n全都来自大海！",
  ["_SSAnneB1FRoomsFisherEndBattleText"] = "可恶！\n让它从我手里\v溜走了！",
  ["_SSAnneB1FRoomsMachokeText"] = "豪力：咕哦！\n咕咕哦！",
  ["_SSAnneB1FRoomsSailor1AfterBattleText"] = "哈哈！想成为\n水手吗，伙计？",
  ["_SSAnneB1FRoomsSailor1BattleText"] = "你知道水手们\n常说的，\v打架是家常便饭！",
  ["_SSAnneB1FRoomsSailor1EndBattleText"] = "没错！\n打得漂亮，伙计！",
  ["_SSAnneB1FRoomsSailor2AfterBattleText"] = "你在枯叶市\n见到\v钓鱼大师了吗？",
  ["_SSAnneB1FRoomsSailor2BattleText"] = "我的水手荣誉\n就赌在这一战！",
  ["_SSAnneB1FRoomsSailor2EndBattleText"] = "你的\n气势击沉了我！",
  ["_SSAnneB1FRoomsSailor3AfterBattleText"] = "我们所有宝可梦\n都是出海时\v捕到的！",
  ["_SSAnneB1FRoomsSailor3BattleText"] = "我们水手也有\n宝可梦！",
  ["_SSAnneB1FRoomsSailor3EndBattleText"] = "好吧，\n你还不赖。",
  ["_SSAnneB1FRoomsSailor4AfterBattleText"] = "海洋宝可梦生活在\n深水中。\v你需要钓竿！",
  ["_SSAnneB1FRoomsSailor4BattleText"] = "我喜欢像你这样\n有冲劲的小孩！",
  ["_SSAnneB1FRoomsSailor4EndBattleText"] = "啊！\n输了！",
  ["_SSAnneB1FRoomsSailor5AfterBattleText"] = "水母有时\n会漂进\v船里。",
  ["_SSAnneB1FRoomsSailor5BattleText"] = "伙计，输了就\n罚你走跳板！",
  ["_SSAnneB1FRoomsSailor5EndBattleText"] = "啊！\n居然输给小孩！",
  ["_SSAnneB1FRoomsSuperNerdText"] = "我的伙伴豪力\n超级强壮！\f它使出的\n怪力足以推动\v大岩石！",
  ["_SSAnneBowCooltrainerMText"] = "呜……我不舒服。\f我出来透透\n气。",
  ["_SSAnneBowSailor1Text"] = "擦洗甲板\n可是苦差事！",
  ["_SSAnneBowSailor2AfterBattleText"] = "你觉得一共有\n多少种宝可梦？",
  ["_SSAnneBowSailor2BattleText"] = "嘿，伙计！\f来跳段\n小舞吧！",
  ["_SSAnneBowSailor2EndBattleText"] = "你\n真了不起！",
  ["_SSAnneBowSailor3AfterBattleText"] = "我老爸说\n宝可梦有100种。\v我觉得远不止\v这么多。",
  ["_SSAnneBowSailor3BattleText"] = "哟呵！\n你晕船了吗？",
  ["_SSAnneBowSailor3EndBattleText"] = "我只是\n大意了！",
  ["_SSAnneBowSuperNerdText"] = "派对结束了。\n船很快就会\v启航。",
  ["_SSAnneCaptainsRoomCaptainHM01NoRoomText"] = "糟了！你没有\n空间装这个！",
  ["_SSAnneCaptainsRoomCaptainIFeelMuchBetterText"] = "船长：呼！\n谢谢你！我\v好多了！\f你想看我的\n居合斩技巧吗？\f要不是身体不适，\n我就能演示……\f对了！这个\n送给你！\f让宝可梦学会后，\n你随时都能\v看到它施展\v居合斩！",
  ["_SSAnneCaptainsRoomCaptainNotSickAnymoreText"] = "船长：呼！\f我已经不晕了，\n也该出发了。",
  ["_SSAnneCaptainsRoomCaptainReceivedHM01Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_SSAnneCaptainsRoomRubCaptainsBackText"] = "船长：呜呃……\n我好难受……\v呃！晕船了……\f{PLAYER}帮\n船长拍了拍\v后背！\f拍拍……\n拍拍……",
  ["_SSAnneCaptainsRoomSeasickBookText"] = "战胜晕船的\n方法……\v船长正在\v读这本书！",
  ["_SSAnneCaptainsRoomTrashText"] = "呕！真不该\n往里看！",
  ["_SSAnneKitchenCook1Text"] = "你，小家伙！\n这里正忙！\v别挡路！",
  ["_SSAnneKitchenCook2Text"] = "我在垃圾桶里\n看到一个奇怪的球。",
  ["_SSAnneKitchenCook3Text"] = "忙得我\n头都晕了！",
  ["_SSAnneKitchenCook4Text"] = "哼哼哼～\n哼……\f我每天都要\n削土豆！\v哼哼……",
  ["_SSAnneKitchenCook5Text"] = "你听说过\n卡比兽吗？\f它除了吃\n就是睡！",
  ["_SSAnneKitchenCook6Text"] = "抽泣……吸鼻子……\f我只能\n剥洋葱……\v呜呜……",
  ["_SSAnneKitchenCook7MainCourseIsText"] = "咳咳！没错，\n我就是主厨！\f今天的主菜是",
  ["_SSTicketNoRoomText"] = "东西太多了，\n老兄！",
  ["_SSTicketReceivedText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_SafariZoneAngryText"] = "野生的{RAM:wEnemyMonNick}\n生气了！",
  ["_SafariZoneCenterRestHouseGirlText"] = "莎拉：我的男朋友\n艾瑞克去哪了？",
  ["_SafariZoneCenterRestHouseScientistText"] = "我要捕捉宝可梦\n带回家当礼物！",
  ["_SafariZoneCenterRestHouseSignText"] = "休息屋",
  ["_SafariZoneCenterTrainerTipsSignText"] = "训练家须知\f按下START键\n可查看\v剩余时间！",
  ["_SafariZoneEastRestHouseRockerText"] = "我抓到\n吉利蛋了！\f这下所有辛苦\n都值得了！",
  ["_SafariZoneEastRestHouseScientistText"] = "你抓了多少只？\n这活儿累得我\v筋疲力尽！",
  ["_SafariZoneEastRestHouseSignText"] = "休息屋",
  ["_SafariZoneEastRestHouseSilphWorkerMText"] = "呼！玩得太累了！",
  ["_SafariZoneEastSignText"] = "中央区\n北：2区",
  ["_SafariZoneEastTrainerTipsText"] = "训练家须知\f剩余时间只会在\n走动时减少！",
  ["_SafariZoneEatingText"] = "野生的{RAM:wEnemyMonNick}\n正在进食！",
  ["_SafariZoneGateSafariZoneWorker1CallYouOnThePAText"] = "\f时间或狩猎球\n用完时，我们会\v通过广播\v通知你！",
  ["_SafariZoneGateSafariZoneWorker1GoodHaulComeAgainText"] = "收获不错吗？\n欢迎再来！",
  ["_SafariZoneGateSafariZoneWorker1GoodLuckText"] = "祝你好运！",
  ["_SafariZoneGateSafariZoneWorker1LeavingEarlyText"] = "要提前离开吗？",
  ["_SafariZoneGateSafariZoneWorker1NotEnoughMoneyText"] = "哎呀！钱不够！",
  ["_SafariZoneGateSafariZoneWorker1PleaseComeAgainText"] = "好！欢迎\n下次再来！",
  ["_SafariZoneGateSafariZoneWorker1ReturnSafariBallsText"] = "请归还\n剩余的狩猎球。",
  ["_SafariZoneGateSafariZoneWorker1Text"] = "欢迎来到\n野生原野区！",
  ["_SafariZoneGateSafariZoneWorker1ThatllBe500PleaseText"] = "一共是¥{NUM:wPriceTemp, $c3}，\n谢谢！\f这里只能使用\n特殊的精灵球。\f{PLAYER}获得了\n30个狩猎球！",
  ["_SafariZoneGateSafariZoneWorker1WouldYouLikeToJoinText"] = "只要¥500，\n就能在园内\v随意捕捉宝可梦！\f要参加\n狩猎吗？",
  ["_SafariZoneGateSafariZoneWorker2FirstTimeHereText"] = "你好！第一次\n来这里吗？",
  ["_SafariZoneGateSafariZoneWorker2SafariZoneExplanationText"] = "野生原野区\n分为4个区域。\f每个区域都有\n不同的宝可梦。\v用狩猎球\v捕捉它们吧！\f时间或狩猎球\n用完时，游戏就\v结束了！\f进去前，\n先启用一个空的\v宝可梦盒子，\v好给新宝可梦\v留出空间！",
  ["_SafariZoneGateSafariZoneWorker2YoureARegularHereText"] = "抱歉，原来你是\n这里的常客！",
  ["_SafariZoneLowCostText1"] = "\f好吧，把你有的\n钱都给我就行。",
  ["_SafariZoneLowCostText2"] = "但我不能把\n30个狩猎球全给你。",
  ["_SafariZoneLowCostText3"] = "\f你还真执着，\n对吧？\f好吧，让你免费\n进去，但\v仅此一次！",
  ["_SafariZoneLowCostText5"] = "抱歉，必须付费\n才能入园。",
  ["_SafariZoneLowCostText6"] = "不付钱就\n不能入园！",
  ["_SafariZoneLowCostText7"] = "说了，没钱\n就不能进！",
  ["_SafariZoneLowCostText8"] = "看清我的嘴：不行！\n明白吗？",
  ["_SafariZoneNorthRestHouseGentlemanText"] = "我的伊布进化成了\n火伊布！\f但朋友的伊布\n变成了\v水伊布！\v为什么呢？",
  ["_SafariZoneNorthRestHouseSafariZoneWorkerText"] = "前往野生原野区\n最深处，就能\v赢得奖品！",
  ["_SafariZoneNorthRestHouseScientistText"] = "你可以带走\n在地上找到的\v任何道具。\f但如果想一次\n全拿到，时间会\v不够用！",
  ["_SafariZoneNorthRestHouseSignText"] = "休息屋",
  ["_SafariZoneNorthSignText"] = "2区",
  ["_SafariZoneNorthTrainerTips1Text"] = "训练家须知\f秘密小屋\n就在前方！",
  ["_SafariZoneNorthTrainerTips2Text"] = "训练家须知\f宝可梦会藏在\n高高的草丛里！\f在草地间\n曲折前进，就能\v把它们赶出来。",
  ["_SafariZoneNorthTrainerTips3Text"] = "训练家须知\f找到秘密小屋，\n免费赢取秘传学习器！",
  ["_SafariZoneSecretHouseFishingGuruHM03ExplanationText"] = "秘传学习器03是\n冲浪！\f宝可梦将能载你\n渡过水面！\f而且它不会\n用完！可以\v反复使用！\f能赢得这份\n超棒的奖品，你\v真是太幸运了！",
  ["_SafariZoneSecretHouseFishingGuruHM03NoRoomText"] = "你没有空间\n装这份\v超棒的奖品！",
  ["_SafariZoneSecretHouseFishingGuruReceivedHM03Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_SafariZoneSecretHouseFishingGuruYouHaveWonText"] = "啊！终于来了！\f你是第一个\n抵达秘密小屋的人！\f我还担心\n没人能赢得\v我们的活动奖品。\f恭喜！\n你获胜了！",
  ["_SafariZoneWestFindWardensTeethSignText"] = "寻物启事\f请寻找\n园长丢失的\v金假牙。\v它们就在\v附近某处。\f必有酬谢！\n联系人：园长",
  ["_SafariZoneWestRestHouseCooltrainerMText"] = "使用诱饵会\n让宝可梦\v更容易捕捉。",
  ["_SafariZoneWestRestHouseScientistText"] = "向宝可梦扔石块\n可能会让它们\v逃跑，\v但也会变得\v更容易捕捉。",
  ["_SafariZoneWestRestHouseSignText"] = "休息屋",
  ["_SafariZoneWestRestHouseSilphWorkerFText"] = "我走了很远，\n却没见到任何\v想要的宝可梦。",
  ["_SafariZoneWestSignText"] = "3区\n东：中央区",
  ["_SafariZoneWestTrainerTipsText"] = "训练家须知\f区域探索活动！\f寻找\n秘密小屋！",
  ["_SaffronCityFightingDojoSignText"] = "格斗道场",
  ["_SaffronCityGentlemanText"] = "我看到西尔佛公司的\n新闻后，就骑着\v大比鸟飞来了。\f已经结束了？\n我错过这场大新闻了。",
  ["_SaffronCityGymSignText"] = "金黄市\n宝可梦道馆\v馆主：娜姿\f超能力宝可梦\n大师！",
  ["_SaffronCityMrPsychicsHouseSignText"] = "超能力大叔的\n家",
  ["_SaffronCityPidgeotText"] = "大比鸟：比比哔！",
  ["_SaffronCityPokecenterGuyText1"] = "要是四天王\n能来痛扁\v火箭队就好了！",
  ["_SaffronCityPokecenterGuyText2"] = "火箭队逃跑了！\n我们又能安全地\v出门了！\v太好了！",
  ["_SaffronCityRockerText"] = "我看见火箭队\n老大逃出了\v西尔佛公司的大楼。",
  ["_SaffronCityRocket1Text"] = "你想干什么？\n滚开！",
  ["_SaffronCityRocket2Text"] = "老大说他要\n占领这座城市！",
  ["_SaffronCityRocket3Text"] = "别挡路！",
  ["_SaffronCityRocket4Text"] = "金黄市\n属于火箭队！",
  ["_SaffronCityRocket5Text"] = "作恶让我\n充满活力！",
  ["_SaffronCityRocket6Text"] = "好痛！走路\n看着点！",
  ["_SaffronCityRocket7Text"] = "控制西尔佛公司后，\n我们就能利用\v全世界的\v宝可梦！",
  ["_SaffronCityRocket8Text"] = "我是保安。\f可疑的小孩\n不得入内！",
  ["_SaffronCityRocket9Text"] = "……\n呼噜……\f哈！他睡着了！",
  ["_SaffronCityScientistText"] = "你独自打败了\n火箭队？\v太厉害了！",
  ["_SaffronCitySignText"] = "金黄市\n金光闪耀的\v商业之都",
  ["_SaffronCitySilphCoLatestProductSignText"] = "西尔佛公司的\n最新产品！\f发售日期\n尚未决定……",
  ["_SaffronCitySilphCoSignText"] = "西尔佛公司\n办公大楼",
  ["_SaffronCitySilphWorkerFText"] = "人们现在应该会\n纷纷回到\v金黄市。",
  ["_SaffronCitySilphWorkerMText"] = "太好了！火箭队\n走了！\v又能安全地\v出门了！",
  ["_SaffronCityTrainerTips1Text"] = "训练家须知\f万灵药能治愈\n睡眠、灼伤等\v所有异常状态。\f虽然贵一点，\n但更加方便。",
  ["_SaffronCityTrainerTips2Text"] = "训练家须知\f新款超级球\n提升了捕获率。\f遇到难抓的\n宝可梦就试试吧。",
  ["_SaffronGateGuardGeeImThirstyText"] = "我正在执勤。\n不过，真渴啊！\f喂，等一下，\n这条路封了。",
  ["_SaffronGateGuardImParchedText"] = "哇！\n渴死我了！\v……\v咦？这杯饮料\v给我吗？\v太感谢了！",
  ["_SaffronGateGuardThanksForTheDrinkText"] = "你好，谢谢你的\n清凉饮料！",
  ["_SaffronGateGuardYouCanGoOnThroughText"] = "\f……\n咕嘟咕嘟……\v……\v咕噜……\v你想去金黄市的话……\v……\v可以通过了。\v我会把饮料\v分给其他守卫！",
  ["_SaffronGymChanneler1AfterBattleText"] = "实力相当时，\n意志更坚定的\v一方会获胜！\f想打败娜姿，\n就一心想着\v胜利吧！",
  ["_SaffronGymChanneler1BattleText"] = "娜姿比我年轻，\n但我很尊敬她！",
  ["_SaffronGymChanneler1EndBattleText"] = "还\n不够好！",
  ["_SaffronGymChanneler2AfterBattleText"] = "我必须教给\n宝可梦更好的\v招式！",
  ["_SaffronGymChanneler2BattleText"] = "宝可梦会\n长得像训练家。\f这么说，你的宝可梦\n一定很强！",
  ["_SaffronGymChanneler2EndBattleText"] = "我就\n知道！",
  ["_SaffronGymChanneler3AfterBattleText"] = "我早就知道\n这会发生。",
  ["_SaffronGymChanneler3BattleText"] = "你我双方的\n宝可梦来\v对战吧！",
  ["_SaffronGymChanneler3EndBattleText"] = "结果\n还是输了！",
  ["_SaffronGymGuideBeatSabrinaText"] = "超能力吗？\f要是我也会，\n就能靠老虎机\v大赚一笔！",
  ["_SaffronGymGuideChampInMakingText"] = "哟！未来的\n冠军！\f娜姿的宝可梦\n用的是超能力，\v不是蛮力！\f格斗属性宝可梦\n害怕超能力属性！\f还没来得及\n出拳就会被\v打得落花流水！",
  ["_SaffronGymSabrinaMarshBadgeInfoText"] = "金色徽章能让\n70级以下的宝可梦\v听从指挥！\f更强的宝可梦\n会变得难以驾驭，\v在对战中\v无视命令！\f别把宝可梦的等级\n练得太高！\f等等，请带上\n这个招式学习器！",
  ["_SaffronGymSabrinaPostBattleAdviceText"] = "每个人都有\n超能力！\v只是人们自己\v没意识到！",
  ["_SaffronGymSabrinaReceivedMarshBadgeText"] = "我……\n太震惊了！\v不过，输了就是\v输了。\f我承认自己\n还不够努力，\v所以没能获胜！\f金色徽章\n属于你了！",
  ["_SaffronGymSabrinaReceivedTM46Text"] = "{PLAYER}获得了\n招式学习器46！",
  ["_SaffronGymSabrinaTM46NoRoomText"] = "背包装满了\n其他道具！",
  ["_SaffronGymSabrinaText"] = "我预见到了\n你的到来！\f我从小就有\n超能力。\f起初，我学会用\n念力弯曲汤匙。\f我不喜欢对战，\n但既然你想，\v就让你见识一下\v我的力量！",
  ["_SaffronGymYoungster1AfterBattleText"] = "超能力属性宝可梦\n只害怕虫属性！",
  ["_SaffronGymYoungster1BattleText"] = "你害怕我们\n看不见的力量吗？",
  ["_SaffronGymYoungster1EndBattleText"] = "我从没\n预见到这一幕！",
  ["_SaffronGymYoungster2AfterBattleText"] = "娜姿刚刚打败了\n隔壁的\v空手道王！",
  ["_SaffronGymYoungster2BattleText"] = "你知道\n光靠力量是不够的！",
  ["_SaffronGymYoungster2EndBattleText"] = "真不敢\n相信！",
  ["_SaffronGymYoungster3AfterBattleText"] = "以前金黄市\n有两座宝可梦道馆。\f隔壁的格斗道场\n被我们痛打后，\v就失去了\v道馆资格！",
  ["_SaffronGymYoungster3BattleText"] = "娜姿虽然年轻，\n却也是我们的\v馆主！\f你没那么容易\n见到她！",
  ["_SaffronGymYoungster3EndBattleText"] = "我没法\n集中精神了！",
  ["_SaffronGymYoungster4AfterBattleText"] = "没错！我用\n心灵感应读了\v你的心思！",
  ["_SaffronGymYoungster4BattleText"] = "金黄市宝可梦道馆\n以超能力者闻名！\f你想见\n娜姿！\v我说中了吧！",
  ["_SaffronGymYoungster4EndBattleText"] = "啊啊啊！",
  ["_SaffronMartCooltrainerFText"] = "活力碎片很贵，\n但能让失去战斗能力的\v宝可梦恢复！",
  ["_SaffronMartSuperNerdText"] = "黄金喷雾比\n白银喷雾持续更久，\v能让较弱的宝可梦\v远离你！",
  ["_SaffronPidgeyHouseBrunetteGirlText"] = "谢谢你写信。\n希望很快能\v见到你！\f喂！别偷看\n我的信！",
  ["_SaffronPidgeyHousePaperText"] = "我收到了一瓶\nPP提升剂作为礼物。\f它能提高招式的\nPP！",
  ["_SaffronPidgeyHousePidgeyText"] = "波波：咕噜咕！",
  ["_SaffronPidgeyHouseYoungsterText"] = "模仿少女很可爱！\n我要送她一个\v皮皮玩偶！",
  ["_SaffronPokecenterBeautyText"] = "不同种类的宝可梦\n成长速度也不同。",
  ["_SaffronPokecenterGentlemanText"] = "西尔佛公司非常\n有名，所以才\v引来了\v火箭队！",
  ["_SandshrewDexEntry"] = "身体十分干燥。\n夜晚气温下降时，\n据说它的皮肤\f会凝结出\n细小的露珠",
  ["_SandslashDexEntry"] = "擅长用爪子\n劈开敌人。\n就算爪子折断，\f也能在一天内\n开始重新生长",
  ["_SaveOptionText"] = "记录选项在\n菜单画面中。",
  ["_SavingEnergyText"] = "{USER}\n正在积蓄力量！",
  ["_SavingText"] = "正在记录……",
  ["_ScaredText"] = "{RAM:wBattleMonNick}怕得\n无法行动！",
  ["_ScytherDexEntry"] = "从高草丛中\n一跃而出，用镰刀\n切开猎物。\f它的动作看起来\n就像忍者一样",
  ["_SeadraDexEntry"] = "触碰背鳍\n会让人麻痹。\n睡觉时会用尾巴\f勾住珊瑚，\n固定身体",
  ["_SeafoamIslandsB4FArticunoBattleText"] = "嘎嗷！",
  ["_SeafoamIslandsB4FBouldersSignText"] = "巨石也许能\n改变水流！",
  ["_SeafoamIslandsB4FDangerSignText"] = "危险\n水流湍急！",
  ["_SeakingDexEntry"] = "雄性会用头上的角\n凿开溪流中的\n岩石，\f筑造巢穴",
  ["_SeelDexEntry"] = "喜欢严寒的\n环境。\n它尤其爱在\f华氏14度左右的\n冰冷水域中游泳",
  ["_SentToBoxText"] = "没有空间\n容纳更多宝可梦！\v{RAM:wBoxMonNicks}被\v传送到了电脑的\v宝可梦盒子\n{RAM:wStringBuffer}！",
  ["_ShallWeHealYourPokemonText"] = "要为你的\n宝可梦治疗吗？",
  ["_ShellderDexEntry"] = "外壳能承受\n任何攻击。\n然而外壳打开时，\f柔软的身体\n就会暴露",
  ["_ShroudedInMistText"] = "{USER}\n被白雾笼罩了！",
  ["_SilphCo10FGiovanniILostAgainText"] = "啊！！\n我又输了！？",
  ["_SilphCo10FRocketAfterBattleText"] = "干得不错，\n但董事长室还在\v上一层！",
  ["_SilphCo10FRocketBattleText"] = "欢迎来到10楼！\n你能来真是太好了！",
  ["_SilphCo10FRocketEndBattleText"] = "我……\n惊呆了！",
  ["_SilphCo10FScientistAfterBattleText"] = "打败我就\n满足了吗？\v那就回家吧！",
  ["_SilphCo10FScientistBattleText"] = "你这无聊的\n把戏该结束了！",
  ["_SilphCo10FScientistEndBattleText"] = "没有\n续关机会了！",
  ["_SilphCo10FSilphWorkerFImScaredText"] = "哇啊啊！\n我好害怕！",
  ["_SilphCo10FSilphWorkerFQuietAboutMyCryingText"] = "请别告诉别人\n我哭过！",
  ["_SilphCo11FBeautyText"] = "秘书：谢谢你\n救了大家！\f我们很钦佩\n你的勇气。",
  ["_SilphCo11FGiovanniText"] = "啊，{PLAYER}！\n我们又见面了！\f我正和董事长\n商谈一项\v重要的生意。\f小孩子别来管\n大人的事……\f否则就让你\n尝尝苦头！",
  ["_SilphCo11FGiovanniYouRuinedOurPlansText"] = "可恶！\n你毁了我们\v对西尔佛公司的计划！\f但火箭队\n永远不会倒下！\f{PLAYER}！永远\n别忘了，所有宝可梦\v都是为火箭队而生的！\f我得走了，\n但我还会回来！",
  ["_SilphCo11FRocket2AfterBattleText"] = "小心点，\n老大喜欢强悍的\v宝可梦！",
  ["_SilphCo11FRocket2BattleText"] = "站住！你和\n老大有预约吗？",
  ["_SilphCo11FRocket2EndBattleText"] = "呃啊！\n被打垮了！",
  ["_SilphCo11FSilphPresidentMasterBallDescriptionText"] = "董事长：这个\n哪里都买不到！\f这是我们秘密研发的\n大师球原型！\f无论什么宝可梦\n都一定能抓住！\f不过使用时\n请保密。",
  ["_SilphCo11FSilphPresidentNoRoomText"] = "你没有\n空间装它。",
  ["_SilphCo11FSilphPresidentReceivedMasterBallText"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_SilphCo11FSilphPresidentText"] = "董事长：谢谢你\n拯救西尔佛公司！\f在我们最危急时\n你救了大家，\v我永远不会忘记！\f我必须用某种方式\n感谢你！\f我很富有，\n什么都能送你！\f这个也许\n很合适！",
  ["_SilphCo1FLinkReceptionistText"] = "欢迎！\f董事长在\n11楼的董事长室！",
  ["_SilphCo2FRocket1AfterBattleText"] = "菱形地砖\n是传送装置！\f那是高科技的\n输送器！",
  ["_SilphCo2FRocket1BattleText"] = "这里不准\n小孩进入！",
  ["_SilphCo2FRocket1EndBattleText"] = "真强！",
  ["_SilphCo2FRocket2AfterBattleText"] = "西尔佛公司将\n并入火箭队！",
  ["_SilphCo2FRocket2BattleText"] = "喂，小鬼！你在\n这里做什么？",
  ["_SilphCo2FRocket2EndBattleText"] = "我搞砸了！",
  ["_SilphCo2FScientist1AfterBattleText"] = "我同时为\n西尔佛公司和\v火箭队工作！",
  ["_SilphCo2FScientist1BattleText"] = "救命！我是\n西尔佛公司的员工。",
  ["_SilphCo2FScientist1EndBattleText"] = "你怎么\n知道我是\v火箭队的人？",
  ["_SilphCo2FScientist2AfterBattleText"] = "你能破解\n这里的迷宫吗？",
  ["_SilphCo2FScientist2BattleText"] = "这里禁止进入！\n回家去！",
  ["_SilphCo2FScientist2EndBattleText"] = "你\n很厉害。",
  ["_SilphCo2FSilphWorkerFReceivedTM36Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_SilphCo2FSilphWorkerFTM36ExplanationText"] = "招式学习器36是\n自爆！\f威力很强，\n但使用它的宝可梦\v会失去战斗能力！\v小心使用。",
  ["_SilphCo2FSilphWorkerFTM36NoRoomText"] = "你没有空间\n装这个。",
  ["_SilphCo3FRocketAfterBattleText"] = "提示？钥匙卡\n可以打开门！",
  ["_SilphCo3FRocketBattleText"] = "小鬼，别再\n妨碍我们！",
  ["_SilphCo3FRocketEndBattleText"] = "我\n投降！",
  ["_SilphCo3FScientistAfterBattleText"] = "哼……\f火箭队说\n只要我帮忙，\v就让我\v研究宝可梦！",
  ["_SilphCo3FScientistBattleText"] = "比起西尔佛公司，\n我更支持\v火箭队！",
  ["_SilphCo3FScientistEndBattleText"] = "你真把我\n打败了！",
  ["_SilphCo3FSilphWorkerMWhatShouldIDoText"] = "我是西尔佛公司的\n员工。该怎么办？",
  ["_SilphCo3FSilphWorkerMYouSavedUsText"] = "{PLAYER}！你和\n宝可梦\v救了大家！",
  ["_SilphCo4FRocket1AfterBattleText"] = "哇哈哈哈！\n老大一直\v盯着这里！",
  ["_SilphCo4FRocket1BattleText"] = "火箭队已经\n接管西尔佛公司！",
  ["_SilphCo4FRocket1EndBattleText"] = "啊！",
  ["_SilphCo4FRocket2AfterBattleText"] = "我得去11楼\n告诉老大！",
  ["_SilphCo4FRocket2BattleText"] = "发现入侵者！",
  ["_SilphCo4FRocket2EndBattleText"] = "你\n是谁？",
  ["_SilphCo4FScientistAfterBattleText"] = "这些门都是\n电子锁！\v钥匙卡能打开！",
  ["_SilphCo4FScientistBattleText"] = "我的宝可梦是\n忠诚的士兵！",
  ["_SilphCo4FScientistEndBattleText"] = "可恶！\n你们这些弱小的宝可梦！",
  ["_SilphCo4FSilphWorkerMImHidingText"] = "嘘！没看见\n我在躲着吗？",
  ["_SilphCo4FSilphWorkerMTeamRocketIsGoneText"] = "咦？火箭队\n走了？",
  ["_SilphCo5FPokemonReport1Text"] = "这是宝可梦\n报告！\f宝可梦研究所\n创造了多边兽，\v第一只虚拟\v宝可梦。",
  ["_SilphCo5FPokemonReport2Text"] = "这是宝可梦\n报告！\f已经确认\n宝可梦招式\v超过160种。",
  ["_SilphCo5FPokemonReport3Text"] = "这是宝可梦\n报告！\f有4种宝可梦\n只有通过连接线\v交换才会进化。",
  ["_SilphCo5FRockerAfterBattleText"] = "你才到5楼。\n离老大还\v远着呢！",
  ["_SilphCo5FRockerBattleText"] = "什——么？这里\n不该有小孩！",
  ["_SilphCo5FRockerEndBattleText"] = "哎呀！",
  ["_SilphCo5FRocket1AfterBattleText"] = "找火箭队的麻烦\n可不明智！",
  ["_SilphCo5FRocket1BattleText"] = "听说有个小孩\n到处乱晃。",
  ["_SilphCo5FRocket1EndBattleText"] = "砰！",
  ["_SilphCo5FRocket2AfterBattleText"] = "说起来，\f瓦斯弹会进化成\n双弹瓦斯！",
  ["_SilphCo5FRocket2BattleText"] = "给火箭队\n放尊重点！",
  ["_SilphCo5FRocket2EndBattleText"] = "咳……\n咳……",
  ["_SilphCo5FScientistAfterBattleText"] = "我们研发过\n能捕捉任何宝可梦的\v终极精灵球！",
  ["_SilphCo5FScientistBattleText"] = "这一层研究的是\n精灵球技术！",
  ["_SilphCo5FScientistEndBattleText"] = "可恶！\n混账！",
  ["_SilphCo5FSilphWorkerMThatsYouRightText"] = "火箭队正因为\n某个入侵者\v乱成一团。\v就是你吧？",
  ["_SilphCo5FSilphWorkerMYoureOurHeroText"] = "火箭队逃跑了！\n你是我们的\v英雄！谢谢！",
  ["_SilphCo6FRocket1AfterBattleText"] = "不要紧！\n我的兄弟会\v替我报仇！",
  ["_SilphCo6FRocket1BattleText"] = "我是火箭四兄弟\n之一！",
  ["_SilphCo6FRocket1EndBattleText"] = "熄火了！",
  ["_SilphCo6FRocket2AfterBattleText"] = "你若站在\n正义一边，\v就是背叛邪恶！",
  ["_SilphCo6FRocket2BattleText"] = "你竟敢背叛\n火箭队？",
  ["_SilphCo6FRocket2EndBattleText"] = "你这个\n叛徒！",
  ["_SilphCo6FScientistAfterBattleText"] = "季克西分公司？\n那在俄罗斯的\v无人之境！",
  ["_SilphCo6FScientistBattleText"] = "那个混账\n董事长！\f他就不该派我去\n季克西分公司！",
  ["_SilphCo6FScientistEndBattleText"] = "可恶！",
  ["_SilphCo6FSilphWorkerF1HaveToMarryHimText"] = "我太同情他了，\n非得嫁给他不可！",
  ["_SilphCo6FSilphWorkerF1SuchACowardText"] = "看看他！\n真是个胆小鬼！",
  ["_SilphCo6FSilphWorkerF2TeamRocketConquerWorldText"] = "火箭队想\n利用宝可梦\v征服世界！",
  ["_SilphCo6FSilphWorkerF2TeamRocketRanText"] = "火箭队因为你\n逃跑了！",
  ["_SilphCo6FSilphWorkerM1BackToWorkText"] = "好了，该回去\n工作了！",
  ["_SilphCo6FSilphWorkerM1TookOverTheBuildingText"] = "火箭队来了，\n还占领了\v这栋大楼！",
  ["_SilphCo6FSilphWorkerM3TargetedSilphText"] = "他们肯定是看上了\n西尔佛公司的\v宝可梦产品。",
  ["_SilphCo6FSilphWorkerM3WorkForSilphText"] = "你长大后\n来西尔佛公司\v工作吧！",
  ["_SilphCo6FSilphWorkerMHelpMePleaseText"] = "哎呀，哎呀。\n请救救我！",
  ["_SilphCo6FSilphWorkerMWeGotEngagedText"] = "我们订婚了！\n嘿嘿！",
  ["_SilphCo7FRivalDefeatedText"] = "哎呀！\n看来你已经能\v挑战火箭队老大了！",
  ["_SilphCo7FRivalGoodLuckToYouText"] = "好了，{PLAYER}！\f我要继续\n向前走了！\f查看宝可梦图鉴后，\n我逐渐明白\v什么宝可梦强，\v又该如何进化！\f我要去\n宝可梦联盟，\v赶走四天王！\f我会成为\n世界最强的训练家！\f{PLAYER}，祝你\n好运！\v别太紧张！\v回头见！",
  ["_SilphCo7FRivalText"] = "{RIVAL}：怎么\n这么慢，{PLAYER}？",
  ["_SilphCo7FRivalVictoryText"] = "{RIVAL}：该怎么\n说呢？\f你的水平还不够，\n没资格跟\v我们这些高手玩！",
  ["_SilphCo7FRivalWaitedHereText"] = "{RIVAL}：哈哈！\n我就知道在这里\v等着，你会出现！\f看来火箭队\n拖慢了你！\v反正我不在乎！\f我在金黄市\n看见你了，所以\v想来看看\v你有没有进步！",
  ["_SilphCo7FRocket1AfterBattleText"] = "光是到处乱窜，\n可找不到老大！",
  ["_SilphCo7FRocket1BattleText"] = "哈！我闻到了\n小老鼠的味道！",
  ["_SilphCo7FRocket1EndBattleText"] = "眼前\n一黑！",
  ["_SilphCo7FRocket2AfterBattleText"] = "无所谓。\n我的兄弟会\v替我报仇！",
  ["_SilphCo7FRocket2BattleText"] = "我是火箭四兄弟\n之一！",
  ["_SilphCo7FRocket2EndBattleText"] = "啊！\n兄弟们，我输了！",
  ["_SilphCo7FRocket3AfterBattleText"] = "趁老大还没\n发火，快回家！",
  ["_SilphCo7FRocket3BattleText"] = "小孩入侵者？\n一定就是你！",
  ["_SilphCo7FRocket3EndBattleText"] = "好吧！\n我输了！",
  ["_SilphCo7FScientistAfterBattleText"] = "你年纪虽小，\n却是个出色的\v训练家！",
  ["_SilphCo7FScientistBattleText"] = "嘿嘿！\f你把我当成\n西尔佛公司的员工了？",
  ["_SilphCo7FScientistEndBattleText"] = "我\n完了！",
  ["_SilphCo7FSilphWorkerM1HaveThisPokemonText"] = "哦！你好！你\n不是火箭队的人！\v是来救我们的？\v太感谢了！\f为了感谢你，\n我想把这只宝可梦\v送给你。",
  ["_SilphCo7FSilphWorkerM1IsOurPresidentOkText"] = "火箭队老大\n去了董事长室！\v我们的董事长\v没事吧？",
  ["_SilphCo7FSilphWorkerM1LaprasDescriptionText"] = "这是拉普拉斯。\n它非常聪明。\f我们把它留在\n研究所里，但跟着你\v一定会更幸福！\f我觉得你会成为\n拉普拉斯的好训练家！\f它很会游泳，\n能载你一程！",
  ["_SilphCo7FSilphWorkerM1SavedText"] = "终于得救了！\n谢谢你！",
  ["_SilphCo7FSilphWorkerM2AfterTheMasterBallText"] = "火箭队想要\n能捕捉任何宝可梦的\v大师球！",
  ["_SilphCo7FSilphWorkerM2CancelledMasterBallText"] = "因为火箭队，\n我们取消了\v大师球项目。",
  ["_SilphCo7FSilphWorkerM3ItWouldBeBadText"] = "如果火箭队\n接管西尔佛公司，\v甚至抢走宝可梦，\v可就糟了！",
  ["_SilphCo7FSilphWorkerM3YouChasedOffTeamRocketText"] = "哇！你独自\n赶走了火箭队？",
  ["_SilphCo7FSilphWorkerM4ItsReallyDangerousHereText"] = "你！这里真的\n很危险！\v你是来救我的？\v你可办不到！",
  ["_SilphCo7FSilphWorkerM4SafeAtLastText"] = "终于安全了！\n太感谢你！",
  ["_SilphCo8FRocket1AfterBattleText"] = "再不回头，\n我就叫增援！",
  ["_SilphCo8FRocket1BattleText"] = "你只能\n走到这里！",
  ["_SilphCo8FRocket1EndBattleText"] = "还不够\n有种！",
  ["_SilphCo8FRocket2AfterBattleText"] = "接下来交给\n我的兄弟！",
  ["_SilphCo8FRocket2BattleText"] = "我是火箭四兄弟\n之一！",
  ["_SilphCo8FRocket2EndBattleText"] = "呜啊！\n兄弟们！",
  ["_SilphCo8FScientistAfterBattleText"] = "你觉得\n西尔佛大楼的\v迷宫怎么样？",
  ["_SilphCo8FScientistBattleText"] = "你一直在\n给我们添麻烦！",
  ["_SilphCo8FScientistEndBattleText"] = "咦？\n我输了？",
  ["_SilphCo8FSilphWorkerMSilphIsFinishedText"] = "西尔佛公司\n是不是完了……",
  ["_SilphCo8FSilphWorkerMThanksForSavingUsText"] = "谢谢你救了\n大家！",
  ["_SilphCo9FRocket1AfterBattleText"] = "如果我在\n你这个年纪就开始\v当训练家……",
  ["_SilphCo9FRocket1BattleText"] = "小鬼，你的宝可梦\n似乎很喜欢你！",
  ["_SilphCo9FRocket1EndBattleText"] = "呃啊！",
  ["_SilphCo9FRocket2AfterBattleText"] = "兄弟们会\n替我报仇！",
  ["_SilphCo9FRocket2BattleText"] = "我是火箭四兄弟\n之一！",
  ["_SilphCo9FRocket2EndBattleText"] = "呜啊！\n兄弟们，我输了！",
  ["_SilphCo9FScientistAfterBattleText"] = "攻击弱点确实\n有效！\v多想想\v属性克制！",
  ["_SilphCo9FScientistBattleText"] = "你的宝可梦\n有弱点！我能\v精准打击！",
  ["_SilphCo9FScientistEndBattleText"] = "你把我\n打扁了！",
  ["_SilphCoJessieJamesText1"] = "站住，\n小鬼！",
  ["_SilphCoJessieJamesText2"] = "老大正在\n开会！\f你最好别去\n打扰他！",
  ["_SilphCoJessieJamesText3"] = "还是\n老样子……",
  ["_SilphCoJessieJamesText4"] = "火箭队以\n光速飞走了！\f又来了……",
  ["_SkyAttackGlowingText"] = "\n正在发光！",
  ["_SleepingPikachuText1"] = "没有任何\n反应……",
  ["_SleepingPikachuText2"] = "没有任何\n反应……",
  ["_SlowbroDexEntry"] = "懒洋洋地生活在\n海边。如果尾巴上的\n大舌贝脱落，\f它就会重新\n变回呆呆兽",
  ["_SlowpokeDexEntry"] = "慢得难以置信，\n而且行动迟缓。\n它很满足于\f无忧无虑地发呆，\n完全不在意时间",
  ["_SnorlaxDexEntry"] = "无论什么都能吃，\n就算食物有点\n发霉也不例外。\f它的肚子\n从来不会不舒服",
  ["_SoYouWantPrizeText"] = "你想要\n{RAM:wNameBuffer}吗？",
  ["_SorryNeedMoreCoinsText"] = "抱歉，你需要\n更多代币。",
  ["_SpearowDexEntry"] = "不擅长高空飞行。\n不过它能快速地\n四处飞翔，\f借此保护\n自己的领地",
  ["_SquirtleDexEntry"] = "在水中时会\n向猎物喷水。\f遇到危险就\n缩进壳里",
  ["_StarmieDexEntry"] = "中央部分叫作\n核心。它发出\n七色光芒时，\f人们认为它正在\n进行通信",
  ["_StartSlotMachineText"] = "开始！",
  ["_StartedSleepingEffect"] = "{USER}\n进入了睡眠！",
  ["_StaryuDexEntry"] = "只要中央部分\n没有受伤，即使\n身体被切成碎片，\f也能完全\n再生",
  ["_StatusChangesEliminatedText"] = "所有能力变化\n都被消除了！",
  ["_StoppedEvolvingText"] = "咦？{RAM:wStringBuffer}\n停止进化了！",
  ["_StrengthsAndWeaknessesText"] = "所有宝可梦属性\n对其他属性都有\v优势和\v劣势。",
  ["_SubstituteBrokeText"] = "{TARGET}的\n替身破掉了！",
  ["_SubstituteText"] = "它制造了一个\n替身！",
  ["_SubstituteTookDamageText"] = "替身代替\n{TARGET}承受了\v伤害！",
  ["_SuckedHealthText"] = "吸取了\n{TARGET}的体力！",
  ["_SummerBeachHousePikachuText"] = "皮卡丘：皮卡",
  ["_SummerBeachHousePoster1Text1"] = "冲浪达人的\n随笔……\f当我冲进浪管，\n音乐也跟着\v律动起来！",
  ["_SummerBeachHousePoster1Text2"] = "踏浪30年！\n冲浪达人",
  ["_SummerBeachHousePoster2Text1"] = "冲浪技巧1！\f翻转后，让冲浪板\n顺着浪面落下，\v效果超酷！",
  ["_SummerBeachHousePoster2Text2"] = "夏日海滩小屋\n欢迎宝可梦！",
  ["_SummerBeachHousePoster3Text1"] = "冲浪技巧2！\f腾空时做翻转，\n简直酷毙了！",
  ["_SummerBeachHousePoster3Text2"] = "大海让所有人\n因冲浪相连！",
  ["_SummerBeachHousePrinterText1"] = "好像是某种\n机器……",
  ["_SummerBeachHousePrinterText2"] = "上面写着：\n夏日海滩小屋打印机。",
  ["_SummerBeachHousePrinterText3"] = "画面显示了\n最高分。\f要打印吗？",
  ["_SummerBeachHousePrinterText4"] = "上面写着：\n夏日海滩小屋打印机。\f画面显示了\n最高分。\f要打印吗？",
  ["_SummerBeachHousePrinterText5"] = "打印完成。",
  ["_SummerBeachHousePrinterText6"] = "打印错误！",
  ["_SummerBeachHouseSurfinDudeText1"] = "哇！\f你的皮卡丘会\n使用冲浪！看来，\v我不再孤单……\f太棒了！你获得了\n和本达人一起\v冲浪的资格！\f要试试吗？",
  ["_SummerBeachHouseSurfinDudeText2"] = "随时来冲浪吧，\n朋友！",
  ["_SummerBeachHouseSurfinDudeText3"] = "想去冲浪吗？",
  ["_SummerBeachHouseSurfinDudeText4"] = "今天热狗和汉堡\n特价！",
  ["_SuperEffectiveText"] = "效果绝佳！",
  ["_SurfingGotOnText"] = "{PLAYER}骑上了\n{RAM:wNameBuffer}！",
  ["_SurfingNoPlaceToGetOffText"] = "这里没有地方\n可以上岸！",
  ["_SwitchOnText"] = "打开开关！",
  ["_TM21ExplanationText"] = "\f招式学习器21里是\n超级吸取。\f能吸取造成伤害的\n一半，用来恢复\v宝可梦的体力！",
  ["_TM24ExplanationText"] = "\f招式学习器24里是\n十万伏特！\f让电属性宝可梦\n学习吧！",
  ["_TM34ExplanationText"] = "\f招式学习器内含\n可教给宝可梦的\v招式！\f每个只能用一次！\n用它教授新招式时，\v要谨慎选择\v学习的宝可梦！\f招式学习器34里是\n忍耐！\f宝可梦会在对战中\n承受攻击，再\v以双倍伤害奉还！",
  ["_TM46ExplanationText"] = "\f招式学习器46是\n精神波！\v它用强大的\v精神波动造成伤害！",
  ["_TangelaDexEntry"] = "真实样貌隐藏在\n大量粗壮的蓝色\n藤蔓之下。\f据说这些藤蔓\n永远不会停止生长",
  ["_TaurosDexEntry"] = "性情暴躁，\n体力旺盛。\n一旦开始奔跑，\f撞到东西前\n绝不会停下",
  ["_TeachMachineMoveText"] = "里面是\n{RAM:wStringBuffer}！\f要让宝可梦学习\n{RAM:wStringBuffer}吗？",
  ["_TentacoolDexEntry"] = "有时会发现它\n干瘪地躺在\n海滩上。\f把它扔回海里\n就能恢复活力",
  ["_TentacruelDexEntry"] = "80条触手能\n自由伸缩。\f会缠住猎物，\n再用毒素削弱它",
  ["_TextIDErrorText"] = "{NUM:hTextID, 1, 2}错误。",
  ["_Thanks1Text"] = "嘿，谢谢！",
  ["_Thanks2Text"] = "谢谢！",
  ["_Thanks3Text"] = "谢了，朋友！",
  ["_ThrashingAboutText"] = "{USER}\n正在横冲直撞！",
  ["_ThrewAwayItemText"] = "扔掉了\n{RAM:wNameBuffer}。",
  ["_ThrewBaitText"] = "{PLAYER}扔出了\n一些诱饵。",
  ["_ThrewRockText"] = "{PLAYER}扔出了\n石块。",
  ["_ThrowBallAtTrainerMonText1"] = "训练家\n挡住了精灵球！",
  ["_ThrowBallAtTrainerMonText2"] = "不许偷别人的宝可梦！",
  ["_TimesUpText"] = "广播：叮咚！\f时间到！",
  ["_TooImportantToTossText"] = "这个太重要了，\n不能丢弃！",
  ["_TooWeakSubstituteText"] = "体力太少，\n无法制造替身！",
  ["_TookInSunlightText"] = "\n吸收了阳光！",
  ["_TossHowManyText"] = "要丢几个？",
  ["_TownMapText"] = "一张城镇地图。",
  ["_TradeCenterOpponentText"] = "！",
  ["_TradeForText"] = "为了换取{PLAYER}的\n{RAM:wStringBuffer}，",
  ["_TradeSendsText"] = "{RAM:wLinkEnemyTrainerName}派出了\n{RAM:wNameBuffer}。",
  ["_TradeTakeCareText"] = "请好好照顾\n{RAM:wNameBuffer}。",
  ["_TradeTransferredText"] = "{RAM:wNameBuffer}\n已传送。",
  ["_TradeWavesFarewellText"] = "{RAM:wLinkEnemyTrainerName}挥手\n道别，随后",
  ["_TradeWentToText"] = "{RAM:wStringBuffer}来到了\n{RAM:wLinkEnemyTrainerName}身边。",
  ["_TradeWillTradeText"] = "{RAM:wLinkEnemyTrainerName}愿意\n用{RAM:wNameBuffer}",
  ["_TradedForText"] = "{PLAYER}用\n{RAM:wInGameTradeGiveMonName}交换了\v{RAM:wInGameTradeReceiveMonName}！",
  ["_TradeforText"] = "交换{PLAYER}的\n{RAM:wStringBuffer}。",
  ["_TrainerAboutToUseText"] = "{RAM:wTrainerName}即将\n派出\v{RAM:wEnemyMonNick}！\f{PLAYER}要\n替换宝可梦吗？",
  ["_TrainerDefeatedText"] = "{PLAYER}打败了\n{RAM:wTrainerName}！",
  ["_TrainerNameText"] = "{RAM:wNameBuffer}： ",
  ["_TrainerSentOutText"] = "{RAM:wTrainerName}派出了\n{RAM:wEnemyMonNick}！",
  ["_TrainerWantsToFightText"] = "{RAM:wTrainerName}想要\n对战！",
  ["_TransformedText"] = "{USER}\n变成了\v{RAM:wNameBuffer}！",
  ["_TryingToLearnText"] = "{RAM:wLearnMoveMonName}想要\n学习\v{RAM:wStringBuffer}！\f但是，{RAM:wLearnMoveMonName}\n最多只能学会\v4个招式！\f要忘掉一个\n旧招式，腾出空间\v学习{RAM:wStringBuffer}吗？",
  ["_TurnPageText"] = "要翻页吗？",
  ["_TurnedAwayText"] = "{RAM:wBattleMonNick}转过头去，\n不予理睬！",
  ["_TurnedOnPC1Text"] = "{PLAYER}打开了\n电脑。",
  ["_TurnedOnPC2Text"] = "{PLAYER}打开了\n电脑。",
  ["_UnaffectedText"] = "{TARGET}\n没有受到影响！",
  ["_UndergroundPathRoute6GirlText"] = "地下通道里\n常有人丢东西。",
  ["_UndergroundPathRoute7CopyUnusedGirlText"] = "我想去玉虹市的\n百货大楼购物……\f可那里有很多\n看起来很凶的人。",
  ["_UndergroundPathRoute7CopyUnusedGoesUnderSaffronText"] = "地下通道\n从金黄市下方穿过，\v通往紫苑镇。\f要去华蓝市的话，\n就进马路对面的\v建筑。",
  ["_UndergroundPathRoute7CopyUnusedMiddleAgedManText"] = "你来玉虹市\n购物吗？\f出门向西走\n就到了！",
  ["_UndergroundPathRoute7CopyUnusedTeamRocketHadAHideoutText"] = "火箭队在玉虹市\n有秘密基地？",
  ["_UndergroundPathRoute7MiddleAgedManText"] = "听说玉虹市附近\n出现了一只\v嗜睡的宝可梦。",
  ["_UndergroundPathRoute8GirlText"] = "玉虹市的百货大楼\n商品非常齐全！",
  ["_UnleashedEnergyText"] = "{USER}\n释放了能量！",
  ["_UnusedBenchGuyText1"] = "真希望我也能\n捕捉宝可梦。",
  ["_UnusedBenchGuyText2"] = "玩得太久，\n好累……",
  ["_UnusedBenchGuyText3"] = "西尔佛公司的经理\n躲在野生原野区。",
  ["_UnveiledGhostText"] = "西尔佛检视镜\n识破了\v幽灵的真面目！",
  ["_UseNextMonText"] = "要使用下一只\n宝可梦吗？",
  ["_UsedCutText"] = "{RAM:wNameBuffer}使出居合斩，\n砍掉了障碍！",
  ["_UsedInsteadText"] = "改用\v",
  ["_UsedMove1Text"] = "\n使出了",
  ["_UsedMove2Text"] = "\n使出了",
  ["_UsedStrengthText"] = "{RAM:wNameBuffer}使用了\n怪力。",
  ["_VaporeonDexEntry"] = "细胞结构与\n水分子相似。\f它会融入水中，\n变得无影无踪",
  ["_VendingMachineText1"] = "自动售货机！\n这是商品菜单！",
  ["_VendingMachineText4"] = "糟糕，钱不够！",
  ["_VendingMachineText5"] = "{RAM:wStringBuffer}\n掉了出来！",
  ["_VendingMachineText6"] = "没有空间\n装更多东西！",
  ["_VendingMachineText7"] = "现在不渴！",
  ["_VenomothDexEntry"] = "翅膀上的粉状\n鳞片很难去除。\f接触后还会渗出\n其中的毒素",
  ["_VenonatDexEntry"] = "大眼睛如同\n雷达。在明亮处，\f可以看出它们\n由许多小眼睛组成",
  ["_VenusaurDexEntry"] = "背上的花朵\n会接收阳光。\f随后吸收阳光，\n转化为能量",
  ["_VermilionCityBeautyText"] = "我们很重视\n污染问题！\f听说臭泥会在\n有毒污泥中繁殖！",
  ["_VermilionCityGambler1DidYouSeeText"] = "你看到\n停靠在港口的\v圣特安努号了吗？",
  ["_VermilionCityGambler1SSAnneDepartedText"] = "原来圣特安努号\n已经出发了！\f大约一年后\n还会回来。",
  ["_VermilionCityGambler2Text"] = "我要在这块地上\n盖一栋楼。\f我的宝可梦正在\n夯实地面。",
  ["_VermilionCityGymSignText"] = "枯叶市\n宝可梦道馆\v馆主：马志士\f闪电般的\n美国人！",
  ["_VermilionCityHarborSignText"] = "枯叶港",
  ["_VermilionCityMachopStompingTheLandFlatText"] = "\f一只腕力正在\n把地面踩平。",
  ["_VermilionCityMachopText"] = "腕力：咕哦！\n咕咕咕哦！",
  ["_VermilionCityNoticeSignText"] = "通知！\f12号道路可能被\n沉睡的宝可梦\v堵住了。\f请绕行\n岩山隧道前往\v紫苑镇。\f枯叶警察局",
  ["_VermilionCityPokemonFanClubSignText"] = "宝可梦发烧友俱乐部\n欢迎所有宝可梦迷！",
  ["_VermilionCitySailor1DoYouHaveATicketText"] = "欢迎登上\n圣特安努号！\f请问你\n有船票吗？",
  ["_VermilionCitySailor1FlashedTicketText"] = "{PLAYER}出示了\n船票！\f很好！欢迎登上\n圣特安努号！",
  ["_VermilionCitySailor1ShipSetSailText"] = "船已经启航。",
  ["_VermilionCitySailor1WelcomeToSSAnneText"] = "欢迎登上\n圣特安努号！",
  ["_VermilionCitySailor1YouNeedATicketText"] = "{PLAYER}没有\n所需的\v船票。\f抱歉！\f你需要船票\n才能上船。",
  ["_VermilionCitySailor2Text"] = "圣特安努号是\n著名的豪华邮轮。\f每年会造访\n枯叶市一次。",
  ["_VermilionCitySignText"] = "枯叶市\n夕阳绚丽的\v港口城市",
  ["_VermilionDockUnusedText"] = "（未使用）",
  ["_VermilionGymGentlemanAfterBattleText"] = "门打不开？\f马志士一直\n这么谨慎！",
  ["_VermilionGymGentlemanBattleText"] = "我在军队服役时，\n马志士是我\v严厉的长官！",
  ["_VermilionGymGentlemanEndBattleText"] = "停！\n你很厉害！",
  ["_VermilionGymGymGuideBeatLTSurgeText"] = "呼！真是一场\n电光四射的对战！",
  ["_VermilionGymGymGuideChampInMakingText"] = "哟！未来的\n冠军！\f马志士有个外号。\n人们称他为\v闪电般的\v美国人！\f他是电属性宝可梦\n专家！\f飞行和水属性\n宝可梦会很吃亏！\v也要小心麻痹！\f马志士非常\n谨慎！\f你必须解开机关\n才能见到他！",
  ["_VermilionGymLTSurgePostBattleAdviceText"] = "小鬼，给你\n一句忠告！\f电力确实\n威力强大！\f但对地面属性\n宝可梦毫无作用！",
  ["_VermilionGymLTSurgePreBattleText"] = "立正！欢迎来到\n枯叶道馆！\f瞧瞧，一个\n小不点挑战者！\f哈哈哈！你力量\n这么弱小，却有胆量\v来挑战我！\f宝可梦对战\n就是战争！\v我来让你见识，\v平民！\f我会电到你\n投降！",
  ["_VermilionGymLTSurgeReceivedTM24Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_VermilionGymLTSurgeReceivedThunderBadgeText"] = "哇！\f小鬼，你果然\n有真本事！\f好吧，拿走\n橙色徽章！",
  ["_VermilionGymLTSurgeTM24NoRoomText"] = "喂，小鬼，\n给背包腾点空间！",
  ["_VermilionGymLTSurgeThunderBadgeInfoText"] = "橙色徽章能\n提高宝可梦的\v速度！\f还让宝可梦\n随时都能使用\v飞翔，小鬼！\f你很特别，\n小鬼！拿着这个！",
  ["_VermilionGymSailorAfterBattleText"] = "马志士设置了\n两道锁！\v给你个提示！\f打开第一道锁后，\n第二道锁就在\v它旁边！",
  ["_VermilionGymSailorBattleText"] = "这里不是\n小孩该来的地方！",
  ["_VermilionGymSailorEndBattleText"] = "哇！\n吓我一跳！",
  ["_VermilionGymSuperNerdAfterBattleText"] = "好吧，我告诉你！\f马志士说他把\n门锁开关藏在\v某种东西里面！",
  ["_VermilionGymSuperNerdBattleText"] = "我体格不强，\n但很懂电！",
  ["_VermilionGymSuperNerdEndBattleText"] = "被电焦了！",
  ["_VermilionGymTrashFailText"] = "不对！这里只\n有垃圾。\v喂！电子锁\v重置了！",
  ["_VermilionGymTrashSuccessText1"] = "嘿！垃圾下面\n有个开关！\v把它打开！\f第一道电子锁\n打开了！",
  ["_VermilionGymTrashSuccessText2"] = "嘿！垃圾下面\n还有一个开关！\v把它打开！",
  ["_VermilionGymTrashSuccessText3"] = "第二道电子锁\n打开了！\f电动门\n打开了！",
  ["_VermilionGymTrashText"] = "不对，这里\n只有垃圾。",
  ["_VermilionMartCooltrainerFText"] = "我觉得宝可梦\n也有善恶，\v关键在于训练家。",
  ["_VermilionMartCooltrainerMText"] = "有些坏人会\n利用宝可梦\v进行犯罪。\f火箭队会贩卖\n稀有宝可梦。\f他们还会抛弃\n不够受欢迎或\v没有利用价值的\v宝可梦。",
  ["_VermilionOldRodHouseFishingGuruDoYouLikeToFishText"] = "我是钓鱼\n大师！\f我最最最喜欢\n钓鱼！\f你喜欢\n钓鱼吗？",
  ["_VermilionOldRodHouseFishingGuruFishingIsAWayOfLifeText"] = "\f钓鱼就是\n一种生活方式！\f无论大海还是河流，\n都去钓条大鱼吧，\v年轻人！",
  ["_VermilionOldRodHouseFishingGuruHowAreTheFishBitingText"] = "你好，\n{PLAYER}！\f最近鱼\n咬钩吗？",
  ["_VermilionOldRodHouseFishingGuruNoRoomText"] = "糟了！\f你的背包没空间\n装我的礼物！",
  ["_VermilionOldRodHouseFishingGuruTakeThisText"] = "太好了！我喜欢\n你的作风！\f年轻人，拿上这个\n去钓鱼吧！\f{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_VermilionOldRodHouseFishingGuruThatsSoDisappointingText"] = "唉……真让人\n失望……",
  ["_VermilionPidgeyHouseLetterText"] = "亲爱的皮皮，希望\n能尽快见到你。\f听说金黄市\n正受火箭队侵扰。\f枯叶市这里\n似乎很安全。",
  ["_VermilionPidgeyHousePidgeyText"] = "波波：咕噜咕！",
  ["_VermilionPidgeyHouseYoungsterText"] = "我让波波把\n信送到北边的\v金黄市！",
  ["_VermilionPokecenterFishingGuruText"] = "即使等级相同，\n宝可梦的能力也可能\v差异很大。\f训练家培育的\n宝可梦比野生的\v更强。",
  ["_VermilionPokecenterGuyText"] = "等级更高的宝可梦\n确实会更强……\f但每种宝可梦\n面对特定属性\v都会有弱点。\f所以不存在\n无敌的宝可梦。",
  ["_VermilionPokecenterSailorText"] = "我的宝可梦\n中毒了！走着走着\v就失去了\v战斗能力！",
  ["_VictoryRoad1FCooltrainerFAfterBattleText"] = "我从来不想\n输给任何人！",
  ["_VictoryRoad1FCooltrainerFBattleText"] = "不知道你有没有\n资格跟我对战！",
  ["_VictoryRoad1FCooltrainerFEndBattleText"] = "我\n输了！",
  ["_VictoryRoad1FCooltrainerMAfterBattleText"] = "我认输，\n你比我厉害！",
  ["_VictoryRoad1FCooltrainerMBattleText"] = "看得出你很强！\n让我看看\v究竟有多强！",
  ["_VictoryRoad1FCooltrainerMEndBattleText"] = "我本来\n有机会……",
  ["_VictoryRoad2FCooltrainerMAfterBattleText"] = "你有资格\n踏上冠军之路！",
  ["_VictoryRoad2FCooltrainerMBattleText"] = "来吧！\n我会击败你！",
  ["_VictoryRoad2FCooltrainerMEndBattleText"] = "我被\n击败了！",
  ["_VictoryRoad2FHikerAfterBattleText"] = "如果被困住，\n试着移动一些\v巨石！",
  ["_VictoryRoad2FHikerBattleText"] = "冠军之路是\n训练家的最终\v考验！",
  ["_VictoryRoad2FHikerEndBattleText"] = "哎呀！",
  ["_VictoryRoad2FMoltresBattleText"] = "嘎嗷！",
  ["_VictoryRoad2FSuperNerd1AfterBattleText"] = "{RIVAL}也从\n这里通过了！",
  ["_VictoryRoad2FSuperNerd1BattleText"] = "哦，你想\n挑战四天王吗？",
  ["_VictoryRoad2FSuperNerd1EndBattleText"] = "被你\n拿下了！",
  ["_VictoryRoad2FSuperNerd2AfterBattleText"] = "论宝可梦知识，\n我能打败你！",
  ["_VictoryRoad2FSuperNerd2BattleText"] = "只要通过这里，\n就能去见\v四天王！",
  ["_VictoryRoad2FSuperNerd2EndBattleText"] = "不！\n难以置信！",
  ["_VictoryRoad2FSuperNerd3AfterBattleText"] = "很多训练家在\n这里放弃了挑战。",
  ["_VictoryRoad2FSuperNerd3BattleText"] = "冠军之路\n太难了吗？",
  ["_VictoryRoad2FSuperNerd3EndBattleText"] = "干得\n漂亮！",
  ["_VictoryRoad3FCooltrainerF1AfterBattleText"] = "你让我看清了\n自己的实力！",
  ["_VictoryRoad3FCooltrainerF1BattleText"] = "我会让你看看\n自己的实力！",
  ["_VictoryRoad3FCooltrainerF1EndBattleText"] = "我\n气坏了！",
  ["_VictoryRoad3FCooltrainerF2AfterBattleText"] = "经过艰苦的\n对战，你会\v变得更强！",
  ["_VictoryRoad3FCooltrainerF2BattleText"] = "训练家活着就是\n为了寻找更强的\v对手！",
  ["_VictoryRoad3FCooltrainerF2EndBattleText"] = "哦！\n真强！",
  ["_VictoryRoad3FCooltrainerM1AfterBattleText"] = "你打败了\n火箭队的坂木？",
  ["_VictoryRoad3FCooltrainerM1BattleText"] = "听说有个\n天才小孩！",
  ["_VictoryRoad3FCooltrainerM1EndBattleText"] = "传闻\n是真的！",
  ["_VictoryRoad3FCooltrainerM2AfterBattleText"] = "这里所有训练家\n都要去\v宝可梦联盟！\v小心点！",
  ["_VictoryRoad3FCooltrainerM2BattleText"] = "只有被选中的人\n才能通过！",
  ["_VictoryRoad3FCooltrainerM2EndBattleText"] = "我\n不敢相信！",
  ["_VictreebelDexEntry"] = "用蜂蜜般的\n甜香引诱猎物。\n猎物被整个吞下后，\f一天内连骨头\n都会被溶解",
  ["_VileplumeDexEntry"] = "扇动宽大的\n花瓣，散播\n有毒花粉。\f扇动时会发出\n很大的声音",
  ["_ViridianBlackboardBurnText"] = "灼伤会降低\n力量和速度，\v还会持续造成伤害。\f对战结束后\n灼伤仍会保留。\f使用灼伤药\n治愈灼伤！",
  ["_ViridianBlackboardFrozenText"] = "冰冻后，宝可梦\n完全无法行动！\f即使对战结束，\n冰冻仍会保留。\f使用解冻药\n为宝可梦解冻！",
  ["_ViridianBlackboardPoisonText"] = "中毒后，宝可梦的\n体力会不断减少。\f对战结束后\n中毒仍会保留。\f使用解毒药\n治愈中毒！",
  ["_ViridianBlackboardPrlzText"] = "麻痹可能让\n宝可梦的招式\v无法使出！\f对战结束后\n麻痹仍会保留。\f使用解麻药\n治疗！",
  ["_ViridianBlackboardSleepText"] = "宝可梦睡着时\n无法攻击！\f即使对战结束，\n宝可梦仍会睡着。\f使用解眠药\n唤醒它们！",
  ["_ViridianCityFisherReceivedTM42Text"] = "{PLAYER}获得了\n招式学习器42！",
  ["_ViridianCityFisherTM42ExplanationText"] = "招式学习器42里是\n食梦……\v……呼噜……",
  ["_ViridianCityFisherTM42NoRoomText"] = "你带的东西太多了。",
  ["_ViridianCityGambler1GymAlwaysClosedText"] = "这座宝可梦道馆\n总是关着门。\f馆主到底是谁呢？",
  ["_ViridianCityGambler1GymLeaderReturnedText"] = "常青道馆的\n馆主回来了！",
  ["_ViridianCityGirlHasntHadHisCoffeeYetText"] = "哎呀，爷爷！别这么凶！\v他还没喝咖啡呢。",
  ["_ViridianCityGirlWhenIGoShopText"] = "我去深灰市买东西时，\n必须走常青森林里\v弯弯曲曲的小路。",
  ["_ViridianCityGymLockedText"] = "道馆的门锁着……",
  ["_ViridianCityGymSignText"] = "常青市\n宝可梦道馆",
  ["_ViridianCityOldManHadMyCoffeeNowText"] = "啊，喝完咖啡，\n精神多了！\f你可以过去了！\f刚才对你那么无礼，\n真是对不起！\f你在用宝可梦图鉴吧？\f就当赔礼，\n我来示范怎样\v收服宝可梦。",
  ["_ViridianCityOldManLosingMyTouchText"] = "居然失败了！\n看来我的技术\v退步了。\f精灵球也用光了。\f我得去友好商店\n买一些。",
  ["_ViridianCityOldManNotGoodEnoughForYouText"] = "哦……看来我还\n不够资格教你。",
  ["_ViridianCityOldManSleepyPrivatePropertyText"] = "这里不能通行！\f这是私人领地！",
  ["_ViridianCityOldManWantMeToShowYouAgainText"] = "嗯？你还想让我\n再示范一次\v怎样收服宝可梦吗？",
  ["_ViridianCityOldManWatchCloselyText"] = "好！\n现在仔细看\v我是怎么做的！",
  ["_ViridianCityOldManYouNeedToWeakenTheTargetText"] = "首先，要先削弱\n目标宝可梦。",
  ["_ViridianCityPokecenterGuyText"] = "宝可梦中心能让\n疲惫、受伤或昏厥的\v宝可梦恢复精神！",
  ["_ViridianCitySignText"] = "常青市\n常青葱郁的乐园",
  ["_ViridianCityTrainerTips1Text"] = "训练家提示\f收服宝可梦，\n扩充你的伙伴阵容！\f伙伴越多，\n对战就越轻松！",
  ["_ViridianCityTrainerTips2Text"] = "训练家提示\f宝可梦的招式受到\n招式点数PP的限制。\f去宝可梦中心休息，\n就能恢复PP！",
  ["_ViridianCityYoungster1Text"] = "你腰间的是精灵球！\n你有宝可梦！\f无论何时何地\n都能带着宝可梦，\v真方便啊！",
  ["_ViridianCityYoungster2YouWantToKnowAboutText"] = "想了解两种\n毛毛虫宝可梦吗？",
  ["_ViridianForestCooltrainerFAfterBattleText"] = "我找了好久，\n却没在这里找到\v皮卡丘！",
  ["_ViridianForestCooltrainerFBattleText"] = "你好，你有\n皮卡丘吗？",
  ["_ViridianForestCooltrainerFEndBattleText"] = "不会吧，\n真的吗？",
  ["_ViridianForestLeavingSignText"] = "即将离开\n常青森林\v前方是深灰市",
  ["_ViridianForestNorthGateGrampsText"] = "你注意到路边的\n小树了吗？\f用某种特殊的\n宝可梦招式\v就能砍掉它们。",
  ["_ViridianForestNorthGateSuperNerdText"] = "许多宝可梦只生活在\n森林和洞窟里。\f想找到不同种类，\n就得四处搜寻！",
  ["_ViridianForestSouthGateGirlText"] = "你要去常青森林吗？\n小心，那里是个\v天然迷宫！",
  ["_ViridianForestSouthGateLittleGirlText"] = "要到很远的地方，\n才能找到新种类的\v宝可梦。\f常青森林外面\n还有其他种类的\v宝可梦。",
  ["_ViridianForestTrainerTips1Text"] = "训练家提示\f想避开对战，\n就离草丛远一点！",
  ["_ViridianForestTrainerTips2Text"] = "训练家提示\f用电脑联系大木博士，\n请他评价你的\v宝可梦图鉴！",
  ["_ViridianForestTrainerTips3Text"] = "训练家提示\f不许偷走其他训练家的\n宝可梦！\v只能收服\v野生宝可梦！",
  ["_ViridianForestTrainerTips4Text"] = "训练家提示\f先削弱宝可梦，\n再尝试收服！\f体力充足时，\n它们可能会逃走！",
  ["_ViridianForestUseAntidoteSignText"] = "中毒时用解毒药！\n友好商店就有卖！",
  ["_ViridianForestYoungster1Text"] = "我和朋友们一起来的！\f他们都去找人\n进行宝可梦对战！",
  ["_ViridianForestYoungster2AfterBattleText"] = "嘘！你会把虫子\n吓跑的！",
  ["_ViridianForestYoungster2BattleText"] = "嘿！你有宝可梦！\n来吧！\v我们来对战！",
  ["_ViridianForestYoungster2EndBattleText"] = "不！\n绿毛虫不行啊！",
  ["_ViridianForestYoungster3AfterBattleText"] = "可恶！我要去抓\n更强的宝可梦！",
  ["_ViridianForestYoungster3BattleText"] = "喂！既然是\n宝可梦训练家，\v就别想躲开对战！",
  ["_ViridianForestYoungster3EndBattleText"] = "咦？\n我的宝可梦\v全倒下了！",
  ["_ViridianForestYoungster4AfterBattleText"] = "有时能在地上\n捡到东西！\f我正在找\n自己弄丢的东西！",
  ["_ViridianForestYoungster4BattleText"] = "喂，等一下！\n急什么？",
  ["_ViridianForestYoungster4EndBattleText"] = "我认输！\n你很厉害！",
  ["_ViridianForestYoungster5AfterBattleText"] = "铁甲蛹很棒，\n它的攻击方式\v就是防御！",
  ["_ViridianForestYoungster5BattleText"] = "我要成为最强的！\n你赢不了我！",
  ["_ViridianForestYoungster5EndBattleText"] = "我明明\n那么努力……",
  ["_ViridianForestYoungster6Text"] = "我的精灵球用光了，\n没法收服宝可梦！\f你最好多带一些！",
  ["_ViridianGymCooltrainerM1AfterBattleText"] = "想跟上我们的\n道馆馆主，你需要\v实力！",
  ["_ViridianGymCooltrainerM1BattleText"] = "嘿！你现在\n一定快没力气了！",
  ["_ViridianGymCooltrainerM1EndBattleText"] = "我\n没劲了！",
  ["_ViridianGymCooltrainerM2AfterBattleText"] = "馆主会\n训斥我！",
  ["_ViridianGymCooltrainerM2BattleText"] = "真正有天分的人\n会赢得漂亮！",
  ["_ViridianGymCooltrainerM2EndBattleText"] = "我\n失手了！",
  ["_ViridianGymCooltrainerM3AfterBattleText"] = "只有打败我们的\n道馆馆主，才能前往\v宝可梦联盟！",
  ["_ViridianGymCooltrainerM3BattleText"] = "常青道馆关闭了\n很久，但现在\v馆主回来了！",
  ["_ViridianGymCooltrainerM3EndBattleText"] = "我竟然\n被打败了？",
  ["_ViridianGymGiovanniEarthBadgeInfoText"] = "绿色徽章能让\n任何等级的宝可梦\v听从指挥！\f它证明你已是\n顶尖的宝可梦训练家！\f有了它，就能\n进入宝可梦联盟！\f这是送给你挑战\n宝可梦联盟的礼物！",
  ["_ViridianGymGiovanniPostBattleAdviceText"] = "输掉对战后，\n我无颜面对\v手下！\v火箭队\v从此彻底解散！\f我将毕生投入\n宝可梦训练！\f希望有一天\n还能再见！\v告辞！",
  ["_ViridianGymGiovanniPreBattleText"] = "哇哈哈哈！这里是\n我的藏身处！\f我原本打算在这里\n重建火箭队！\f但又被你\n找到了！\v也罢！这一次，\v我不会手下留情！\f再来面对一次\n最强训练家\v坂木吧！",
  ["_ViridianGymGiovanniReceivedEarthBadgeText"] = "哈！\n真是一场\v激烈的对战！\v你赢了！\v作为胜利的证明，\v这枚绿色徽章给你！",
  ["_ViridianGymGiovanniReceivedTM27Text"] = "{PLAYER}获得了\n招式学习器27！",
  ["_ViridianGymGiovanniTM27ExplanationText"] = "\f招式学习器27是\n地裂！\v只需一击就能\v打倒宝可梦！\f这是很久以前，\n我担任这里的馆主时\v制作的……",
  ["_ViridianGymGiovanniTM27NoRoomText"] = "你没有空间\n装这个！",
  ["_ViridianGymGuidePostBattleText"] = "真让人吃惊！\n坂木竟然是这里的\v道馆馆主？",
  ["_ViridianGymGuidePreBattleText"] = "哟！未来的\n冠军！\f连我也不知道\n常青道馆馆主的\v身份！\f他会是所有\n道馆馆主中\v最强的一位！\f听说这里的训练家\n喜欢地面属性\v宝可梦！",
  ["_ViridianGymHiker1AfterBattleText"] = "我还\n不够格！",
  ["_ViridianGymHiker1BattleText"] = "吼！我要让自己\n愤怒起来！",
  ["_ViridianGymHiker1EndBattleText"] = "呜啊！",
  ["_ViridianGymHiker2AfterBattleText"] = "要是我的宝可梦\n也像我一样\v擅长空手道……",
  ["_ViridianGymHiker2BattleText"] = "空手道是\n最强的武术！",
  ["_ViridianGymHiker2EndBattleText"] = "啊哒！",
  ["_ViridianGymHiker3AfterBattleText"] = "宝可梦联盟？\n就凭你？别\v得意忘形！",
  ["_ViridianGymHiker3BattleText"] = "我是空手道之王！\n你的命运\v由我决定！",
  ["_ViridianGymHiker3EndBattleText"] = "呀！",
  ["_ViridianGymRocker1AfterBattleText"] = "你知道我们的\n道馆馆主是谁吗？",
  ["_ViridianGymRocker1BattleText"] = "宝可梦和我\n能共同奏出\v美妙的音乐！",
  ["_ViridianGymRocker1EndBattleText"] = "你们配合得\n天衣无缝！",
  ["_ViridianGymRocker2AfterBattleText"] = "等等！我只是\n大意了！",
  ["_ViridianGymRocker2BattleText"] = "鞭子一响，\n你的宝可梦就会\v吓得发抖！",
  ["_ViridianGymRocker2EndBattleText"] = "嗷！\n鞭子抽到我了！",
  ["_ViridianMartClerkParcelQuestText"] = "你认识大木博士吧？\f他订的货到了。\n能帮忙带给他吗？\f{PLAYER}获得了\n大木博士的包裹！",
  ["_ViridianMartClerkSayHiToOakText"] = "好！替我向大木博士问好！",
  ["_ViridianMartClerkYouCameFromPalletTownText"] = "喂！你是从真新镇来的？",
  ["_ViridianMartCooltrainerMText"] = "店里终于补到\n伤药了。",
  ["_ViridianMartYoungsterText"] = "这家店卖很多\n解麻药。",
  ["_ViridianNicknameHouseBaldingGuyText"] = "给宝可梦起昵称\n很有趣，却也很难。\f简单的名字\n最容易记住。",
  ["_ViridianNicknameHouseLittleGirlText"] = "我爸爸也很喜欢\n宝可梦。",
  ["_ViridianNicknameHouseSpearowText"] = "小烈：啾啾！",
  ["_ViridianNicknameHouseSpearySignText"] = "烈雀\n名字：小烈",
  ["_ViridianPokecenterCooltrainerMText"] = "之后每座城镇都有\n宝可梦中心。\f而且完全免费！",
  ["_ViridianPokecenterGentlemanText"] = "你可以使用角落里的电脑。\f是接待员告诉我的。\n她真亲切！",
  ["_ViridianSchoolBlackboardText1"] = "黑板上写着\n宝可梦在对战中的\v异常状态。",
  ["_ViridianSchoolBlackboardText2"] = "你想看哪个标题？",
  ["_ViridianSchoolHouseBrunetteGirlText"] = "呼！我在努力\n背下所有笔记。",
  ["_ViridianSchoolHouseCooltrainerFText"] = "好！\f一定要认真\n阅读黑板！",
  ["_ViridianSchoolHouseLittleGirlText"] = "姐姐说，只要\n善待宝可梦，\v它们就会变乖。",
  ["_ViridianSchoolNotebookText1"] = "查看了\n笔记本！\f第一页……\f精灵球用于\n捕捉宝可梦。\f最多可携带\n6只宝可梦。\f培育宝可梦并\n让它们对战的人，\v被称为\v宝可梦训练家。",
  ["_ViridianSchoolNotebookText2"] = "第二页……\f健康的宝可梦\n很难捕捉，\v要先削弱它！\f中毒、灼伤等\n异常状态很有效！",
  ["_ViridianSchoolNotebookText3"] = "第三页……\f宝可梦训练家\n会寻找其他人\v进行宝可梦\v对战。\f宝可梦道馆中\n经常有人对战。",
  ["_ViridianSchoolNotebookText4"] = "第四页……\f宝可梦训练家的目标\n是打败\v最顶尖的8位\v道馆馆主。\f完成后就能获得\n挑战……\f宝可梦联盟\n四天王的资格！",
  ["_ViridianSchoolNotebookText5"] = "女孩：喂！别看\n我的笔记！",
  ["_VitaminNoEffectText"] = "不会有效果。",
  ["_VitaminStatRoseText"] = "{RAM:wNameBuffer}的\n{RAM:wStringBuffer}提高了。",
  ["_VoltorbDexEntry"] = "据说会伪装成\n精灵球。\n即使受到很小的刺激，\f也会自爆",
  ["_VulpixDexEntry"] = "毛发和尾巴\n都很美丽。\n随着成长，尾巴会\f不断分叉，\n数量也会增加",
  ["_WannaTrade1Text"] = "我在寻找\n{RAM:wInGameTradeGiveMonName}！\f愿意用它交换\n{RAM:wInGameTradeReceiveMonName}吗？",
  ["_WannaTrade2Text"] = "你好！你愿意用\n{RAM:wInGameTradeGiveMonName}\f交换\n{RAM:wInGameTradeReceiveMonName}吗？",
  ["_WannaTrade3Text"] = "嗨！你有\n{RAM:wInGameTradeGiveMonName}吗？\f愿意用它\n交换{RAM:wInGameTradeReceiveMonName}吗？",
  ["_WardensHouseDisplayMerchandiseText"] = "古老的宝可梦\n周边商品。",
  ["_WardensHouseDisplayPhotosAndFossilsText"] = "宝可梦的照片\n和化石。",
  ["_WardensHouseWardenGaveTheGoldTeethText"] = "{PLAYER}把\n金假牙交给了\v园长！",
  ["_WardensHouseWardenGibberish1Text"] = "园长：泥好，\n窝硕不清楚！\f窝的假牙\n不见了。帮\v窝找回来！",
  ["_WardensHouseWardenGibberish2Text"] = "啊，泥听懂了！\n请帮窝找假牙！",
  ["_WardensHouseWardenGibberish3Text"] = "啥？泥不愿意\n帮窝找假牙！",
  ["_WardensHouseWardenHM04ExplanationText"] = "园长：秘传学习器04\n能教会宝可梦怪力！\f它让宝可梦\n在对战外也能\v推动巨石。\f对了，你找到\n野生原野区的\v秘密小屋了吗？\f找到就能\n赢得秘传学习器！\f听说是稀有的\n冲浪秘传学习器。",
  ["_WardensHouseWardenHM04NoRoomText"] = "背包塞满了！",
  ["_WardensHouseWardenReceivedHM04Text"] = "{PLAYER}获得了\n{RAM:wStringBuffer}！",
  ["_WardensHouseWardenTeethPoppedInHisTeethText"] = "\f园长装上了\n假牙！",
  ["_WardensHouseWardenThanksText"] = "园长：谢谢你，\n小鬼！以前没人\v听得懂我说什么。\f那样根本没法\n工作。\v送你点东西，\v感谢你帮忙。",
  ["_WarpToLastPokemonCenterText"] = "传送到上次去过的\n宝可梦中心。",
  ["_WartortleDexEntry"] = "受到敲击时，\n会把头缩进去，\f但尾巴仍会\n稍微露在外面",
  ["_WasBlownAwayText"] = "{TARGET}\n被吹飞了！",
  ["_WasSeededText"] = "{TARGET}\n被种下了种子！",
  ["_WeedleDexEntry"] = "小心头上的\n尖锐毒针。\n它藏在草地和灌木中，\f以树叶为食",
  ["_WeepinbellDexEntry"] = "饥饿时会吞下\n任何会动的东西。\f倒霉的猎物会在体内\n被强酸溶解",
  ["_WeezingDexEntry"] = "通过吸收\n有毒废料和垃圾中的\n灰尘、细菌与毒气，\f维持生命并成长",
  ["_WhatDoYouWantText"] = "你想做什么？",
  ["_WhatGoesAroundComesAroundText"] = "善有善报，\n恶有恶报！",
  ["_WhatText"] = "什么？",
  ["_WhatToDepositText"] = "要存放什么？",
  ["_WhatToTossText"] = "要丢弃什么？",
  ["_WhatToWithdrawText"] = "要取出什么？",
  ["_WhenYouChangeBoxText"] = "更换宝可梦盒子时\n会保存数据。\f可以吗？",
  ["_WhichFloorText"] = "想去几楼？",
  ["_WhichMoveToForgetText"] = "要忘记哪个\n招式？",
  ["_WhichPrizeText"] = "想要哪个\n奖品？",
  ["_WigglytuffDexEntry"] = "身体充满弹性。\n只要深深吸气，\f就能不断膨胀，\n似乎没有极限",
  ["_WildMonAppearedText"] = "野生的{RAM:wEnemyMonNick}\n出现了！",
  ["_WildRanText"] = "野生的{RAM:wEnemyMonNick}\n逃走了！",
  ["_WillBeTradedText"] = "{RAM:wNameOfPlayerMonToBeTraded}和\n{RAM:wNameBuffer}即将\v进行交换。",
  ["_WithExpAllText"] = "通过学习装置，\v",
  ["_WithdrawHowManyText"] = "要取出几个？",
  ["_WithdrewItemText"] = "取出了\n{RAM:wNameBuffer}。",
  ["_WokeUpText"] = "{USER}\n醒来了！",
  ["_WontObeyText"] = "{RAM:wBattleMonNick}不肯\n听从命令！",
  ["_WouldYouLikeToSaveText"] = "要记录\n游戏吗？",
  ["_WrongMon1Text"] = "什么？这不是\n{RAM:wInGameTradeGiveMonName}！\f等你有一只时，\n再回来！",
  ["_WrongMon2Text"] = "嗯？这不是\n{RAM:wInGameTradeGiveMonName}。\f等你有一只时\n别忘了我。",
  ["_WrongMon3Text"] = "……这不是\n{RAM:wInGameTradeGiveMonName}。\f等你有一只，\n就跟我交换吧！",
  ["_YeahText"] = "好耶！",
  ["_YourNameIsText"] = "对！那么你的\n名字是{PLAYER}！",
  ["_ZapdosDexEntry"] = "据说当天空变暗，\n雷电不断落下时，\f这只传说的\n鸟宝可梦就会现身",
  ["_ZubatDexEntry"] = "飞行时会发出\n超声波叫声。\f这些声音如同声呐，\n用于探测前方障碍",

  ["_SafariZoneLowCostText4"] = "（未使用）",
}
